  ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);

  int n; cin >> n;
  vector<int> a(n);
  for (auto& x : a) cin >> x;

  map<int, int> cnt;
  for (int i = 0; i < n; i += 2) {
    cnt[a[i]]++;
  }
  vector<pair<int, int>> odd;
  for (auto& x : cnt) {
    odd.push_back({ x.second, x.first });
  }
  cnt.clear();
  for (int i = 1; i < n; i += 2) {
    cnt[a[i]]++;
  }
  vector<pair<int, int>> even;
  for (auto& x : cnt) {
    even.push_back({ x.second, x.first });
  }
  sort(odd.rbegin(), odd.rend());
  sort(even.rbegin(), even.rend());
  if (odd[0].second != even[0].second) {
    cout << n - odd[0].first - even[0].first << "\n";
  } else if (odd.size() >= 2 && even.size() >= 2) {
    int ans = n - min(odd[0].first + even[1].first, odd[1].first + even[0].first);
    cout << ans << "\n";
  } else if (odd.size() >= 2) {
    int ans = n - odd[1].first - even[0].first;
    cout << ans << "\n";
  } else if (even.size() >= 2) {
    int ans = n - odd[0].first - even[1].first;
    cout << ans << "\n";
  } else {
    cout << n - max(odd[0].first, even[0].first) << "\n";
  }
}

