using namespace std;
int main() {
	int N;
	cin >> N;
	vector<int> V(N);
	for (auto& x : V) cin >> x;
	map<int,int> a[2];
	for (int i = 0; i < N; ++ i) {
		++ a[i%2][V[i]];
	}
	vector<pair<int,int>> b0, b1;
	for (auto p : a[0]) b0.push_back({p.second, p.first});
	for (auto p : a[1]) b1.push_back({p.second, p.first});
	sort(b0.rbegin(), b0.rend());
	sort(b1.rbegin(), b1.rend());
	int r = N/2;
	for (int i = 0; i < 2 && i < b0.size(); ++ i) {
		for (int i = 0; i < 2 && i < b1.size(); ++ i) {
			if (b0[i].second != b1[i].second) {
				int n0 = N/2 - b0[i].first;
				int n1 = N/2 - b1[i].first;
				r = min(r, n0 + n1);
			}
		}
	}
	cout << r << endl;
}

