  int n;
  cin >> n;
  vector<int> v(n);
  for (int &x: v) cin >> x;
  map<int, int> even, odd;
  for (int i = 0; i < n; i++) {
    if (i & 1) {
      odd[v[i]]++;
    } else even[v[i]]++;
  }
  vector<pair<int, int>> o, e;
  for (auto [a, occ] : even) e.push_back({occ, a});
  for (auto [a, occ] : odd) o.push_back({occ, a});
  sort(all(o), greater<pair<int, int>>());
  sort(all(e), greater<pair<int, int>>());
  int ans = n;
  if (e[0].second != o[0].second) {
    ans -= e[0].first + o[0].first;
  } else {
    int a1 = e[0].first, a2 = (sz(e) > 1 ? e[1].first : 0);
    int a3 = o[0].first, a4 = (sz(o) > 1 ? o[1].first : 0);
    ans = max(n - a1 - a4, n - a2 - a3);
  }
  cout << ans << endl;
}

