using namespace std;
#define R register int
#define AC 201000
#define ac 101000

int n, cnt, tot;
int ll[ac], rr[ac];

struct node{
	int id, sum;
}l[AC], r[AC];

inline bool cmp(node a, node b)
{
	return a.sum > b.sum;
}

int read()
{
	int x = 0;char c = getchar();
	while(c > '9' || c < '0') c = getchar();
	while(c >= '0' && c <= '9') x = x * 10 + c - '0', c = getchar();
	return x;
}

void pre()
{
	n = read();
	int b = n / 2;
	for(R i = 1; i <= b; i ++) 
		++ ll[read()], ++ rr[read()];
}

void work()
{
	for(R i = 1; i <= 100000; i ++)
	{
		if(ll[i]) l[++cnt] = (node){i, ll[i]};
		if(rr[i]) r[++tot] = (node){i, rr[i]};
	}
	sort(l + 1, l + cnt + 1, cmp);
	sort(r + 1, r + tot + 1, cmp);
	if(l[1].id != r[1].id)
	{
		printf("%d\n", n - l[1].sum - r[1].sum);
		return ;
	}
	else
	{
		int x = l[1].sum + r[2].sum, y = l[2].sum + r[1].sum;
		printf("%d\n", n - max(x, y));
	}
}

int main()
{
	pre();
	work();
	return 0;
}

