void complete(int n) {
  sort(e.rbegin(), e.rend());
  sort(o.rbegin(), o.rend());
  int f = 0, ff = 0;
  for (int i = 1; i < N; ++i) {
    if (e[i] < e[i-1]) {
      f = e[i];
      break;
    }
  }
  for (int i = 1; i < N; ++i) {
    if (o[i] < o[i-1]) {
      ff = o[i];
      break;
    }
  }
  cout << max(n/2-ff+(n+1)/2-e[0], n/2-o[0]+(n+1)/2-f) << endl;
}

