    if (count > odd_first){
      odd_second = odd_first;
      odd_first = count;
      odd_memo = memo;
    }
    else if (count > odd_second){
      odd_second = count;
    }
  }

  int even_first = 0;
  int even_second = 0;
  int even_memo = 0;
  for (auto c : even){
    int memo = c.first;
    int count = c.second;
    if (count > even_first){
      even_second = even_first;
      even_first = count;
      even_memo = memo;
    }
    else if (count > even_second){
      even_second = count;
    }
  }

  if (odd_memo != even_memo){
    cout << n - odd_first - even_first << endl;
  }
  else{
