  for(int i = 0; i < min(2LL, (int)vs[0].size()); i++) {
    for(int j = 0; j < min(2LL, (int)vs[1].size()); j++) {
      if(vs[0][i].second == vs[1][j].second) continue;
      cost = min(cost, n - vs[0][i].first - vs[1][j].first);
    }
  }

  for(int k = 0; k < 2; k++) {
    for(int i = 0; i < min(1LL, (int)vs[k].size()); i++) {
      cost = min(cost, n - vs[k][i].first);
    }
  }

  cout << cost << endl;
}

