const int maxn = 1e+5 + 5;
int a[maxn], b[maxn];

void solve()
{
    int n;
    cin >> n;

    int m1 = 0, m2 = 0;
    int m12 = 0, m22 = 0;

    int m1_val = -1, m2_val = -1;

    for(int i = 0; i < maxn; i++)
    {
        a[i] = b[i] = 0;
    }

    for(int i = 0; i < n; i++)
    {
        int x;
        cin >> x;
        if(i & 1)
        {
            a[x]++;

            if(m1 < a[x])
            {
                m1 = a[x];
                m1_val = x;
            }

            if(m12 < a[x] && a[x] < m1)
            {
                m12 = a[x];
            }
        }
        else
        {
            b[x]++;

            if(m2 < b[x])
            {
                m2 = b[x];
                m2_val = x;
            }

            if(m22 < b[x] && b[x] < m2)
            {
                m22 = b[x];
            }
        }
    }

    if(m1_val != m2_val)
    {
        cout << n - m1 - m2;
    }
    else
    {
        cout << max(n - m1 - m22, n - m2 - m12);
    }
}

