    if(x<0) putchar('-'),x=-x;
    if(x>9) write(x/10);
    putchar(x%10+'0');
}
inline void rd(long long &val){
    long long x=0;
    int f=1;
    char ch=getchar();
    while((ch<'0'||ch>'9')&&ch!='-') ch=getchar();
	if(ch=='-'){
		f=-1;
		ch=getchar();
	}
    while(ch>='0'&&ch<='9'){
        x=x*10+ch-'0';
        ch=getchar();
    }
    val=x*f;
}
inline void rd(int &val){
    int x=0;
    int f=1;
    char ch=getchar();
    while((ch<'0'||ch>'9')&&ch!='-') ch=getchar();
	if(ch=='-'){
		f=-1;
		ch=getchar();
	}
    while(ch>='0'&&ch<='9'){
        x=x*10+ch-'0';
        ch=getchar();
    }
    val=x*f;
}
inline void _write(int x){
	write(x);
	putchar(' ');
}
inline void print(int x){
	write(x);
	putchar('\n');
}
inline void _write(ll x){
	write(x);
	putchar(' ');
}
inline void print(ll x){
	write(x);
	putchar('\n');
}
struct PII{
	ll first,second;
	PII(){}
	PII(ll f, ll s): first(f),second(s){}
	inline bool operator <(const PII& x)const{
		if(first!=x.first) return first<x.first;
		return second<x.second;
	}
	inline bool operator ==(const PII& x)const{
		return first==x.first and second==x.second;
	}
	inline bool operator >(const PII& x)const{
		if(first!=x.first) return first>x.first;
		return second>x.second;
	}
	inline bool operator !=(const PII& x)const{
		return first!=x.first and second!=x.second;
	}
};
