inline string itos(int x){
	string rt="";
	while(x) rt=(char)(x%10+'0')+rt,x/=10;
	return rt;
}
clock_t __stt;
inline void TStart(){__stt=clock();}
inline void TReport(){printf("\nTaken Time : %.3lf sec\n",(double)(clock()-__stt)/CLOCKS_PER_SEC);}
int x[1111],y[1111];
ll a[1111];
ll n,odd,even;
char c[]={'R','L','D','U'};
ll dx[4]={1,-1,0,0};
ll dy[4]={0,0,-1,1};
int main(){
	ios_base::sync_with_stdio(false);
	int i,j,k;
	#ifdef LOCAL
        TStart();
    #endif
	rd(n);
	for(i=1;i<=n;++i){
		rd(x[i]),rd(y[i]);
		if((x[i]+y[i])&1) ++odd; else ++even;
	}
	if (odd&&even) return puts("-1"),0;
	puts(even?"32":"31");
	for (i=30;i+1;--i) _write(a[++*a]=(1<<i));
