	for(j=1;j<=n;++j){
		ll nx(0ll),ny(0ll),px,py,mn;
		ll d;
		for(i=1;i<=*a;++i){
			mn=fff;
			for(k=0;k<4;++k){
				px=nx+dx[k]*a[i];
				py=ny+dy[k]*a[i];
				if(abs(px-x[j])+abs(py-y[j])<mn){
					mn=abs(px-x[j])+abs(py-y[j]);
					d=k;
				}
			}
			nx+=dx[d]*a[i];
			ny+=dy[d]*a[i];
			printf("%c",c[d]);
