    }
    std::sort(v1.begin(), v1.end()), std::sort(v2.begin(), v2.end());
    const int N1 = v1.back().first, N2 = v2.back().first;
    int ans = N - N1 - N2;
    const int V1 = v1.back().second, V2 = v2.back().second;
    v1.pop_back(), v2.pop_back();
    if (V1 == V2) {
        ans += std::min(N1 - v1.back().first, N2 - v2.back().first);
    }
    std::cout << ans << std::endl;
    return 0;
}

