#include <bits/stdc++.h>
using namespace std;
using pint = pair<int, int>;

void disp(int i)
{
    cout << i << endl;
    exit(0);
}


int main()
{
    int n;
    cin >> n;

    map<int, int> map_gu, map_ki;
    for (int i = 0; i < n / 2; i++)
    {
        int j, k;
        cin >> j >> k;
        map_gu[j]++;
        map_ki[k]++;
    }

    if (map_gu.size() == 1 && map_ki.size() == 1) // 偶数番目と奇数番目がそれぞれ全部一致
    {
        if (map_gu.begin()->first != map_ki.begin()->first) disp(0);
        else disp(n / 2);
    }
    else
    {
        priority_queue<pint, vector<pint>> gus, kis;
        for (auto pa : map_gu) gus.push(pint(pa.second, pa.first));
        for (auto pa : map_ki) kis.push(pint(pa.second, pa.first));
        if (gus.top().second != kis.top().second)
        {
            disp(n - gus.top().first - kis.top().first);
        }
        else if (map_gu.size() == 1)
        {
            if (gus.top().second == kis.top().second) kis.pop();
            disp(n - gus.top().first - kis.top().first);
        }
        else if (map_ki.size() == 1)
        {
            if (gus.top().second == kis.top().second) gus.pop();
            disp(n - gus.top().first - kis.top().first);
        }
        else
        {
            int u = gus.top().first;
            int v = kis.top().first;
            gus.pop();
            kis.pop();
            int ans = max(u + kis.top().first, v + gus.top().first);
            disp(n - ans);
        }
    }
}

