void solv(){
  for(int i = 0; i < n; i += 2)
    f[a[i]]++;

  for(int i = 0; i < maxN; i++)
    f[i] = (n / 2) - f[i];

  int mn1 = 0, mn2 = 0;
  for(int i = 0; i < maxN; i++){
    if(f[i] < f[mn1]){
      mn2 = mn1;
      mn1 = i;
    } else if(f[i] < f[mn2])
      mn2 = i;
  }

  int ans = INF;
  for(int i = 1; i < n; i += 2)
    g[a[i]]++;

  for(int i = 0; i < maxN; i++){
    g[i] = (n / 2) - g[i];
    if(i == mn1)
      ans = min(ans, f[mn2] + g[i]);
    else
      ans = min(ans, f[mn1] + g[i]);
  }

  cout << ans << '\n';
}

