void solve() {
	map<int, int> q1, q2;
	for (int i = 1; i <= n; i += 2) {
		q1[a[i]]++;
	}
	for (int i = 2; i <= n; i += 2) {
		q2[a[i]]++;
	}

	vpii v1, v2;
	for (auto z : q1) {
		v1.pb(mp(z.second, z.first));
	}
	for (auto z : q2) {
		v2.pb(mp(z.second, z.first));
	}

	v1.pb(mp(0, -1));
	v2.pb(mp(0, -2));

	sort(v1.begin(), v1.end());
	sort(v2.begin(), v2.end());

	int ans = INF;

