class SBSChecker {
private:
  unordered_map<int, int> valMap;
  int maxNVal;
  int type;

public:
  SBSChecker(int t) {
    maxNVal = 0;
    type = t;
  }

  int processNewVal() {
    int v;
    cin >> v;
    valMap[v]++;
    maxNVal = max(maxNVal, valMap[v]);
    return v;
  }

  void getnDiffMap(map<int, int>& nDiffMapOut) {
    for(auto itr=valMap.begin(); itr!=valMap.end(); itr++) {
        nDiffMapOut[itr->second] = itr->first;
    }
  }
};

int main() {
  size_t n;
  cin >> n;

  unordered_map<int, int> valMap;
  SBSChecker sbs1(1);
  SBSChecker sbs2(2);

  int d = 0;
  int hn = n / 2;
  for (size_t i = 0; i < hn; i++) {
    valMap[sbs1.processNewVal()]++;
    valMap[sbs2.processNewVal()]++;
  }

  if (valMap.size() == 1) {
    d = hn;
  } else {
    map<int, int> nDiffMap1;
    map<int, int> nDiffMap2;
    sbs1.getnDiffMap(nDiffMap1);
    sbs2.getnDiffMap(nDiffMap2);

    int maxNDiff = 0;
    for(auto itr=nDiffMap1.begin(); itr!=nDiffMap1.end(); itr++) {
      for(auto itr2=nDiffMap2.begin(); itr2!=nDiffMap2.end(); itr2++) {
        if (itr->second != itr2->second) {
           maxNDiff = max(maxNDiff, itr->first + itr2->first);
        }
      }
    }
    d = n - maxNDiff;
  }

  cout << d << "\n";

  return 0;
}

