//第一大和第二大的数值和出现次数 
typedef long long ll;
pair<pair<ll,ll>,pair<ll,ll>> s(ll cnt[100005])
{
	pair<ll,ll> a,b;
	a.first = -10000;
	b.first = -10000;
	for(ll i=0;i<100005;i++)
	{
		if(cnt[i]>=a.first)
		{
			b=a;
			a.first = cnt[i];
			a.second = i;
		}                                              
		else if(cnt[i]<a.first&&cnt[i]>b.first)
		{
			b.first = cnt[i];
			b.second = i;
		}
	}
	return make_pair(a,b);
}
ll cnto[100005],cnte[100005];
vector<ll> odd,even;
int main()
{
	ll n;
	cin>>n;
	vector<ll> vi;
	//统计个数，输入 
	for(ll i=0;i<n;i++)
	{
		ll a;
		cin>>a;
		vi.push_back(a);
		if(i%2 == 0)
		{
			odd.push_back(a);
			cnto[a]++; 
		}
		else
			even.push_back(a) , cnte[a]++;
	}
	// 第一大和第二大的数值和出现次数。
	//是两个格的 
	pair<ll,ll> fo = s(cnto).first;
	pair<ll,ll> so = s(cnto).second;
	pair<ll,ll> fe = s(cnte).first;
	pair<ll,ll> se = s(cnte).second;
	ll x = fo.second;
	ll y = fe.second;
	//如果两个最大的数相等，就把第二大多的哪一个设为那一列的评判标准 
	if(fo.second == fe.second)
	{ 
		if(so.first>se.first)
			x = so.second;
		else
			y = se.second;
	}
	ll sum = 0;
	//如果是奇数列，而且不是X，就需要被替换。
	//如果是偶数列，而且不是Y，就需要被替换。 
	for(ll i=0;i<vi.size();i++)
	{
		if(vi[i]!=x&&i%2 == 0)
			sum++;
		else if(vi[i]!=y&&i%2)
			sum++;
	} 
	cout<<sum<<endl;
}

