int main() {
	int ki[100001] = { 0 };
	int gu[100001] = { 0 };

	int n; cin >> n;

	//0,…n-1を偶奇で二分割
	for (int i = 0; i < n / 2; i++) {
		int u, v; cin >> u >> v;
		ki[u]++;
		gu[v]++;
	}

	//奇数の1,2番目と
	//偶数の1,2番目を管理したい。
	//1,2番目を知りたいだけなので、いちいちマップを使わなくても4つ変数使うことで
	//対処できたらものすごい楽。
	int ka = 0, kb = 0, ga = 0, gb = 0;

	//11b2222a33333
	//iはソートされていないので、
	//上の1,2,3のどこにくるかはわからない。
	//bより大きければ更新が発生するが、3だった場合aとbが逆転しているので
	//元に戻してやる必要がある

	for (int i = 0; i <= 100000; i++) {

		//ki[kb]より大きい要素があったら添字を更新する。
		if (ki[kb] < ki[i]) { kb = i; }

		//2番目が1番を追い越していたら、交換して正しい順位に戻す。
		if (ki[ka] < ki[kb]) { swap(ka, kb); }

		//偶数も同様
		if (gu[gb] < gu[i]) { gb = i; }
		if (gu[ga] < gu[gb]) { swap(ga, gb); }
	}

	//考察の通り、偶数と奇数で衝突が起きているかいないかで、変わる。
	//最頻値に衝突が起きていないなら
	//n/2-最頻値で最頻値以外を書き換えるのを偶奇でそれそれやればよい。

	//衝突が起きているならa1-b2,a2-b1の組合せを全部試す。


	if (ka != ga) { cout << n - (ki[ka] + gu[ga]) << endl; }
	else { cout << n - max(ki[ka] + gu[gb], ki[kb] + gu[ga]) << endl; }

	return 0;
}

