int x[Maxn],y[Maxn];
bool flag=false;
bool ap[2];
int Move[Maxn][45];
bool in(int u,int d){
	ll dis=(ll)abs(x[u])+(ll)abs(y[u]);
	int up=((1<<d)-1)*2+1;
	return dis<=up;
}
void MMove(int u,int d){
	if(d==0){
		if(x[u]==1&&y[u]==0)Move[u][++Move[u][0]]=0;
		if(x[u]==-1&&y[u]==0)Move[u][++Move[u][0]]=1;
		if(x[u]==0&&y[u]==1)Move[u][++Move[u][0]]=2;
		if(x[u]==0&&y[u]==-1)Move[u][++Move[u][0]]=3;
		return;
	}
	x[u]-=(1<<d);
	if(in(u,d-1)){
		Move[u][++Move[u][0]]=0;
		return;
	}
	x[u]+=(1<<d);
	x[u]+=(1<<d);
	if(in(u,d-1)){
		Move[u][++Move[u][0]]=1;
		return;
	}
	x[u]-=(1<<d);
	y[u]-=(1<<d);
	if(in(u,d-1)){
		Move[u][++Move[u][0]]=2;
		return;
    }
	y[u]+=(1<<d);
	y[u]+=(1<<d);
	if(in(u,d-1)){
		Move[u][++Move[u][0]]=3;
		return;
	}
}
