const int N = 1e5+10;

int n;
int even[N], odd[N];

int main() {
  cin.tie(0); cin.exceptions(cin.failbit);

  scanf("%d", &n);
  rep(i, 0, n){
    int v;
    scanf("%d", &v);

    if(i%2==0){
      even[v]++;
    } else {
      odd[v]++;
    }
  }

  // find highest, second highest
  int ehi = 0, ev=0;
  rep(i, 1, N){
    if(even[i] > ehi){
      ehi = even[i];
      ev = i;
    }
  }

  int eshi =0, esv=0;
  rep(i, 1, N){
    if(i == ev) continue;

    if(even[i] > eshi){
      eshi = even[i];
      esv = i;
    }
  }

  // first and second
  int ohi=0, ov = 0;
  rep(i, 1, N){
    if(odd[i] > ohi){
      ohi = odd[i];
      ov = i;
    }
  }

  int oshi=0, osv = 0;
  rep(i, 1, N){
    if(i == ov) continue;
    if(odd[i] > oshi){
      oshi = odd[i];
      osv = i;
    }
  }

  int ans = 0;

  // printf("%d %d, s: %d %d\n", ev, ov, esv, osv);
  if(ev != ov){
    ans = n-ehi-ohi;
  } else {
    if(esv == 0 && osv == 0){ // no secondaries
      ans = n-ehi; // have to change n/2 - ehi + n/2
    } else if(esv && osv){ // both have secondaries
      if(ehi+oshi > ohi+eshi) ans = n-ehi-oshi;
      else ans = n-ohi-eshi;
    } else { // only one has secondary
      if(esv){
        ans = n-ohi-eshi;
      } else if(osv){
        ans = n-ehi-oshi;
      }
    }
  }

  printf("%d\n", ans);

}

