const int INF = 1<<29;
const long long  INFL = 1e18;
const int MOD = 1000000007;
const int MAX = 210000;
const int MAX_NUM = 999999999;
void solve() {
	int n; cin >> n;
	vector<int> v(n);
	map<int, int> cnt[2];
	for (int i = 0; i < n; ++i) cin >> v[i];
	for (int i = 0; i < n; ++i) {
		cnt[i % 2][v[i]]++;
	}
	vector<pair<int, int>> pairs[2];
	for (int i = 0; i < 2; ++i) {
		cnt[i][0] = 0;
		for (auto&& x : cnt[i]) pairs[i].push_back( { x.second, x.first });
		sort(pairs[i].rbegin(), pairs[i].rend());
	}
	int64 ans = 0;
	if (pairs[0][0].second != pairs[1][0].second) {
		ans = n - (pairs[0][0].first + pairs[1][0].first);
	} else {
		ans = n - max(pairs[0][1].first + pairs[1][0].first,  pairs[0][0].first + pairs[1][1].first);
	}
	cout << ans << endl;
	return;
}
int main() {
	solve();
	return 0;
}

