const int MAXN = 1e5+5;
int n, a[MAXN], b[MAXN];

vector<ii> count_(int *a, int n){
	map<int, int> mp;
	FOR(i,0,n) mp[a[i]]++;
	vector<ii> ret;
	for(auto it : mp){
		ret.emplace_back(it.snd, it.fst);
	}
	sort(all(ret));
	reverse(all(ret));
	return ret;
}

int main(){
	scan(n);
	n/=2;
	FOR(i,0,n) scan(a[i], b[i]);

	vector<ii> va = count_(a, n);
	vector<ii> vb = count_(b, n);

	int ans = -1;
	if(va.size() == 1){
		int xa = va[0].snd;
		if(vb.size() == 1){
			int xb = vb[0].snd;
			if(xa == xb) ans = n;
			else ans = 0;
		}else{
			int xb1 = vb[0].snd, c1 = vb[0].fst, c2 = vb[1].fst;
			if(xa == xb1){
				ans = n-c2;
			}else{
				ans = n-c1;
			}
		}
	}else{
		int xa1 = va[0].snd, c1 = va[0].fst, c2 = va[1].fst;
		if(vb.size() == 1){
			int xb = vb[0].snd;
			if(xa1 == xb) ans = n-c2;
			else ans = n-c1;
		}else{
			int xb1 = vb[0].snd, cb1 = vb[0].fst, cb2 = vb[1].fst;
			if(xa1 == xb1){
				ans = min(n-c2 + n-cb1, n-c1 + n-cb2);
			}else{
				ans = n-c1 + n-cb1;
			}

		}
	}
	printf("%d\n",ans);

}

