pair<vector<int>::const_iterator, vector<int>::const_iterator> maxes(const vector<int>& v) {
    auto mx = max_element(all(v));
    if (mx == v.begin())
        return mp(mx, max_element(v.begin() + 1, v.end()));
    else if (next(mx) == v.end())
        return mp(mx, max_element(v.begin(), v.end() - 1));
    else {
        auto it = max_element(v.begin(), mx);
        auto jt = max_element(mx + 1, v.end());
        return mp(mx, *it > *jt ? it : jt);
    }
}

vector<int> count(vector<int> v) {
    vector<int> ans(*max_element(all(v)) + 1);
    for (int u : v)
        ans[u]++;
    return ans;
}

