				edge[i-1].second = i + 1;
				i++;
			}
			else {
				j++;
				i++;
			}
		}
		edge[N - 2].first = N - 1;
		edge[N - 2].second = N;
		REP(i, 0, N-1) {
			cout << edge[i].first << " " << edge[i].second << endl;
