int solve() {
    map<int, int> even, odd;
    REP(i,1,MAX_V) {
        even[i] = 0;
        odd[i] = 0;
    }
    REP(i,0,N) {
        if (i % 2 == 0) {
            even[V[i]]++;
        } else {
            odd[V[i]]++;
        }
    }
    vector<pair<int,int> > even_vector, odd_vector;
    REP(i,1,MAX_V) {
