/**
* @fn
* /\/\/\/
* @brief 奇数個目で一番頻出のやつ(A1)がなにかを調べる
*        偶数個目で同様に行い(B1)、N - (A1+B1)を回答。ただし、A1=B1の場合は、次に多くでてくるやつにする(A2>=B2ならA2)
*        すべてA2がない場合は、B2。B2もなければ、無なので、N-A1+0となる
* @param (引数名) 引数の説明
* @param (引数名) 引数の説明
* @return 戻り値の説明
* @sa 参照すべき関数を書けばリンクが貼れる
* @detail 詳細な説明
*/
int main(){
    int N,tmp;
    vector<int> v_odd(10^5,0);
    vector<int> v_even(10^5,0);

    cin >> N;


    for(int i = 0; i < N; i++)
    {
        cin >> tmp;
        if(i % 2 == 0)v_even.at(tmp)++;
        else{v_odd.at(tmp)++;}
    }

    int max_odd,max_even,second_odd,second_even;
    //配列番号がほしい

    std::vector<int>::iterator max_odd_iter = std::max_element(v_odd.begin(), v_odd.end());
    int max_odd_index = std::distance(v_odd.begin(), max_odd_iter);
    max_odd = *max_odd_iter;

    std::vector<int>::iterator max_even_iter = std::max_element(v_even.begin(), v_even.end());
    int max_even_index = std::distance(v_even.begin(), max_even_iter);
    max_even = *max_even_iter;

    //2番目を取得
    //削除した後は要素番号は必要ないのでよしとする
    v_odd.erase(v_odd.begin(), max_odd_iter);
    v_even.erase(v_even.begin(), max_even_iter);

    std::vector<int>::iterator second_odd_iter = std::max_element(v_odd.begin(), v_odd.end());
    int second_odd_index = std::distance(v_odd.begin(), second_odd_iter);
    second_odd = *second_odd_iter;

    std::vector<int>::iterator second_even_iter = std::max_element(v_even.begin(), v_even.end());
    int second_even_index = std::distance(v_even.begin(), second_even_iter);
    second_even = *second_even_iter;

    int A,B;
    if(max_odd_index == max_even_index)
    {
        //A2を取得
        //A1を削除してmaxを取得
        //B2
        if(second_odd >= second_even)
        {
            A = second_odd;
            B = max_even;
        }
        else
        {
            A = max_odd;
            B = second_even;
        }
    }
    else
    {
        A = max_odd;
        B = max_even;
    }

    cout << N -(A+B) << endl;
}

