const int N =1e5+10;
int n;
int v[N];
int cnt[2][N];
int ans;
int main(int argv, char ** argc) {
  cin.tie(0); cin.exceptions(cin.failbit);
  scanf("%d", &n);
  rep(i, 1, n+1){
    scanf("%d", v+i);
    int parity = i % 2 == 0;
    cnt[parity][v[i]]++;
  }

  int odd_hi_num = 0, odd_hi_num_2 = 0,
    even_hi_num = 0, even_hi_num_2 =0;

  rep(i, 1, N){
    // odd
    if(cnt[0][i] > cnt[0][odd_hi_num]){
      odd_hi_num_2 = odd_hi_num;
      odd_hi_num = i;
    } else if(cnt[0][i] > cnt[0][odd_hi_num_2]){
      odd_hi_num_2 = i;
    }

    // even
    if(cnt[1][i] > cnt[1][even_hi_num]){
      even_hi_num_2 = even_hi_num;
      even_hi_num = i;
    } else if(cnt[1][i] > cnt[1][even_hi_num_2]){
      even_hi_num_2 = i;
    }
  }

  if(odd_hi_num == even_hi_num){
    // both have same highest num
    ans = min(n - cnt[0][odd_hi_num] - cnt[1][even_hi_num_2],
              n - cnt[1][even_hi_num] - cnt[0][odd_hi_num_2]);
  } else {
