vector<pair<long, long>> elementCounter(vector<long> value_array){
	sort(value_array.begin(), value_array.end());

	auto array_iter = value_array.begin();
	auto old_array_iter = array_iter;
	vector<pair<long, long>> element_array;

	while(array_iter++ != value_array.end()){
		if (*array_iter != *old_array_iter){
			element_array.push_back(make_pair(*old_array_iter, static_cast<long>(distance(old_array_iter, array_iter))));
			old_array_iter = array_iter;
		}
	}
	element_array.push_back(make_pair(0l,0l));

	sort(element_array.begin(), element_array.end(), [](auto i, auto j){return i.second > j.second;});

	return element_array;
}

