inline void addMod(ll& a, ll b) { a += b; a %= mod; }
inline void subMod(ll& a, ll b) { a -= b; if (a < 0) { a += mod; } }
inline void mulMod(ll& a, ll b) { a *= b; a %= mod; }
inline ll powerMod(ll a, ll n) { ll ans = 1; while (n > 0) { if (n & 1) { mulMod(ans, a); } mulMod(a, a); n >>= 1; } return ans; }
inline ll powerNoMod(ll a, ll n) { ll ans = 1; while (n > 0) { if (n & 1) { ans *= a; } a *= a; n >>= 1; } return ans; }
inline ll gcd(ll a, ll b) { if (b == 0) { return a; } return gcd(b, a % b); }
inline ll lcm(ll a, ll b) { return (a * b) / gcd(a, b); }
inline bool isEqualDouble(double a, double b, double epsilon = 0.0000001) { return fabs(a - b) < epsilon; }
// call fact(f) in main first
inline void fact(vector<ll>& f) { f[0] = 1LL; for (int i = 1; i <= 1e6; i++) { mulMod(f[i], (ll)i); } }
inline ll nCk(ll k, ll n) { ll ans = 1; k = max(k, n - k); for (int i = 0; i < k; i++) { ans *= (n - i); ans /= (i + 1); } return ans; }
inline ll nCk(const vector<ll>& f, int k, int n) { if (k < 0 || k > n) { return 0; } ll d = (f[k] * f[n - k]) % mod; d = powerMod(d, (ll)mod - 2LL); return (f[n] * d) % mod; }
