        }
        else
        {
            freqOdd[t]++;
        }
    }
    vector<pair<int, int> > evens, odds;
    for (i = 0; i < n; i++)
    {
        if (i % 2 == 0 && !usedEven[a[i]])
        {
            evens.pb({ freqEven[a[i]], a[i] });
            usedEven[a[i]] = true;
        }
        if (i % 2 != 0 && !usedOdd[a[i]])
        {
            odds.pb({ freqOdd[a[i]], a[i] });
