#include<bits/stdc++.h>
using namespace std;

priority_queue<pair<pair<int, int>, int>> pq;  //even     firstに連続数、secondに値
vector<int> v;
int n;
int cn = 0;


int main(){
  cin >> n;

  int a;
  for(int i = 0; i < n; i++){
    cin >> a; v.push_back(a);
  }

  int i = 0;
  while(i < n){
    int j = 0;
    while(i + j < n && v[i+j] == v[i]) j += 2;
    pq.push(make_pair(make_pair(j/2, v[i]), i%2));
    i += j; j = 0;
  }

  i = 1;
  while(i < n){
    int j = 0;
    while(i + j < n && v[i+j] == v[i]) j += 2;
    pq.push(make_pair(make_pair(j/2, v[i]), i%2));
    i += j; j = 0;
  }

  pair<pair<int, int>, int> e = make_pair(make_pair(-1, -1), -1);  //初期値を設定
  pair<pair<int, int>, int> o = make_pair(make_pair(-2, -2), -2);

  while(!pq.empty() && e.first.second == o.first.second || e.first.first < 0 || o.first.first < 0){
    pair<pair<int, int>, int> p = pq.top(); pq.pop();
    if(p.second == 1){
      if(p.first.first > e.first.first) e = p;
    }else{
      if(p.first.first > o.first.first) o = p;
    }
  }

  if(pq.empty()) cn = n - max(e.first.first, o.first.first);
  else cn = n - e.first.first - o.first.first;

  cout << cn << endl;
  return 0;
}

