  vector<pair<size_t ,size_t>> ml{};
  vector<pair<size_t ,size_t>> mr{};
  for(size_t i = 0;i < n; i+=2){
    size_t l,r;
    cin >> l >> r;

    auto fl = std::find_if(ml.begin(),ml.end(),[&l](auto p){ return p.first == l;});
    if(fl == ml.end()){
      ml.emplace_back(l, 1);
    }else{
      ++fl->second;
    }

    auto fr = std::find_if(mr.begin(),mr.end(),[&r](auto p){ return p.first == r;});
    if(fr == mr.end()){
      mr.emplace_back(r, 1);
    }else{
      ++fr->second;
    }
  }

  if(ml.size() == 1 && mr.size() == 1){
    cout << ((ml.at(0).first != mr.at(0).first) ? 0 : (n / 2)) << endl;
  }else{
    size_t result = 0;

    sort(ml.begin(),ml.end(),[](auto p1,auto p2){ return p1.second >= p2.second; });
    sort(mr.begin(),mr.end(),[](auto p1,auto p2){ return p1.second >= p2.second; });   

    if(ml.at(0).first != mr.at(0).first){
      if(ml.size() != 1){
        result += (n/2) - ml.at(0).second;
      }
      if(mr.size() != 1){
        result += (n/2) - mr.at(0).second;
      }
    }else{
      if(ml.size()==1){
        result += (n/2) - ml.at(0).second;
        result += (n/2) - mr.at(1).second;
      }else{
        result += (n/2) - ml.at(1).second;
        result += (n/2) - mr.at(0).second;
      }
    }

    cout << result << endl;
  }
}

