                    max_even = even[v[i]];
                    even_num = v[i];
                }
            }
        }
    }
    if (odd_num == even_num){
        if (max_odd > max_even){
            max_even = 0;
            for (int i=0;i<n;i++){
                if (!(i % 2) && v[i] != odd_num && even[v[i]] > max_even)
                    max_even = even[v[i]];
            }
        }
        else{
            max_odd = 0;
            for (int i=0;i<n;i++){
                if (i % 2 && v[i] != even_num && odd[v[i]] > max_odd)
                    max_odd = odd[v[i]];
            }

        }
    }

    cout << (n - max_odd - max_even);
    return 0;

}

