int v[100001];

int main(){

    // 1. 入力情報取得.
    int N;
    scanf("%d", &N);
    map<int, int> me, mo;
    me[100001] = 0, mo[100001] = 0; // dummyデータとして保存.
    for(int i = 0; i < N; i++){
        scanf("%d", &v[i]);
        // 偶数番目, 奇数番目 ごとに, 各整数の出現回数を保存.
        if(i % 2 == 0) me[v[i]]++;
        else           mo[v[i]]++;
    }

    // 2. 出現回数の調査.
    // map -> vector に 情報 を 移し替える.
    vector<pair<int, int>> ve, vo;
    for(auto &p : me){
        int f = p.first, s = p.second;
        ve.push_back({-s, f});
    }
    for(auto &p : mo){
        int f = p.first, s = p.second;
        vo.push_back({-s, f});
    }

    // 昇順sort.
    sort(ve.begin(), ve.end());
    sort(vo.begin(), vo.end());

    // 2-1. 偶数番目, 奇数番目 で, 最大出現数 を 持つ整数が異なる場合.
    if(ve[0].second != vo[0].second){
        printf("%d\n", N + ve[0].first + vo[0].first);
        return 0;
    }

    // 2-2. 偶数番目, 奇数番目 で, 最大出現数 を 持つ整数が同じ場合.
    if(ve[0].second == vo[0].second){
        // 偶数番目で, 2番目に大きい整数を選択した場合.
        int v1 = N + ve[1].first + vo[0].first;
        // 奇数番目で, 2番目に大きい整数を選択した場合.
        int v2 = N + ve[0].first + vo[1].first;
        // 大小比較して, 小さい方を出力.
        printf("%d\n", min(v1, v2));
    }

    return 0;

}

