using namespace std;

const int mod = 1e9 + 7;
const int M = 100000;

typedef long long ll;

int n;
int cnt[2][100100];
int pre[2][100100], suf[2][100100];
int tot[2];

int main() {
  ios_base::sync_with_stdio(0);
  cin.tie(0);

  cin >> n;
  for(int i = 0; i < n; ++i) {
    int x; cin >> x;
    cnt[i % 2][x]++;
    tot[i % 2]++;
  }

  for(int i = 0; i < 2; ++i) {
    for(int j = 1; j <= M; ++j) {
      pre[i][j] = max(pre[i][j-1], cnt[i][j]);
    }
    for(int j = M; j >= 1; --j) {
      suf[i][j] = max(suf[i][j+1], cnt[i][j]);
    }
  }

  int ans = mod;
  for(int i = 0; i < 2; ++i) {
    for(int j = 1; j <= M; ++j) {
      int maxInOther = max(suf[i ^ 1][j + 1], pre[i ^ 1][j - 1]);
      ans = min(ans, tot[i] - cnt[i][j] + tot[i ^ 1] - maxInOther);
    }
  }
  cout << ans << endl;
}

