tuple<int, int, int> solver(vector<int>& x){

  sort(x.begin(), x.end());

  int cnt = 1;
  int max_cnt = 0;
  int second_cnt = 0;
  int num = 0;
  int second_num = 0;
  int s = 0;
  // cout << "vector size = " << x.size() << endl;
  for(int i = 1; i < x.size(); i++){
    if(x[i] != x[i-1]){
      cnt = i-1 - s + 1;
      if(max_cnt <= cnt) {
        second_cnt = max_cnt;
        max_cnt = cnt;
        second_num = num;
        num = x[i-1];
      }
      s = i;
    }else if(i == x.size() - 1){
      cnt = i - s + 1;
      if(max_cnt <= cnt){
        second_cnt = cnt;
        max_cnt = cnt;
        second_num = num;
        num = x[i-1];
      }
    }
  }

  // cout << num << "," << max_cnt << endl;

  int ans = 0;
  for(int i = 0; i < x.size(); i++){
    if(x[i] != num) ans ++;
  }
  int second_ans = 0;
  for(int i = 0; i < x.size(); i++){
    if(x[i] != second_num) second_ans ++;
  }

  return make_tuple(num, ans, second_ans);
}

