int get_max(map<int,int> &m, int &k, int &v) {
	v = INT_MIN;
	for(auto x: m) {
		if (x.second > v) {
			k = x.first;
			v = x.second;
		}
	}
	return m.size()>0;
}

int solve() {
	map<int,int> m[2];
	for (int i=0; i<n; i++) {
		int k = i%2;
		if (m[k].count(a[i])) m[k][a[i]]++;
		else m[k][a[i]] = 1;
	}
	int r = 0, k[2] = {0}, v[2];
	for (int i=0; i<2; i++) {
		get_max(m[i], k[i], v[i]);
	}
	if (k[0] == k[1]) {
		r = INT_MAX;
		for (int i=0; i<2; i++) {
			if (m[i].size()>1) {
				m[i].erase(k[i]);
				int kk[2], vv[2];
				for (int j=0; j<2; j++)
					get_max(m[j], kk[j], vv[j]);
				r = min(r, n-vv[0]-vv[1]);
				m[i][k[i]] = v[i];
			}
		}
		if (r==INT_MAX) r = n/2;
	}
	else {
		r = n - v[0] - v[1];
	}
	return r;
}

