int main() {
  int n;
  cin >> n;
  vector<int> v(n);
  for (int i = 0; i < n; i++) cin >> v.at(i);
  map<int, int> vcount;
  for (int i = 0; i < n; i++){
    if(i % 2) vcount[v.at(i)]++;
    else vcount[-v.at(i)]++;
  }

  int first = 0;
  int first_memo = 0;
  int second = 0;
  int second_memo = 0;
  int third = 0;
  for (auto c : vcount){
    int memo = c.first;
    int count = c.second;
    if (count > first){
      third = second;
      second = first;
      second_memo = first_memo;
      first = count;
      first_memo = memo;
    }
    else if (count > second){
      third = second;
      second = count;
      second_memo = memo;
    }
  }

  if (first_memo != -1 * second_memo){
    cout << n - first - second << endl;
  }
  else{
    cout << n - first - third << endl;
  }

}

