void solve() {
    int n; cin >> n;
    map<int, int> mp1, mp2;
    for (int i = 0; i < n/2; i++) {
        int a, b; cin >> a >> b;
        mp1[a]++; mp2[b]++;
    }

    int ma1 = 0, ma1_second = 0, ma2 = 0, ma2_second = 0;
    int a = 0, b = 0;
    for (auto e : mp1) {
        if (e.second > ma1) {
            ma1_second = ma1;
            ma1 = e.second;
            a = e.first;
        }
    }

    for (auto e : mp2) {
        if (e.second > ma2) {
            ma2_second = ma2;
            ma2 = e.second;
            b = e.first;
        }
    }

    int ans;
    if (a == b) {
        ans = min(n - ma1 - ma2_second, n - ma1_second - ma2);
    }
    else ans = n - ma1 - ma2;
    cout << ans << '\n';
}

int main() {
    cin.tie(nullptr);
    ios_base::sync_with_stdio(false);

    solve();

    return 0;
}

