const int maxn = 3e5 + 7;
int even[maxn],odd[maxn];
/*------------------------------------- */ void Fan_chipu() {
  int n; cin >> n;
  rep1(i,n) {
    int x;
    cin >> x;
    if(i & 1) ++odd[x];
    else ++even[x];
  }
  int maxEven = 0,maxOdd = 0;
  rep(i,maxn) {
    if(even[maxEven] < even[i]) maxEven = i;
  }
  rep(i,maxn) {
    if(i == maxEven) continue;
    if(odd[maxOdd] < odd[i]) maxOdd = i; 
  }
  int ans = n - even[maxEven] - odd[maxOdd];
  maxEven = 0,maxOdd = 0;
  rep(i,maxn) {
    if(even[maxEven] < even[i]) maxEven = i;
  }
  rep(i,maxn) {
    if(i == maxEven) continue;
    if(odd[maxOdd] < odd[i]) maxOdd = i; 
  }
  umin(ans,n - odd[maxOdd] - even[maxEven]);
  cout << ans;
}

