int main()
{
	int num;
	std::cin >> num;

	const size_t size = num / 2;
	std::vector<std::pair<int, int>> odd_v;
	std::vector<std::pair<int, int>> even_v;
	odd_v.reserve(size);
	even_v.reserve(size);

	{
		std::unordered_map<int, int> odd;
		std::unordered_map<int, int> even;

		for (uint32_t i = 0; i < num; ++i)
		{
			int value;
			std::cin >> value;

			if (i % 2)
			{
				++odd[value];
			}
			else
			{
				++even[value];
			}
		}

		for (auto&& v : odd)
		{
			odd_v.emplace_back(v);
		}

		for (auto&& v : even)
		{
			even_v.emplace_back(v);
		}
	}

	std::sort(odd_v.begin(), odd_v.end(), [](auto v1, auto v2)
	{
		return v1.second > v2.second;
	});

	std::sort(even_v.begin(), even_v.end(), [](auto v1, auto v2)
	{
		return v1.second > v2.second;
	});

	bool is_same_max = odd_v[0].first == even_v[0].first;
	bool is_same_num = odd_v[0].second == even_v[0].second;

	do {
		if (is_same_max)
		{
			if (odd_v.size() == 1)
			{
				odd_v[0] = { odd_v[0].first, 0 };
				break;
			}

			if (is_same_num)
			{
				if (odd_v[1].second > even_v[1].second)
				{
					odd_v[0] = odd_v[1];
				}
				else
				{
					even_v[0] = even_v[1];
				}
			}
			else
			{
				if (odd_v[0].second > even_v[0].second)
				{
					even_v[0] = even_v[1];
				}
				else
				{
					odd_v[0] = odd_v[1];
				}
			}
		}
	} while (false);

	int odd_change = size - odd_v[0].second;
	int even_change = size - even_v[0].second;

	std::cout << odd_change + even_change;

	return 0;
}

