	}
	for (int i = 1;i < n >> 1;++ i) {
		for (int j = 0;j < 2;++ j) {
			if (v[j][i] == v[j][i - 1]) ++ freq[j][index[j]].first; // 前回と同値ならそっちに加算
			else {
				++ index[j];
				freq[j][index[j]] = make_pair(1, v[j][i]); // そうでないなら新しく作る
			}
		}
	}
	for (int i = 0;i < 2;++ i) sort(freq[i], freq[i]+index[i]+1);

	if (freq[0][index[0]].second != freq[1][index[1]].second) cout << n - freq[0][index[0]].first - freq[1][index[1]].first;
	else cout << n - max(freq[0][index[0] - 1].first + freq[1][index[1]].first, freq[0][index[0]].first + freq[1][index[1] - 1].first);

