using namespace std;
typedef long long ll;

int main()
{
    ll N;
    cin >> N;
    ll* v = new ll[N];
    std::unordered_map<ll, ll> map1;
    std::unordered_map<ll, ll> map2;
    for(ll i = 0; i < N; i ++){
        cin >> v[i];
    }
    for(ll i = 0; i < N; i += 2){
        try{
            map1[v[i]] = map1[v[i]] + 1;
        }
        catch(std::out_of_range&) {
            map1[v[i]] = 1;
        }
    }
    for(ll i = 1; i < N; i += 2){
        try{
            map2[v[i]] = map2[v[i]] + 1;
        }
        catch(std::out_of_range&) {
            map2[v[i]] = 1;
        }
    }
    ll max1 = 0;
    ll max1num = 0;
    ll max2 = 0;
    for(auto itr = map1.begin(); itr != map1.end(); ++itr) {
        if(itr->second > max1){
            max1 = itr->second;
            max1num = itr->first;
        }
    }
    for(auto itr = map2.begin(); itr != map2.end(); ++itr) {
        if(itr->second > max2 && itr->first != max1num){
            max2 = itr->second;
        }
    }

    ll maxtemp = N - max1 - max2;

    max1 = 0;
    ll max2num = 0;
    max2 = 0;
    for(auto itr = map2.begin(); itr != map2.end(); ++itr) {
        if(itr->second > max2){
            max2 = itr->second;
            max2num = itr->first;
        }
    }
    for(auto itr = map1.begin(); itr != map1.end(); ++itr) {
        if(itr->second > max1 && itr->first != max2num){
            max1 = itr->second;
        }
    }

    if((N - max1 - max2) > maxtemp){
        cout << maxtemp;
    }
    else{
        cout << (N - max1 - max2);
    }

    return 0;
}

