int main()
{
	int n;
	int ans=0;
	cin>>n;
	for(int i=0;i<n;i++)
	{
		cin>>v[i];
	}
	for(int i=0;i<100001;i++)
	{
		odd[i]=make_pair(0,i);
		even[i]=make_pair(0,i);
