#include <bits/stdc++.h>

using namespace std;

int n;
int v[100005];

void init() {
    cin >> n;
    for(int i = 0 ; i < n ; i++) cin >> v[i];
}

int test(int a, int b) {
    int ans = 0;
    for(int i = 0 ; i < n ; i += 2) if(v[i] != a) ans++;
    for(int i = 1 ; i < n ; i += 2) if(v[i] != b) ans++;
    return ans;
}
void solve() {
    map<int, int> m[2];
    for(int i = 0 ; i < n ; i++) m[i%2][v[i]]++;
    vector<pair<int, int> > v[2];
    for(int i = 0 ; i < 2 ; i++) {
        for(auto j : m[i]) v[i].push_back(make_pair(j.second, j.first));
        sort(v[i].begin(), v[i].end());
        reverse(v[i].begin(), v[i].end());
    }

    if(v[0][0].second == v[1][0].second) {
        if(v[0].size() == 1 && v[1].size() == 1) cout << min(v[0][0].first, v[1][0].first) << '\n';
        else if(v[0].size() == 1) {
            cout << test(v[0][0].second, v[1][1].second) << '\n';
        }
        else if(v[1].size() == 1) {
            cout << test(v[0][1].second, v[1][0].second) << '\n';
        }
        else {
            cout << min(test(v[0][1].second, v[1][0].second), test(v[0][0].second, v[1][1].second)) << '\n';
        }
    }
    else {
        cout << test(v[0][0].second, v[1][0].second) << '\n';
    }
}

int main() {
    init();
    solve();
}

