                break;
            }
        }
    }
    REP(i, mv2.size()) {
        if (mv2[i].first == 0) continue;
        REP(j, mv1.size()) {
            if (mv1[j].first == 0) continue;
            if (mv2[i].second != mv1[j].second) {
                chmin(ans, N + mv2[i].first + mv1[j].first);
                break;
            }
        }
    }
    if (ans == INT64_MAX) ans = N / 2;
    out(ans);

    return 0;
}

