void solve() {
    int n;
    cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    map<int, int> mp1, mp2;
    for (int i = 0; i < n; ++i) {
        if (i % 2 == 0) {
            mp1[a[i]] = n / 2;
        }
        else {
            mp2[a[i]] = n / 2;
        }
    }
    for (int i = 0; i < n; ++i) {
        if (i % 2 == 0) {
            mp1[a[i]]--;
        }
        else {
            mp2[a[i]]--;
        }
    }
    vector<pair<int, int>> v1, v2;
    if ($(mp1) == 1) {
        v1.push_back(*mp1.begin());
    }
    else {
        v1.push_back(*mp1.begin());
        mp1.erase(mp1.begin());
        v1.push_back(*mp2.begin());
    }
    if ($(mp2) == 1) {
        v2.push_back(*mp2.begin());
    }
    else {
        v2.push_back(*mp2.begin());
        mp2.erase(mp2.begin());
        v2.push_back(*mp2.begin());
    }

    if ($(v1) == 1 && $(v2) == 1) {
        if (v1[0].x == v2[0].x) {
            cout << n / 2 << endl;
        }
        else {
            cout << 0 << endl;
        }
    }
    else if ($(v1) == 1 && $(v2) == 2) {
        if (v1[0].x != v2[0].x) {
            cout << v1[0].y + v2[0].y << endl;
        }
        else {
            cout << v1[0].y + v2[1].y << endl;
        }
    }
    else if ($(v1) == 2 && $(v2) == 1) {
        if (v1[0].x != v2[0].x) {
            cout << v2[0].y + v1[0].y << endl;
        }
        else {
            cout << v1[1].y + v2[0].y << endl;
        }
    }
    else {
        if (v1[0].x != v2[0].x) {
            cout << v1[0].y + v2[0].y << endl;
        }
        else {
            cout << min(v1[0].y + v2[1].y, v1[1].y + v2[0].y) << endl;
        }
    }
}

