void solve(long long n, vector<long long> v){
  vector<long long> odd(100001, 0);
  vector<long long> even(100001, 0);
  long long neven, nodd;
  neven = 0;
  nodd = 0;
  for (int i = 0; i < n; i++) {
    if (i%2 == 0) {
      even[v[i]]++;
      neven++;
    } else {
      odd[v[i]]++;
      nodd++;
    }
  }
  long long ret = 0;
  long long maxodd, maxeven;
  long long maxodd2, maxeven2;
  int oddidx, evenidx;
  int oddidx2, evenidx2;
  maxodd = 0;
  maxeven = 0;
  for (int i = 0; i < 100001; i++) {
    if (maxodd < odd[i]) {
      maxodd2 = maxodd;
      maxodd = odd[i];
      oddidx2 = oddidx;
      oddidx = i;
    }
    if (maxeven < even[i]) {
      maxeven2 = maxeven;
      maxeven = even[i];
      evenidx2 = evenidx;
      evenidx = i;
    }
  }
  ret += nodd - maxodd;
  ret += neven - maxeven;
  if (oddidx == evenidx) {
    ret = min(nodd - maxodd + neven - maxeven2, nodd - maxodd2 + neven - maxeven);
  }
  std::cout << ret << std::endl;
}

