    if (it.second > max_even_count) {
      max_even_count = it.second;
	  prev_even = max_even;
      max_even = it.first;
    }
  }

  int max_odd_count = 0;
  int max_odd = 0;
  int prev_odd = 0;
  for (auto it : odd) {
    if (it.second > max_odd_count) {
      max_odd_count = it.second;
	  prev_odd = max_odd;
      max_odd = it.first;
    }
  }
  if (max_even == max_odd) {
	  if (max_odd_count > max_even_count)
		  max_even = prev_even;
	  else
		  max_odd = prev_odd;
  }
  int c = 0;
  for (int i = 0; i < n; ++i){
    if (i % 2){
      if (v[i] != max_even) ++c; 
    } else {
      if (v[i] != max_odd) ++c;
    }
  }

  cout << c;
}

