    auto odd_idx = odd_count.size() - 1;
    auto even_idx = even_count.size() - 1;
    auto target = N >> 1;
    auto ans = 0;
    if (odd_count[odd_idx].first == target && even_count[even_idx].first == target) {
        if (odd_count[odd_idx].second != even_count[even_idx].second) {
            ans = 0;
        }
        else {
            ans = target;
        }
    }
    else if (odd_count[odd_idx].first == target) {
        if (even_count[even_idx].second != odd_count[odd_idx].second) {
            ans = target - even_count[even_idx].first;
        }
        else {
            ans = target - even_count[even_idx - 1].first;
        }
    }
    else if (even_count[even_idx].first == target) {
        if (odd_count[odd_idx].second != even_count[even_idx].second) {
            ans = target - odd_count[odd_idx].first;
        }
        else {
            ans = target - odd_count[odd_idx - 1].first;
        }
    }
    else {
        auto o1 = odd_count[odd_idx].first;
        auto o2 = odd_count[odd_idx - 1].first;

        auto e1 = even_count[even_idx].first;
        auto e2 = even_count[even_idx - 1].first;

        auto ans1 = target - o1 + target - e2;
        auto ans2 = target - e1 + target - o2;
        ans = min(ans1, ans2);
    }

    cout << ans << '\n';
}

