const int N=1e5+5;
int n,a[N],q[N],cnt[N],top,topx,topy,ans; pii x[N],y[N];
int main(){
	scanf("%d",&n);
	rep (i,1,n) scanf("%d",&a[i]);
	for (int i=1;i<=n;i+=2) q[++top]=a[i],cnt[a[i]]++;
	topx=unique(q+1,q+1+top)-q-1;
	rep (i,1,topx) x[i]=pii(cnt[q[i]],q[i]);
	sort(x+1,x+1+topx,greater<pii>());
	top=0; memset(cnt,0,sizeof(cnt));
	for (int i=2;i<=n;i+=2) q[++top]=a[i],cnt[a[i]]++;
	topy=unique(q+1,q+1+top)-q-1;
	rep (i,1,topy) y[i]=pii(cnt[q[i]],q[i]);
	sort(y+1,y+1+topy,greater<pii>());
	if (x[1].se==y[1].se) ans=max(x[2].fi+y[1].fi,x[1].fi+y[2].fi); else ans=x[1].fi+y[1].fi;
	cout<<n-ans;
