    for(int i=0; i<n/2; i++){
        if(mp_odd.find(v_odd[i])==mp_odd.end()){
            mp_odd[v_odd[i]]=1;
            if(mp_odd[v_odd[i]]>max_odd){
                max2_odd=max_odd;
                max_odd=mp_odd[v_odd[i]];
                num_max_odd=v_odd[i];
            }
        }
        else{
            mp_odd[v_odd[i]]++;
            if(mp_odd[v_odd[i]]>max_odd){
                if(num_max_odd!=v_odd[i]){
                    max2_odd=max_odd;
                }
                max_odd=mp_odd[v_odd[i]];
                num_max_odd=v_odd[i];
            }
        }

        if(mp_even.find(v_even[i])==mp_even.end()){
            mp_even[v_even[i]]=1;
            if(mp_even[v_even[i]]>max_even){
                max2_even=max_even;
                max_even=mp_even[v_even[i]];
                num_max_even=v_even[i];
            }
        }
        else{
            mp_even[v_even[i]]++;
            if(mp_even[v_even[i]]>max_even){
                if(num_max_even!=v_even[i]){
                    max2_even=max_even;
                }
                max_even=mp_even[v_even[i]];
                num_max_even=v_even[i];
            }
        }
    }

    int ans;
    if(num_max_odd==num_max_even){
        if(max_even+max2_odd>max2_even+max_odd){
            ans=n-(max_even+max2_odd);
        }
        else{
            ans=n-(max2_even+max_odd);
        }
    }
    else{
        ans=n-(max_even+max_odd);
    }
    //cout<<max_even<<endl << max_odd;
    cout << ans << endl;
}

