        if(it.second > next_even && it.first != n_even){
            k_even = it.first;
            next_even = it.second;
        }
    }
    for(auto it: m_odd){
        if(it.second > max_odd){
            n_odd = it.first;
            max_odd = it.second;
        }
    }
    for(auto it: m_odd){
