int main()
{
	int num;
	std::cin >> num;

	std::unordered_map<int, int> odd;
	std::unordered_map<int, int> even;

	std::pair<int, int> odd_max = { 0, 0 };
	std::pair<int, int> odd_max2 = { 0, 0 };
	std::pair<int, int> even_max = { 0, 0 };
	std::pair<int, int> even_max2 = { 0, 0 };

	for (uint32_t i = 0; i < num; ++i)
	{
		int value;
		std::cin >> value;

		if (i % 2)
		{
			++odd[value];
			if (odd_max.first != value && odd_max.second < odd[value])
			{
				odd_max2 = odd_max;
				odd_max = *odd.find(value);
			}
		}
		else
		{
			++even[value];
			if (even_max.first != value && even_max.second < even[value])
			{
				even_max2 = even_max;
				even_max = *even.find(value);
			}
		}
	}

	bool is_same_max = (odd_max.first == even_max.first);
	bool is_same_max_num = (odd_max.second == even_max.second);

	if (odd.size() == 1)
	{
		odd_max2 = { odd_max.first + 1, odd_max.second + 1 };
	}

	if (even.size() == 1)
	{
		even_max2 = { even_max.first + 1, even_max.second + 1 };
	}

	if (is_same_max)
	{
		if (!is_same_max_num)
		{
			odd_max = odd_max2;
		}
		else
		{
			even_max = even_max2;
		}
	}

	int odd_change = 0;
	for (auto&& v : odd)
	{
		if (v.first != odd_max.first)
		{
			++odd_change;
		}
	}

	int even_change = 0;
	for (auto&& v : even)
	{
		if (v.first != even_max.first)
		{
			++even_change;
		}
	}

	if (odd_max == even_max)
	{
		std::cout << std::min(num - odd_max.second - even_max2.second, num - odd_max2.second - even_max.second);
	}
	else
	{
		std::cout << num - odd_max.second - even_max.second;
	}

	return 0;
}

