const int N = 100005;

int n;
int a[N], x[N], y[N], use[N], vis[N];

int main()
{
    cin >> n;
    Rep(i, 1, n) cin >> a[i];

    for (int i = 1; i <= n; i += 2) x[a[i]]++;
    for (int i = 2; i <= n; i += 2) y[a[i]]++;

    int la = 0, lb = 0, ma = 0;
    for (int i = 0; i < N; ++i) {
        if (x[i] > la) {
            lb = la;
            la = x[i];
            ma = i;
        }
    }

    int ra = 0, rb = 0, sa = 0;
    for (int i = 0; i < N; ++i) {
        if (y[i] > ra) {
            rb = ra;
            ra = y[i];
            sa = i;
        }
    }

    bool flag = 0;
    rep(i, 0, N) {
        if (x[i] == la) use[i] = 1;
        if (y[i] == ra) vis[i] = 1;
        if (use[i] ^ vis[i]) flag = 1;
    }

    if (ma != sa || flag) {
        cout << (n - la - ra) << endl;
    }
    else {
        int ans = min(n - la - rb, n - lb - ra);
        cout << ans << endl;
    }

    return 0;
}

