template<typename T> constexpr T ModUp(const T& x, ll Mod = mod) { return (x % Mod + Mod) % Mod; }
template<typename T>
constexpr T exgcd(T a, T b, T& x, T& y)
{
	if (a == 0 && b == 0)return -1;
	if (b == 0) { x = 1, y = 0; return a; }
	T d = exgcd(b, a % b, y, x);
	y -= a / b * x;
