#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const double PI = 4*atan(1);
const int INF = 0x3f3f3f3f;
const ll LINF = 0x3f3f3f3f3f3f3f3f;
const double EPS = 1e-6;
const string YES = "Possible";
const string NO = "Impossible";
#define pb push_back
#define mp make_pair
const int MAX_N = 1e5+5;
int v[MAX_N];
int ce[MAX_N], co[MAX_N];
int N;

void solve()
{
	if(N==2){
		if(v[0] != v[1]) cout << 0 << endl;
		else cout << 1 << endl;
		return;
	}
	for(int i=0;i<N;i+=2) ce[v[i]]++;
	for(int i=1;i<N;i+=2) co[v[i]]++;
	vector<pair<int,int>> ve, vo;
	for(int i=0; i<N;++i) if(ce[i]) ve.emplace_back(ce[i],i);
	for(int i=0; i<N;++i) if(co[i]) vo.emplace_back(co[i],i);
	sort(ve.begin(), ve.end(), greater<pair<int,int>>());
	sort(vo.begin(), vo.end(), greater<pair<int,int>>());
	int e=0, o=0;
	if(ve[e].second == vo[o].second){//most common
		if(ve[e].first + vo[o+1].first >= ve[e+1].first + vo[o].first){
			o++;
		}else{
			e++;
		}
	}
	int ans;
    if(e>=ve.size()) ans = N-vo[o].first;
    else if(o >=vo.size()) ans = N-ve[e].first;
	else ans = N-ve[e].first-vo[o].first;
	cout << ans << endl;
}

int main()
{
	cin >> N;
	for(int i=0;i<N;++i) cin >> v[i];
	solve();
}

