            oddMax = {0, 0};
            evens.erase(evenMax.first);
            for (auto e : evens)
                if (e.second > evenMax.second) evenMax = e;
        }
    }

    int ans = 0;
    for (auto e : evens)
        if (e.first != evenMax.first) ans += e.second;
    for (auto e : odds)
        if (e.first > oddMax.first) ans += e.second;

