                    if (v[i] != even_num)
                        sec_even = max_even;
                    max_even = even[v[i]];
                    even_num = v[i];
                }
            }
        }
    }
    int ret = n - max_odd - max_even;
    if (odd_num == even_num){
        if ((max_even + sec_odd) > (max_odd + sec_even))
            ret = n - max_even - sec_odd;
        else
            ret = n - max_odd - sec_even;
    }

    cout << ret;
    return 0;

}

