int solve(){
	for(int i = 0; i < N; ++i){
		if(i % 2 == 0) e[A[i]]++;
		else o[A[i]]++;
	}
	map<int, int>::iterator it = e.begin();
	for(; it != e.end(); ++it){
		evec.push_back(P(it->second, it->first));
