        cin>>v[i];
    }
    map<int,int> a;
    map<int,int> b;
    for (int i = 0; i < n-1; i+=2) {
        a[v[i]]+=1;
    }
    for (int i = 1; i < n; i+=2) {
        b[v[i]]+=1;
    }
    priority_queue<pair<int,int>> aq,bq;
    for(auto i:a){
        aq.emplace(i.second,i.first);
    }
    for(auto i:b){
        bq.emplace(i.second,i.first);
    }
    int ans=0;
    if(aq.top().second!=bq.top().second){
        ans+=n/2-aq.top().first;
        ans+=n/2-bq.top().first;
        cout<<ans<<endl;
        return 0;
    }
    else {
        if(aq.top().first>bq.top().first){
            bq.pop();
            ans+=n/2-aq.top().first;
            if(bq.empty())ans+=n/2;
            else ans+=n/2-bq.top().first;
            cout<<ans<<endl;
            return 0;
        }
        else if(aq.top().first<bq.top().first){
            aq.pop();
            if(aq.empty())ans+=n/2;
            else ans+=n/2-aq.top().first;
            ans+=n/2-bq.top().first;
            cout<<ans<<endl;
            return 0;
        }
        else {
            int m=min(aq.top().first,bq.top().first);
            aq.pop();
            bq.pop();
            if(aq.empty()){
                if(bq.empty()){
                    ans=n/2-m;
                    ans+=n/2;
                }
                else {
                    ans+=n/2-m;
                    ans+=n/2-bq.top().first;
                }
            }
            else if(bq.empty()){
                ans+=n/2-m;
                ans+=n/2-aq.top().first;
            }
            else {
                ans+=n/2-m;
                ans+=min(n/2-aq.top().first,n/2-bq.top().first);
            }
            cout<<ans<<endl;
        }
    }
    return 0;
}

