const int MOD = 1e9 + 7;
const int MAXV = 1e5;

int main() {
    FAST_IO();
    int N; cin >> N;
    vector<int> odd, even;
    rep(i, N) {
        int x; cin >> x;
        if(i % 2 == 1) odd.push_back(x);
        else even.push_back(x);
    }
    vector<int> cntOdd(MAXV + 1), cntEven(MAXV + 1);
    rep(i, sz(odd)) cntOdd[odd[i]]++;
    rep(i, sz(even)) cntEven[even[i]]++;
    int FirstFreqIdxOdd = -1, FirstFreqIdxEven = -1;
    int FirstFreqOdd = 0, FirstFreqEven = 0;;
    repp(i, 1, MAXV) {
        if(cntOdd[i] > FirstFreqOdd) {
            FirstFreqOdd = cntOdd[i];
            FirstFreqIdxOdd = i;
        }
    }
    repp(i, 1, MAXV) {
        if(cntEven[i] > FirstFreqEven) {
            FirstFreqEven = cntEven[i];
            FirstFreqIdxEven = i;
        }
    }
    int SecondFreqIdxOdd = -1, SecondFreqIdxEven = -1;
    int SecondFreqOdd = 0, SecondFreqEven = 0;
    repp(i, 1, MAXV) {
        if(cntOdd[i] >= SecondFreqOdd && i != FirstFreqIdxOdd) {
            SecondFreqOdd = cntOdd[i];
            SecondFreqIdxOdd = i;
        }
    }
    repp(i, 1, MAXV) {
        if(cntEven[i] >= SecondFreqEven && i != FirstFreqIdxEven) {
            SecondFreqEven = cntEven[i];
            SecondFreqIdxEven = i;
        }
    }
    cout << FirstFreqIdxOdd << " " << FirstFreqIdxEven << "\n";
    cout << SecondFreqIdxOdd << " " << SecondFreqIdxEven << "\n";
    if(FirstFreqIdxOdd == FirstFreqIdxEven) {
        cout << sz(odd) + sz(even) - max(FirstFreqOdd + SecondFreqEven, FirstFreqEven + SecondFreqOdd) << endl;
    } else {
        cout << sz(odd) + sz(even) - FirstFreqOdd - FirstFreqEven << endl;
    }
    return 0;
}

