inline int getmin(int vp,int vq){
	return vp<vq?vp:vq;
}

int main(int argc,char **argv){
	in.open(stdin,512);
	out.open(stdout,512);
	in.scan();
	int n;
	in>n;
	int v[100000];
	in.get(v,n);
	struct ds{
		int x;
		int y;
	};
	ds a[100001],b[100001];
	for(int i=1;i<=100000;++i){
		a[i].x=b[i].x=i;
		a[i].y=b[i].y=0;
	}
	for(int i=0;i<n;i+=2) ++a[v[i]].y;
	for(int i=1;i<n;i+=2) ++b[v[i]].y;
	std::nth_element(&a[1],&a[2],&a[1]+100000,[](ds &s,ds &t){return s.y>t.y;});
	std::nth_element(&b[1],&b[2],&b[1]+100000,[](ds &s,ds &t){return s.y>t.y;});
	out<(a[1].x!=b[1].x?(n/2-a[1].y)+(n/2-b[1].y):getmin((n/2-a[1].y)+(n/2-b[2].y),(n/2-a[2].y)+(n/2-b[1].y)))<'\n';
