	for(int i = 0 ; i < N ; ++i){
		scanf("%d",&x);
		if(i%2)
			odd[x]++;
		else	
			even[x]++;
	}
	int omax = 0,emax = 0;
	int oind, eind;
	for(int i = 1 ; i <= 100000 ; ++i){
		if(odd[i] >= omax){
			omax = odd[i];
			oind = i;
		}
		if(even[i] >= emax){
			emax = even[i];
			eind = i;
		}
	}
	if(oind == eind){
		if(omax > emax){
			even[eind] = 0;
			emax = 0;
			for(int i = 1 ; i <= 100000 ; ++i){
				if(even[i] >= emax){
					emax = even[i];
					eind = i;
				}
			}
		}
		else if(omax < emax){
			odd[eind] = 0;
			omax = 0;
			for(int i = 1 ; i <= 100000 ; ++i){
				if(odd[i] >= omax){
					omax = odd[i];
					oind = i;
				}
			}
		}

		else{
			even[eind] = 0;
			odd[oind] = 0;
			int esed = 0,osed = 0;
			for(int i = 1 ; i <= 100000 ; ++i){
				if(odd[i] > osed)
					osed = odd[i];

			}
			for(int i = 1 ; i <= 100000 ; ++i){
				if(even[i] >= esed)
					esed = even[i];

			}
			if(esed > osed)
				emax = esed;
			else
				omax = osed;
		}

	} 
	//printf("%d %d %d %d\n",oind,omax,eind,emax);
	printf("%d\n",N - omax - emax);

	return 0;
}

