#include <iostream>
#include <map>

int main() {
  size_t n;
  std::cin >> n;

  std::map<int, int> v[2];
  for (size_t i=0; i<n; i+=2)
    for (size_t j=0; j<2; ++j) {
      int tmp;
      std::cin >> tmp;
      ++v[j][tmp];
    }

  // 偶奇で分けたとき，各々のうちで最も多く出現する値とその数（へのイテレータ）
  // *f0 の型は std::pair<const int, int> のはず
  auto f0=v[0].begin();
  auto f1=v[1].begin();

  if (v[0].size() == 1 && v[1].size() == 1) {
    // 各グループの種類数がどちらも 1 のとき
    if (f0->first == f1->first) {
      // それらが同じなら半分を変える必要があります
      std::cout << n/2 << std::endl;
    } else {
      // 異なっていれば何も変える必要がありません
      std::cout << "0\n";
    }
    return 0;
  }

  if (f0->first != f1->first) {
    // 最も多く出現する値が異なっていれば，それら以外を変えます
    std::cout << n-(f0->second+f1->second) << std::endl;
    return 0;
  }

  // どちらも同じ場合はどうしますか？
  // 出現数が少ない方は二番目に多く出現する値に変えます
  auto g0=std::next(f0);
  auto g1=std::next(f1);
  if (f0->second != f1->second) {
    // 要素数が 1 のとき，std::next(foo.begin()) の要素を取得することは
    // できませんが，今回は問題設定の関係からそうした状況は避けられます．
    // 要素数が 1 だった場合，出現数は n/2 のはずで，相手のグループがそれを
    // 上回ることはできないからです．
    if (f0->second > f1->second) {
      std::cout << n-(f0->second+g1->second) << std::endl;
    } else {
      std::cout << n-(g0->second+f1->second) << std::endl;
    }
    return 0;
  }

  // タイの場合はどうしますか？
  // 二番目に多く出現する値の出現数が大きい方のグループは，
  // その値に変えることにし，そうでない方のグループは一番多く出現する
  // 値に変えることにします．それでも同じなら適当に選びます
  std::cout << n-(f0->second+std::max(g0->second, f1->second)) << std::endl;
}

