	read(n);
	for (int x, i = 1; i <= n; ++i) {
		read(x);
		++tot[i & 1][x];
	}
	for (int i = 1; i <= MAXN; ++i)
		for (int j = 0; j <= 1; ++j) {
			if (tot[j][i] > firMax[j]) {
				secMax[j] = firMax[j], secRes[j] = firRes[j];
				firMax[j] = tot[j][i], firRes[j] = i;
			} else if (tot[j][i] > secMax[j])
				secMax[j] = tot[j][i], secRes[j] = i;
		}
	if (firRes[0] != firRes[1]) write(n - firMax[0] - firMax[1]);
	else write(n - max(firMax[0] + secMax[1], secMax[0] + firMax[1]));
	putchar('\n');
	return 0;
}

