#include <bits/stdc++.h>

using namespace std;

const int N = 1e5 + 5;

int n;
int cnt[2][N];
pair<int, int> b[2];

void update(pair<int, int>& a, int num, int type) {
  if (cnt[type][num] > cnt[type][a.first]) a.second = a.first, a.first = num;
  else if (cnt[type][num] > cnt[type][a.second]) a.second = num;
}

int calc(int x, int y) {
  return n - cnt[0][x] - cnt[1][y];
}

int main() {
  ios::sync_with_stdio(false);
  cin >> n;
  for (int i = 1; i <= n; i++) {
    int x; cin >> x; 
    cnt[i % 2][x]++;
  }
  for (int i = 1; i <= 100000; i++) update(b[0], i, 0), update(b[1], i, 1);
  int ans = 0x3f3f3f3f;
  if (b[0].first != b[1].first) ans = min(ans, calc(b[0].first, b[1].first)); 
  if (b[0].second != b[1].first) ans = min(ans, calc(b[0].second, b[1].first));
  if (b[0].first != b[1].second) ans = min(ans, calc(b[0].first, b[1].second)); 
  if (b[0].second != b[1].second) ans = min(ans, calc(b[0].second, b[1].second));
  cout << ans << '\n';
  return 0; 
}

