int main(){
    int n;
    cin >> n;
    vector<int> v(n);
    unordered_map <int, int> odd;
    unordered_map <int, int> even;
    int max_odd = 0, max_even = 0, sec_odd = 0, sec_even = 0;
    int odd_num, even_num;
    for (int i;i<n;i++){
        cin >> v[i];
        if (i % 2){
            if (odd.find(v[i]) == odd.end()){
                odd.insert(make_pair(v[i], 1));
                if (odd[v[i]] > max_odd){
                    max_odd = odd[v[i]];
                    odd_num = v[i];
                }
                else if(odd[v[i]] > sec_odd){
                    sec_odd = odd[v[i]];
                }
            }

            else{
                odd[v[i]]++;
                if (odd[v[i]] > max_odd){
                    if (v[i] != odd_num)
                        sec_odd = max_odd;
                    max_odd = odd[v[i]];
                    odd_num = v[i];
                }
                else if(odd[v[i]] > sec_odd){
                    sec_odd = odd[v[i]];
                }
            }

        }
        else{
            if (even.find(v[i]) == even.end()){
                even.insert(make_pair(v[i], 1));
                if (even[v[i]] > max_even){
                    max_even = even[v[i]];
                    even_num = v[i];
                }
                else if(even[v[i]] > sec_even){
                    sec_even = even[v[i]];
                }
            }

            else{
                even[v[i]]++;
                if (even[v[i]] > max_even){
                    if (v[i] != even_num)
                        sec_even = max_even;
                    max_even = even[v[i]];
                    even_num = v[i];
                }
                else if(even[v[i]] > sec_even){
                    sec_even = even[v[i]];
                }
            }
        }
    }
    int ret = n - max_odd - max_even;
    if (odd_num == even_num){
        if ((max_even + sec_odd) > (max_odd + sec_even))
            ret = n - max_even - sec_odd;
        else
            ret = n - max_odd - sec_even;
    }

    cout << ret;
    return 0;

}

