int main(void)
{
	int n;


	while(scanf("%d", &n)==1)
	{
		vi a(n);
		map<int,int> m_odd, m_even;

		for(int i=0;i<n;i++)
		{
			scanf("%d", &a[i]);
			if(i%2)
			{
				m_odd[a[i]]++;
			}
			else
			{
				m_even[a[i]]++;
			}
		}

		vector<pii> v_odd, v_even;

		for(auto it=m_odd.begin();it!=m_odd.end();++it)
		{
			v_odd.push_back(make_pair(it->second,it->first));
		}
		sort(v_odd.rbegin(), v_odd.rend());
		v_odd.push_back(make_pair(0, -1));

		for(auto it=m_even.begin();it!=m_even.end();++it)
		{
			v_even.push_back(make_pair(it->second,it->first));
		}
		sort(v_even.rbegin(), v_even.rend());
		v_even.push_back(make_pair(0, -1));

		int ans=-1;
		if(v_odd[0].second!=v_even[0].second)
		{
			ans=n-v_odd[0].first-v_even[0].first;
		}
