        if(i%2 == 0) cin>>even[i_even++];
        else cin>>odd[i_odd++];
    }

    sort(even.begin(), even.end());
    sort(odd.begin(), odd.end());

    bool same_flag = true;
    for(int i = 0; i < n/2; i++){
        if(odd[i] != even[i]) same_flag=false;
    }
    if (same_flag){
        cout<<n/2<<endl;
        return 0;
    }

    vector<pair<int, int> > even_count(n/2), odd_count(n/2);

    i_even = 0;
    i_odd = 0;
    int same_even_count = 0, same_odd_count = 0;
    for(int i = 1; i <= n/2; i++){
        if(even[i] == even[i-1]) same_even_count++;
        if(even[i] != even[i-1] || i == n/2 - 1){
            even_count[i_even++] = make_pair(same_even_count + 1, even[i-1]);
            same_even_count = 0;
        }

        if(odd[i] == odd[i-1]) same_odd_count++;
        if(odd[i] != odd[i-1] || i == n/2 - 1){
            odd_count[i_odd++] = make_pair(same_odd_count + 1, odd[i-1]);
            same_odd_count = 0;
        }
    }

    sort(even_count.begin(), even_count.end(), greater<pair<int, int> >());
    sort(odd_count.begin(), odd_count.end(), greater<pair<int, int> >());
    int count = 0;
    if(even_count[0].second == odd_count[0].second) count = max(even_count[1].first + odd_count[0].first, even_count[0].first + odd_count[1].first);
    else count = even_count[0].first + odd_count[0].first;

    cout<<n-count<<endl;

  return 0;
}

