        int x;
        scanf("%d", &x);
        m[i % 2][x]++;
    }
    vector <data> v;
    for (int t = 0; t < 2; t++)
        for (const pair<int, int> &p: m[t]) {
            data d;
            d.x = p.first;
            d.f = p.second;
            d.t = t;
            v.push_back(d);
        }
    sort(v.begin(), v.end(), [](const data a, const data b) {
        if (a.f != b.f)
            return a.f > b.f;
        return a.t < b.t;
    });
    data last;
    int ans = n;
    for (const data &d: v) {
        if (last.t == -1) {
            last = d;
            ans -= d.f;
        } else if (d.x != last.x && d.t != last.t) {
            ans -= d.f;
            break;
        }
    }
    printf("%d\n", ans);
    return 0;
}

