    ++cnt[x][i % 2];
    if(cnt[x][i % 2] >= cnt[memo[i % 2][0]][i % 2] &&
       memo[i % 2][0] != x) {
      memo[i % 2][1] = memo[i % 2][0];
      memo[i % 2][0] = x;
    }
  }
  for(int i = 0; i < 2; ++i)
    for(int j = 0; j < 2; ++j) {
      if(memo[0][i] != memo[1][j])
        mnum = min(mnum, n - cnt[memo[0][i]][0] -
                             cnt[memo[1][j]][1]);
    }
  cout << mnum << endl;
