   int max_odd = 0, max_even = 0;
   for (auto value = begin(even); value != end(even); value++)
   {
      max_even = max(max_even, value->second);
   }
   for (auto value = begin(odd); value != end(odd); value++)
   {
      max_odd = max(max_odd, value->second);
   }
   cout << max_even << max_odd << endl;
   cout << n - max_even - max_odd << endl;
}

