        for(int j=0;j<(int)v2.size();j++){
            if(v2[j].se!=v[i].se){
                cev2=n/2-v2[i].fi;
                break;
            }
        }
        if(cev2==-1) cev+=n/2;
        else cev+=cev2;
        //cout<<"CEV:"<<cev<<endl;
        mn=min(mn,cev);
    }
    printf("%d\n",mn);
    return 0;
}

