#include <bits/stdc++.h>
using namespace std;

class Node {
  public:
    Node() = default;
    int value;
    int cnt;
};

static constexpr int kMaxValue = 100000;

bool has_larger_cnt(const Node& a, const Node& b)
{
  return a.cnt > b.cnt;
}

int main()
{
  int n;
  cin >> n;
  assert(n % 2 == 0);
  vector<Node> odd(kMaxValue+1);
  vector<Node> even(kMaxValue+1);
  for (int i = 0; i <= kMaxValue; i++) {
    even.at(i).value = i;
    odd.at(i).value = i;
  }
  for (int i = 0; i < n; i++) {
    int value;
    cin >> value;
    if (i % 2 == 0) {
      even.at(value).cnt++;
    } else  {
      odd.at(value).cnt++;
    }
  }
  sort(odd.begin(), odd.end(), has_larger_cnt);
  sort(even.begin(), even.end(), has_larger_cnt);
  int result;
  if (odd.at(0).value != even.at(0).value) {
    result = n - odd.at(0).cnt - even.at(0).cnt;
  } else {
    result = n - max(odd.at(0).cnt + even.at(1).cnt, odd.at(1).cnt + odd.at(0).cnt);
  }
  cout << result << endl;
  return 0;
}

