    {
        cnt[i%2][v[i]]++;
    }

    int n0 = (n + 1) / 2;
    int n1 = n / 2;

    vector<pair<int, int>> vlist[2];

    for (auto itr = cnt[0].begin(); itr != cnt[0].end(); itr++) vlist[0].emplace_back(-itr->second, itr->first);
    for (auto itr = cnt[1].begin(); itr != cnt[1].end(); itr++) vlist[1].emplace_back(-itr->second, itr->first);
    sort(vlist[0].begin(), vlist[0].end());
