    int vs0 = 0;
    int vs1 = 0;
    if( vlist[0].size() > 1 ) vs0 = -vlist[0][1].first;
    if( vlist[1].size() > 1 ) vs1 = -vlist[1][1].first;
    return min( n0 + vlist[0][0].first + n1 - vs1, n1 + vlist[1][0].first + n0 - vs0);
}

