using namespace std;

vector<int> vec;
int sum1, sum2;

map<string,int> thread_func(int k, int n, int sum){
	map<string, int> result;
	vector<int> gap;

	for(int i=k;i<n;i=i+2){
		int tmp=0;
		tmp=abs(sum-vec[i]*n/2);
		gap.push_back(tmp);
	}

	auto val =min_element(gap.begin(), gap.end());
	size_t index=distance(gap.begin(),val);
	result["value"]=vec[k+2*index];

	int count=0;
	for(int i=k;i<n;i=i+2){
		if(vec[i]!=result["value"]){
			cout << "v(i)"<<vec[i]<< endl;
			count++;
		}
	}
	result["count"]=count;
	return result;
}

int main(int argc, const char* argv[]){

	int n,v;
	cin >> n;
	for(int i=0;i<n;i++){
		cin >> v;
		vec.push_back(v);
		if(i % 2 ==0){
			sum1+=vec[i];
		}
		else{
			sum2+=vec[i];
		}
	}

	cout << sum1 << " " << sum2 << endl;
	map<string,int> result1;
	map<string,int> result2;

	future<map<string,int>> f1=async(thread_func,0,n,sum1);
	future<map<string,int>> f2=async(thread_func,1,n,sum2);

	result1=f1.get();
	result2=f2.get();

	int output=0;

	if(result1["count"]==0 && result2["count"]==0){
		output=0;
	}else{
		if(result1["value"]==result2["value"]){
			if(result1["count"]>result2["count"]){
				// use result2 value
				output=result2["count"]+n/2;
			}else{
				output=result1["count"]+n/2;
			}
		}else{
			output=result1["count"]+result2["count"];
		}
	}

	cout << output;
	return 0;
}

