ll binpow(ll a, long long b) {
	ll res = 1;
	while (b > 0) {
		if (b & 1)
			res = (res * a);
		a = (a * a);
		b >>= 1;
	}
	return res;
}
const int N = 1e5 + 5;

void solve() {

	int n;
	cin >> n;

	int a[n];
	for (int i = 0 ; i < n ; i++)
		cin >> a[i];
	vector<pair<int, int>> odd , even;

	map<int, int> fr;

	for (int i = 0 ; i < n ; i += 2)
		fr[a[i]]++;
	for (auto x : fr)
		even.pb({x.ss , x.ff});
	fr.clear();

	for (int i = 1 ; i < n ; i += 2)
		fr[a[i]]++;
	for (auto x : fr)
		odd.pb({x.ss , x.ff});

	sort(all(odd)) , reverse(all(odd));
	sort(all(even)) , reverse(all(even));

	int ans = 1e9;

	if (even[0].ss != odd[0].ss)
		ans = min(ans , n - even[0].ff - odd[0].ff);
	else {
		if ((int)even.size() >= 2)
			ans = min(ans , n - even[1].ff - odd[0].ff);
		if ((int)odd.size() >= 2)
			ans = min(ans , n - odd[1].ff - even[0].ff);
		ans = min(ans , n - even[0].ff);
		ans = min(ans , n - odd[0].ff);
	}

	cout << ans << "\n";

}

