  }
  for(int i = 0; i < n; i++){
    if(i%2 == 0)  countEven[v[i]]++;
    else  countOdd[v[i]]++;
  }

  int mostFrequentEven = 0, mostFrequentOdd = 0, secondFrequentEven = 0, secondFrequentOdd = 0;
  int valueEven = 0, valueOdd = 0;

  for(int i = 0; i < 100005; i++){
    if(mostFrequentEven <= countEven[i]){
      secondFrequentEven = mostFrequentEven;
      mostFrequentEven = countEven[i];
      valueEven = i;
    }
    if(mostFrequentOdd <= countOdd[i]){
      secondFrequentOdd = mostFrequentOdd;
      mostFrequentOdd = countOdd[i];
      valueOdd = i;
    }
  }
  int ans;
  if(valueOdd != valueEven){
    ans = (n - (mostFrequentOdd + mostFrequentEven));
  }else{
    ans = min((n - (mostFrequentOdd + secondFrequentEven)), (n - (secondFrequentOdd + mostFrequentEven)));
    ans = min(ans, (n - (secondFrequentOdd + secondFrequentEven)));
