        cnt[i % 2][v[i]]++;
    }
    vector<pair<int, int> > items[2];
    items[0].push_back({0, -1});
    items[1].push_back({0, -2});

    for (int k = 0; k < 2; k++) {
        for (auto e : cnt[k]) {
            items[k].push_back({e.second, e.first});
        }
        sort(items[k].begin(), items[k].end());
    }
    int ans = 1e9;
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 2; j++) {
