class SBSChecker {
private:
  unordered_map<int, int> valMap;
  int maxNVal;
  int type;

public:
  SBSChecker(int t) {
    maxNVal = 0;
    type = t;
  }

  int processNewVal() {
    int v;
    cin >> v;
    valMap[v]++;
    maxNVal = max(maxNVal, valMap[v]);
    return v;
  }

  const unordered_map<int, int>& getValMap() {
    return valMap;
  }
};

int main() {
  size_t n;
  cin >> n;

  unordered_map<int, int> valMap;
  SBSChecker sbs1(1);
  SBSChecker sbs2(2);

  int d = 0;
  int hn = n / 2;
  for (size_t i = 0; i < hn; i++) {
    valMap[sbs1.processNewVal()]++;
    valMap[sbs2.processNewVal()]++;
  }

  if (valMap.size() == 1) {
    d = hn;
  } else {
    const unordered_map<int, int> &valMap1 = sbs1.getValMap();
    const unordered_map<int, int> &valMap2 = sbs2.getValMap();

    int maxNSame = 0;
    for(auto itr=valMap1.begin(); itr!=valMap1.end(); itr++) {
      for(auto itr2=valMap2.begin(); itr2!=valMap2.end(); itr2++) {
        if (itr->first != itr2->first) {
           maxNSame = max(maxNSame, itr->second + itr2->second);
        }
      }
    }

    d = n - maxNSame;
  }

