int main() {
  int n;
  cin >> n;
  vector<int> sum(n);
  for (auto &x: sum) {
    cin >> x;
  }
  map<int,int> mp_evn;
  map<int,int> mp_odd;
  for (int i=0; i < n-1; i+=2) {
    auto itr_evn = mp_evn.find(sum[i]);
    auto itr_odd = mp_odd.find(sum[i+1]);
    if (itr_evn != mp_evn.end()) {
      mp_evn[sum[i]] += 1;
    } else {
      mp_evn[sum[i]] = 1;
    }
    if (itr_odd != mp_odd.end()) {
      mp_odd[sum[i+1]] += 1;
    } else {
      mp_odd[sum[i+1]] = 1;
    }
  }
  // 最貧
  auto e1 = max_element(mp_evn.begin(), mp_evn.end(),
    [](const pair<int, int>& p1, const pair<int, int>& p2) {
        return p1.second < p2.second; });
  auto o1 = max_element(mp_odd.begin(), mp_odd.end(),
    [](const pair<int, int>& p1, const pair<int, int>& p2) {
        return p1.second < p2.second; });
  auto e1_val = e1->second;
  auto o1_val = o1->second;
  mp_evn.erase(e1);
  mp_odd.erase(o1);
  auto e2 = max_element(mp_evn.begin(), mp_evn.end(),
    [](const pair<int, int>& p1, const pair<int, int>& p2) {
        return p1.second < p2.second; });
  auto o2 = max_element(mp_odd.begin(), mp_odd.end(),
    [](const pair<int, int>& p1, const pair<int, int>& p2) {
        return p1.second < p2.second; });
  auto e2_val = e2->second;
  auto o2_val = o2->second;
  int num = n / 2;
  int sum1 = (num - e1_val) + o2_val == 0 ? 0:(num - o2_val);
  int sum2 = (num - o1_val) + e2_val == 0 ? 0:(num - e2_val);
  if (sum1 >= sum2) {
    cout << sum2;
  } else {
    cout << sum1;
  }
}

