vector<pair<int,int>> CU(vector<int> S){
  vector<pair<int,int>> SS;
  sort(S.begin(),S.end());
  int temp=S.at(0);
  SS.push_back(make_pair(1,temp));
  for(int i=1;i<(int)S.size();i++){
    int s=S.size();
    temp=S.at(i);
    if(S.at(i)==S.at(i-1)) SS.at(s-1).first++;
    else SS.push_back(make_pair(1,temp));
  }
  sort(SS.begin(),SS.end());
  reverse(SS.begin(),SS.end());
  return SS
}


