        add_edge(mn, --mx);
        if(i*2 != n)
          add_edge(ones - mn, --mx);
      } else {
        mn++;
      }
    }

    if((int)ans.size() != n-1) {
      cout << -1 << endl;
      return 0;
    }

    for(ii e : ans) cout << e.ff+1 << " " << e.ss+1 << "\n";
  }
}

