int calcola(int N, int V[], int in){
    int prec = V[in];
    int lun = 1, lunMigl = 1;
    int vMig = V[0];
    for(int i = in + 2; i < N; i+=2){
        if(V[i] == prec && V[i] != V[i - 1])
            lun += 1;
        else{
            if(lun > lunMigl){
                lunMigl = lun;
                vMig = V[i];
            }
            lun = 1;
        }
    }

    if(lun > lunMigl){
        lunMigl = lun;
    }

    return (int)((N/2) - lunMigl);
}

