	int Min1 = 1e9 + 7;
	int Min3 = 1e9 + 7;
	int cnt = 0;
	for(int i = 1; i <= n; i += 2){
		if(pos - dis[a[i]] <= Min1 && qwe[a[i]] != 1){
			if(Min1 <= Min3){
				Min3 = Min1;
				er3 = er1;
			}
			Min1 = pos - dis[a[i]];
			er1 = a[i];
		}
	}
	cnt = 0;
	int Min2 = 1e9 + 7;
	int Min4 = 1e9 + 7;
	qwe.clear();
	for(int i = 2; i <= n; i += 2){
		if((n - pos) - vis[a[i]] <= Min2 && qwe[a[i]] != 1){
			if(Min2 <= Min4){
				Min4 = Min2;
				er4 = er2;
			}
			Min2 = (n - pos) - vis[a[i]];
			er2 = a[i];
		}
	}
	if(n == 1) printf("0\n");
	else if(n == 2){
		if(a[1] == a[2]) printf("1\n");
		else printf("0\n");
	}
	else if(er1 != er2) printf("%d\n", Min1 + Min2);
	else{
		int Min = 1e9 + 7;
		if(Min3 != 1e9 + 7 && er3 != er2){
			Min = min(Min, Min3 + Min2);
		}
		if(Min3 != 1e9 + 7 && Min4 != 1e9 + 7 && er3 != er4){
			Min = min(Min, Min3 + Min4);
		}
		if(Min4 != 1e9 + 7 && er1 != er4){
			Min = min(Min, Min1 + Min4);
		}
		if(Min == 1e9 + 7) printf("%d\n", min(pos, n - pos));
		else printf("%d\n", Min);
	}
}

