ll gcd(ll a, ll b)
{
    if(a*b == 0)
    {
        return 0;
    }

    if(a < b)
    {
        swap(a,b);
    }

    while(b != 0)
    {
        a %= b;
        swap(a, b);
    }

    return a;
}

