			++cnt2[a[i]];
		}
	}
	for (int i = 1; i <= 100000; ++i) {
		mnL1[i] = n / 2 - cnt1[i];
		mnR1[i] = n / 2 - cnt1[i];
		mnL2[i] = n / 2 - cnt2[i];
		mnR2[i] = n / 2 - cnt2[i];
	}
	for (int i = 1; i <= 100000; ++i) {
		mnL1[i] = min(mnL1[i - 1], mnL1[i]);
		mnL2[i] = min(mnL2[i - 1], mnL2[i]);
	}
	for (int i = 100000; i >= 1; --i) {
		mnR1[i] = min(mnR1[i + 1], mnR1[i]);
		mnR2[i] = min(mnR2[i + 1], mnR2[i]);
	}
