ll n, v, even[100008], odd[100008];

int main() {
	cin >> n;
	for(ll i = 1; i <= n; i++){
		cin >> v;
		if(i%2 == 0){even[v]++;}
		else{odd[v]++;}
	}

	ll emax1 = 0; ll e1 = -1;
	ll emax2 = 0; ll e2 = -1;
	ll omax1 = 0; ll o1 = -1;
	ll omax2 = 0; ll o2 = -1;
	for(ll i = 1; i <= 100000; i++){
		if(even[i] > emax1){
			emax2 = emax1;
			emax1 = even[i];
			e2 = e1;
			e1 = i;
		}
		else{
			if(even[i] > emax2){
				emax2 = even[i];
				e2 = i;
			}
		}
	}
	for(ll i = 1; i <= 100000; i++){
		if(odd[i] > omax1){
			omax2 = omax1;
			omax1 = odd[i];
			o2 = o1;
			o1 = i;
		}
		else{
			if(odd[i] > omax2){
				omax2 = odd[i];
				o2 = i;
			}
		}
	}	

	ll ans = n;
	if(e1 == o1){
		if(emax1 > omax1){ans -= emax1+omax2;}
		if(emax1 < omax1){ans -= emax2+omax1;}
		if(emax1 == omax1){ans -= (emax2 > omax2)? omax1+emax2 : emax1+omax2;}
	}
	else{
		ans -= emax1+omax1;
	}

	cout << ans;
	return 0;
}

