    FOR (i, 0, N) cnt[i].idx = i;
    for (int& x: V) ++cnt[x].c;
    sort(cnt, cnt + N);
    return {cnt[0], cnt[1]};
}

int main() {
    int n; cin >> n;
    FOR (i, 0, n) cin >> a[i];
    FOR (i, 0, n) if (i & 1) V.push_back(a[i]);
    auto t1 = go();

    V.clear();
    FOR (i, 0, n) if (!(i & 1)) V.push_back(a[i]);
    auto t2 = go();

    int ans = t1.first.idx == t2.first.idx ?
            max(t1.first.c + t2.second.c, t1.second.c + t2.first.c) :
            t1.first.c + t2.first.c;
    cout << n - ans << endl;
}

