vector<pair<int, int>> hist_to_vector(const map<int, int> &h)
{
	vector<pair<int, int>> v;
	for (const auto &e : h) {
		v.emplace_back(e.second, e.first);
	}
	sort(v.begin(), v.end());
	return v;
}

int main()
{
	int n;
	cin >> n;

	map<int, int> hist_e, hist_o;

	hist_e[-2] = 0;
	hist_o[-1] = 0;
	for (int i = 0; i < n; ++i) {
		int v;
		cin >> v;
		if (i % 2 == 0) {
			++hist_e[v];
		}
		else {
			++hist_o[v];
		}
	}

	const vector<pair<int, int>> v_e = hist_to_vector(hist_e);
	const vector<pair<int, int>> v_o = hist_to_vector(hist_o);

	int ans = n;
	for (auto &e : v_e) {
		for (int k = v_o.size() - 1; k >= 0; --k) {
			auto &o = v_o[k];
			if (e.second != o.second) {
				int tmp = (n / 2 - e.first) + (n / 2 - o.first);
				if (tmp >= ans) {
					break;
				}
				ans = tmp;
			}
		}
	}

	cout << ans << endl;
}

