int solve(vector<int>v){
   map<int,int>mp1,mp2;
   int ans1=0,ans2=0;
   int f1=-1,f2=-1,s1=-1,s2=-1;
   for(int i=0;i<n;i+=2){
       mp1[v[i]]++;
       if(f1==-1||mp1[v[i]]>mp1[f1]){
          ans1=mp1[v[i]];
          s1=f1;
          f1=v[i];
       }
       else if(s1==-1||mp1[v[i]>mp1[s1]]){
           if(v[i]!=f1)s1=v[i];
       }
   }
   for(int i=1;i<n;i+=2){
       mp2[v[i]]++;
       if(f2==-1||mp2[v[i]]>mp2[f2]){
          ans1=mp2[v[i]];
          s2=f2;
          f2=v[i];
