using namespace std;
struct wave{
	int num1,num2;
	long long total;
};
int main(){
	int i,n,ans,max=0,maxx=0;
	struct wave a[50005];
	scanf("%d",&n);
	for(i=1;i<=n/2;i++) {
		scanf("%d%d",&a[i].num1,&a[i].num2);
		a[i].total=11111*a[i].num1+a[i].num2;
	}
	for(i=1;i<=n/2;i++)
	{
		int sum=0;
		//if(a[i].num1!=a[i].num2)
		do{
			sum++;
			i++;
		}while(a[i].num1==a[i-1].num1 && i<=n/2);
		if(sum>max) max=sum;
	}
	for(i=1;i<=n/2;i++)
	{
		int summ=0;
		if(a[i].num1!=a[i].num2)
		do{
			summ++;
			i++;
		}while(a[i].total==a[i-1].total && i<=n/2);
		if(summ>maxx) maxx=summ;
	}

	ans=n-maxx-max;
	printf("%d",ans);
