bool cmp (pii a, pii b) {
    return a.ff < b.ff;
}

int n;
int f[100005];
int g[100005];
int a[100005];
vector <pii> even;
vector <pii> odd;

int main() {
//    freopen("codef.inp", "r", stdin);
//    freopen("codef.out", "w", stdout);

    scanf("%d", &n);
    fto(i, 1, n) scanf("%d", &a[i]);

    fto(i, 1, n) {
        if (i%2) {
            if (!f[a[i]]) odd.pb(mp(1, a[i]));
            ++f[a[i]];
        }
        else {
            if (!g[a[i]]) even.pb(mp(1, a[i]));
            ++g[a[i]];

        }
    }

    if (odd.size() == 1 && even.size() == 1) {
        if (a[1] == a[2]) printf("%d\n", n/2);
        if (a[1] != a[2]) printf("%d\n", 0);
    }
    else {

        fto(i, 0, (int) odd.size()-1) {
            odd[i].ff = f[odd[i].ss];
        }

        fto(i, 0, (int) even.size()-1) {
            even[i].ff = g[even[i].ss];
        }
        sort(odd.begin(), odd.end(), cmp);
        sort(even.begin(), even.end(), cmp);

        int res;

        if (odd.size() == 1) {
            if (odd[0].ss == even[0].ss) res = n/2-even[1].ff;
            else res = n/2-even[0].ff;
