        if (even.size() == 1) {
            if (odd[0].ss == even[0].ss) res = n/2-odd[1].ff;
            else res = n/2-odd[0].ff;
        }

        if (even.size() != 1 && odd.size() != 1) {
            res = n-odd[0].ff-even[0].ff;
            if (odd[0].ss == even[0].ss)
                n = min(n-odd[0].ss-even[1].ss, n-odd[1].ss-even[0].ss);
        }

        printf("%d\n", res);
    }


    return 0;
}

