void add(int x, int p) {
    ++c[x];
    if(c[x] > mx[p]) {
        mx[p] = c[x];
        mxv[p] = x;
    } else if(c[x] > mx[p + 1]) {
        mx[p + 1] = c[x];
        mxv[p + 1] = x;
    }
}
