int main()
{
	int n;
	cin >> n;

	map<int, int> a, b;
	for (int i = 0; i < n; i++)
	{
		int x;
		cin >> x;
		if (i % 2 == 0)
		{
			a[x]++;
		}
		else
		{
			b[x]++;
		}
	}

	int m = n / 2;

	vector<pair<int, int>> ap;
	for (map<int, int>::iterator it = a.begin(); it != a.end(); it++)
	{
		pair<int, int> i = *it;
		ap.push_back(make_pair(i.second, i.first));
	}

	sort(ap.begin(), ap.end());
	reverse(ap.begin(), ap.end());

	vector<pair<int, int>> bp;
	for (map<int, int>::iterator it = b.begin(); it != b.end(); it++)
	{
		pair<int, int> i = *it;
		bp.push_back(make_pair(i.second, i.first));
	}

	sort(bp.begin(), bp.end());
	reverse(bp.begin(), bp.end());

	int ans = 0;
	if (a.size() == 1 && b.size() == 1)
	{
		if (ap.front().second == bp.front().second)
		{
			ans = m;
		}
		else
		{
			ans = 0;
		}
	}
	else
	{
		if (ap.front().first == bp.front().first)
		{
			if (ap.front().second == bp.front().second)
			{
				if (ap.at(1).first > bp.at(1).first)
				{
					ans = (m - bp.front().first) + (m - ap.at(1).first);
				}
				else
				{
					ans = (m - ap.front().first) + (m - bp.at(1).first);
				}
			}
			else
			{
				ans = 2 * (m - ap.front().first);
			}
		}
		else
		{
			if (ap.front().first > bp.front().first)
			{
				ans = m - bp.front().first;
			}
			else
			{
				ans = m - ap.front().first;
			}
		}
	}

	cout << ans << endl;
}

