      A_conti = 1;
    }
  }

  auto A_itr = A_set.begin();
  int A_size = A_set.size();
  int A_mode1_cnt = 1;
  int A_mode2_cnt = 1;

  if(A_size == 1){
    std::cout << n/2 << '\n';
