  }

  REP0(i,A_size){
    if (A_mode1_cnt <= A_hist[*(A_itr)]) {
      A_mode2_cnt = A_mode1_cnt;
      A_mode1_cnt = A_hist[*(A_itr)];

    }
    A_itr = ++A_itr;
  }

  std::cout << n - (A_mode1_cnt + A_mode2_cnt) << '\n';

}

