    for (int i = 1; i < n + 1; i++)
    {
        cin >> buf;
        if (i % 2 == 0)
        {
            if (num_cnt_even.find(buf) == num_cnt_even.end())
            {
                num_cnt_even[buf] = 1;
            }
            else
            {
                num_cnt_even[buf] += 1;
            }
        }
        else
        {
            if (num_cnt_odd.find(buf) == num_cnt_odd.end())
            {
                num_cnt_odd[buf] = 1;
            }
            else
            {
                num_cnt_odd[buf] += 1;
            }
        }
    }
    int ok_max_even = 0;
    int ok_second_even;
    int ok_id_even;
    int ok_max_odd = 0;
    int ok_second_odd;
    int ok_id_odd;
    for (auto const &x : num_cnt_even)
    {
        if (x.second > ok_max_even)
        {
            ok_second_even = ok_max_even;
            ok_id_even = x.first;
            ok_max_even = x.second;
        }
    }
    for (auto const &x : num_cnt_odd)
    {
        if (x.second > ok_max_odd)
        {
            ok_second_odd = ok_max_odd;
            ok_id_odd = x.first;
            ok_max_odd = x.second;
        }
    }
    if (ok_id_even == ok_id_odd)
    {
        int ans;
        if (ok_max_even > ok_max_odd)
        {
            ans = n - ok_max_even - ok_second_odd;
        }
        else if (ok_max_even < ok_max_odd)
        {
            ans = n - ok_max_odd - ok_second_even;
        }
        else
        {
            ans = ok_second_even > ok_id_odd ? n - ok_max_odd - ok_second_even : n - ok_max_even - ok_second_odd;
        }
        cout << ans << endl;
    }
    else
    {
        cout << n - ok_max_even - ok_max_odd << endl;
    }
    return 0;
}

