        N = loadint();
        if (N==0) return 0;
    }
    int bufsize = INTSPACE*N + 3;
    if (fgets(_buf, bufsize, stdin)==NULL) return 0;
    v.resize(N);

    int i=0;
    bool last = false;
    for (char *p=&_buf[0]; ;) {
        char *q = p;
        while (*q > ' ') ++q;
        if (*q == 0x0D || *q == 0x0A) last = true;
        *q = 0;
        v[i++] = atoi(p);
        if (last || i == N) break;
        p = q+1;
    }
    // assert(i <= N);
    return i;
}
void read_cr() {
    fgets(_buf, 256, stdin);
}

int solve(int N, vi& a) {
    map<int,int> m0,m1;
    int L0=0, L1=0;
    rep(i,N){
        if (i%2) {
            m0[a[i]]++;
            ++L0;
        } else {
            m1[a[i]]++;
            ++L1;
        }
    }
    m0[-1] = m1[-1] = 0; // centinel
    vector<ii> v0, v1;
    for(ii p: m0) {
        v0.pb(ii(L0-p.second, p.first));
    }
    sort(ALL(v0)); // reverse(ALL(v0));
    for (ii p : m1) {
      v1.pb(ii(L1-p.second, p.first));
    }
    sort(ALL(v1)); // reverse(ALL(v1));

    if (v0[0].second != v1[0].second) {
        return v0[0].first + v1[0].first;
    } else {
        return min(
            v0[0].first + v1[1].first,
            v0[1].first + v1[0].first
        );
    }

}

