    for (int i = 1; i <= n; i++) cin >> a[i];
    if (n == 2) {
        int ans = a[1] == a[2] ? 1 : 0;
        cout << ans << endl;
        return 0;
    }
    map<int, int> m1, m2;
    for (int i = 1; i <= n; i++) {
        if (i % 2 == 1) m1[a[i]]++;
        else m2[a[i]]++;
    }
    map<int, int>::iterator iter = m1.begin();
    map<int, int>::iterator m1_f = iter,m1_s = iter;
    while (iter != m1.end()) {
        if (iter->second >= m1_f->second) {
            m1_f = iter;
        }
        iter++;
    }
    iter = m1.begin();
    while (iter != m1.end()) {
        if (iter != m1_f) {
            if (iter->second >= m1_s->second) {
                m1_s = iter;
            }
        }
        iter++;
    }
    iter = m2.begin();
    map<int, int>::iterator m2_f = iter,m2_s = iter;
    while (iter != m2.end()) {
        if (iter->second >= m2_f->second) {
            m2_f = iter;
        }
        iter++;
    }
    iter = m2.begin();
    while (iter != m2.end()) {
        if (iter != m2_f) {
            if (iter->second >= m2_s->second) {
                m2_s = iter;
            }
        }
        iter++;
    }
    int ans = 0;
    if (m1_f->first != m2_f->first) {
        ans = n - m1_f->second - m2_f->second;
    } else {
        int t1 = n, t2 = n;
        int k11 = 0, k12 = 0, k21 = 0, k22 = 0;
        if (m1_f->first == m1_s->first) {
            k11= m1_f->second;
        } else {
            k11 = m1_f->second;
            k12 = m1_s->second;
        }
        if (m2_f->first == m2_s->first) {
            k21 = m2_f->second;
        } else {
            k21 = m2_f->second;
            k22 = m2_s->second;
        }
        t1 = n - k12 - k21;
        t2 = n - k11 - k22;
        ans = min(t1, t2);
    }
    cout << ans << endl;
}

