int n, ans, a[maxn];

int read()
{
	int x = 0, k = 1;
	char c; c = getchar();
	while(c < '0' || c > '9') { if(c == '-') k = -1; c = getchar(); }
	while(c >= '0' && c <= '9') x = x * 10 + c - '0', c = getchar();
	return x * k; 
}

struct node
{
	int sum, num;
	friend bool operator <(const node& a, const node& b)
	{ return a.sum > b.sum; }
}odd[maxn], even[maxn];

int main()
{
	n = read();
	for(int i = 1; i <= n; i ++) a[i] = read();
	for(int i = 1; i <= n; i ++)
	{
		if(i & 1) odd[a[i]].sum ++;
		else even[a[i]].sum ++;
	}
	for(int i = 1; i < maxn; i ++) odd[i].num = i, even[i].num = i;
	sort(odd + 1, odd + maxn); sort(even + 1, even + maxn);
	if(odd[1].num != even[1].num) ans = odd[1].sum + even[1].sum;
	else
	{
		ans = max(ans, odd[1].sum + even[2].sum);
		ans = max(ans, odd[2].sum + even[1].sum);
	}
	cout << n - ans << endl;
	return 0;
}

