            }
            else
            {
                num_cnt_even[buf] += 1;
            }
        }
        else
        {
            if (num_cnt_odd.find(buf) == num_cnt_odd.end())
            {
                num_cnt_odd[buf] = 1;
            }
            else
            {
                num_cnt_odd[buf] += 1;
            }
        }
    }
