using i64 = long long;
#define rep(i,s,e) for(int (i) = (s);(i) <= (e);(i)++)
#define refor(x, v) for(auto& x: v)
#define all(x) x.begin(),x.end()

vector<pair<int,int>> calc(const std::vector<i64> A) {
  vector<i64> cnt(101010,0);
  refor(x, A) {
    cnt[x]++;
  }
  int i = max_element(all(cnt)) - begin(cnt);
  int mi = cnt[i];
  cnt[i] = 0;
  int j = max_element(all(cnt)) - begin(cnt);
  int mj = cnt[j];
  return { { mi, i }, { mj, j } };
}

int main() {
  std::size_t n;
  cin >> n;
  std::vector<i64> v(n);
  refor(x, v) cin >> x;
  std::vector<i64> a[2];
  for(int i = 0;i < n;i++) {
    a[i & 1].push_back(v[i]);
  }

  auto A = calc(a[0]);
  auto B = calc(a[1]);
  if(A[0].second != B[0].second) {
    cout << n - A[0].first - B[0].first << endl;
  }
  else {
    cout << n - max(A[0].first + B[1].first, A[1].first + B[0].first) << endl;
  }
}

