void solve() {
    int n;
    cin >> n;

    veci v(n);
    for (int i=0; i<n; ++i) {
        cin >> v[i];
    }

    veci odd(int(1e5+1),0);
    veci even(int(1e5+1),0);
    for (int i=0; i<n; ++i) {
        if (i%2) {
            odd[v[i]] += 1;
        } else {
            even[v[i]] += 1;
        }
    }

    veci oddidx(int(1e5+1));
    veci evenidx(int(1e5+1));
    for (int i=0; i<=int(1e5); ++i) {
        oddidx[i] = i;
        evenidx[i] = i;
    }

    sort(oddidx.rbegin(), oddidx.rend(), [&odd](int l, int r) { return odd[l]<odd[r];});
    sort(evenidx.rbegin(), evenidx.rend(), [&even](int l, int r) { return even[l]<even[r];});

    int cnt = n-odd[oddidx[0]]-even[evenidx[0]];
    if (oddidx[0] == evenidx[0]) {
        int maxi = min(-odd[oddidx[0]],-even[evenidx[0]]);
        if (oddidx[1]) {
            maxi = max(maxi, odd[oddidx[0]] - odd[oddidx[1]]);
        }

        if (evenidx[1]) {
            maxi = max(maxi, even[evenidx[0]] - even[evenidx[1]]);
        }

        cnt += maxi;
    }

    cout << cnt << endl;
}

