vector<pii> counting(const vector<int> vec)
{
    map<int, int> num_cnt;
    rep(i, 0, vec.size()) num_cnt[vec[i]]++;

    int max_cnt = 0;
    vector<pii> cnt_num;
    for (auto n_c: num_cnt)
        cnt_num.emplace_back(n_c.second, n_c.first);
    sort(cnt_num.begin(), cnt_num.end());
    reverse(cnt_num.begin(), cnt_num.end());    
    return cnt_num;
}

int main()
{
    int n;
    cin >> n;
    vector<int> odds, evens;
    rep(i, 0, n)
    {
        int v;
        cin >> v;
        if (i % 2 == 0)
            evens.push_back(v);
        else
            odds.push_back(v);
    }
    vector<pii> cnt_num_even = counting(evens);
    vector<pii> cnt_num_odd = counting(odds);
    int ans = evens.size() + odds.size();
    if (cnt_num_even[0].second != cnt_num_odd[0].second)
        ans -= cnt_num_even[0].first + cnt_num_odd[0].first;
    else
    {
        if (cnt_num_even.size() == 1 and cnt_num_odd.size() == 1)
            ans -= evens.size();
        else if (cnt_num_even[0].first > cnt_num_odd[0].first)
        {
            ans -= cnt_num_even[0].first;
            if (cnt_num_odd.size() > 1)
                ans -= cnt_num_odd[1].first;
        }
        else
        {
            ans -= cnt_num_odd[0].first;
            if (cnt_num_even.size() > 1)
                ans -= cnt_num_even[1].first;
        }
    }
    cout << ans << endl;

    return 0;
}

