const int MAXN = 1e5 + 10;
int n, a[MAXN], cnt[MAXN];
struct Node {
  int cc, id;
  bool operator <(const Node &rhs) const {
    return cc > rhs.cc;
  }
} b[MAXN], ans1[4];
void work() {
  scanf("%d", &n);
  for(reg int i = 1; i <= n; ++i) scanf("%d", &a[i]);
  for(reg int i = 1; i <= n; i += 2) ++cnt[a[i]];
  int tot = 0;
  for(reg int i = 1; i <= MAXN - 10; ++i) b[++tot].cc = cnt[i], b[tot].id = i;
  sort(b + 1, b + tot + 1);
  ans1[0] = b[1], ans1[1] = b[2];
  memset(cnt, 0, sizeof(cnt)), tot = 0;
  for(reg int i = 2; i <= n; i += 2) ++cnt[a[i]];
  for(reg int i = 1; i <= MAXN - 10; ++i) b[++tot].cc = cnt[i], b[tot].id = i;
  sort(b + 1, b + tot + 1);
  ans1[2] = b[1], ans1[3] = b[2];
  int mx = 0;
  for(reg int i = 0; i <= 1; ++i) {
    for(reg int j = 2; j <= 3; ++j) {
      if(ans1[i].id != ans1[j].id) mx = max(mx, ans1[i].cc + ans1[j].cc);
    }
  }
  printf("%d\n", n - mx);
}
signed main() {
  int _ = 1;
  // scanf("%d", &_);
