vector<pair<int, int>> max_freq(map<int, int> freq) {
    vector<pair<int, int>> pair_freq;

    for (auto it : freq)
        pair_freq.emplace_back(it.second, it.first);

    sort(pair_freq.rbegin(), pair_freq.rend());
    return pair_freq;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<int> V(N);

    for (int &v : V)
        cin >> v;

    map<int, int> freq[2];

    for (int i = 0; i < N; i++)
        freq[i % 2][V[i]]++;

    vector<pair<int, int>> pair_freq[2] = {max_freq(freq[0]), max_freq(freq[1])};
    pair_freq[0].emplace_back(0, -1);
    pair_freq[1].emplace_back(0, -1);

    int keep = pair_freq[0].front().first + pair_freq[1].front().first;

