#define REP(i, n) for(int i=0;i<(n);++i)
#define RREP(i, n) for(int i=(n)-1;i>=0;--i)

signed main() {
  INIT;
	VAR(int, n);
	VEC(int, v, n);

	vector< int > p(MAX_N, 0);
	vector< int > q(MAX_N, 0);
	REP(i, n) {
		if (i % 2 == 1) {
			p[v[i]]++;
		} else {
			q[v[i]]++;
		}
	}

	int mx = 0, m = 0;
	int mnx = 0, mn = 0;
	REP(i, MAX_N) {
		if (p[i] >= mx) {
			mnx = mx;
			mn = m;
			mx = p[i];
			m = i;
		}
	}

	int ans = 0;
	REP(i, n) {
		int N = v[i++];
		int res = q[N];

		if (N == m) {
			res += mnx;
		} else {
			res += mx;
		}

		ans = max(res, ans);
	}

	OUT(n - ans)BR;

  return 0;
}

