using namespace std;

ll common_counter(vector<ll> v, ll& most_common) {
    ll max = 0;
    map<ll,ll> m;
    for (auto vi = v.begin(); vi != v.end(); vi++) {
        m[*vi]++;
        if (m[*vi] > max) {
            max = m[*vi]; 
            most_common = *vi;
        }
    }
    return max;
}

ll common_counter_ignore(vector<ll> v, ll ignore) {
    ll max = 0;
    map<ll,ll> m;
    for (auto vi = v.begin(); vi != v.end(); vi++) {
        if (*vi == ignore) continue;
        m[*vi]++;
        if (m[*vi] > max) {
            max = m[*vi];
        }
    }
    return max;
}

int main(void){
    cin.tie(0);
