    int n; cin >> n;
    vector<int> even;
    vector<int> odd;
    vector<int> v(n); REP (i, n) cin >> v[i];
    REP(i, n) {
        if (i % 2 == 1) {
            odd.push_back(v[i]);
        } else {
            even.push_back(v[i]);
        }
    }

    int even_most = -1;
    int even_com_c = common_counter(even, even_most);
    int odd_most = -1;
    int odd_com_c = common_counter(odd, odd_most);

    if (even_most != odd_most) {
        cout << n - even_com_c - odd_com_c << endl;
        return 0;
    }

    cout << n - max(odd_com_c + common_counter_ignore(even, even_most), even_com_c + common_counter_ignore(odd, even_most)) << endl;

    return 0;
}

