typedef pair<int, int> P;
bool customCompare(const P& firstElof, const P& secondElof)
{
    return firstElof.first >= secondElof.first;
}
/**
* /\/\/\/
* @brief 奇数個目で一番頻出のやつ(A1)がなにかを調べる
*        偶数個目で同様に行い(B1)、N - (A1+B1)を回答。ただし、A1=B1の場合は、次に多くでてくるやつにする(A2>=B2ならA2)
*        すべてA2がない場合は、B2。B2もなければ、無なので、N-A1+0となる
*/
int main(){
    int N,tmp;
    vector<pair<int,int>> v_odd(100001);
    vector<pair<int,int>> v_even(100001);

    int A,B;

    cin >> N;

    for(int i = 0; i < 100001; i++)
    {
        v_odd[i].first = 0;
        v_odd[i].second = i;
        v_even[i].first = 0;
        v_even[i].second = i;
    }

    for(int i = 0; i < N; i++)
    {
        cin >> tmp;
        if(i % 2 == 0)v_even.at(tmp).first++;
        else{v_odd.at(tmp).first++;}
    }

    //降順に並べる
    sort(v_odd.begin(),v_odd.end(),customCompare);
    sort(v_even.begin(),v_even.end(),customCompare);

    //配列番号がほしい
    //std::vector<int>::iterator max_odd_iter = std::max_element(v_odd.begin(), v_odd.end());
    //int max_odd_index = std::distance(v_odd.begin(), max_odd_iter);

    if(v_odd[0].second == v_even[0].second)
    {
        //A2を取得
        //A1を削除してmaxを取得
        if(v_odd[1].second >= v_even[1].second)
        {
            A = v_even[1].first;//0でも大丈夫
            B = v_even[0].first;
        }
        else
        {
            A = v_even[0].first;
            B = v_even[1].first;
        }
    }
    else
    {
        A = v_odd[0].first;
        B = v_even[0].first;
    }
    cout << N - (A + B) << endl;
}

