using namespace std;

typedef vector<int> vi;
typedef pair<int, int> pii;

bool compare(pii a, pii b) {
  return a.second > b.second;
}

vector<pii> solve(vi& v) {
  map<int, int> mapka;

  for (auto& it : v) {
    mapka[it]++;
  }

  vector<pii> occurence(mapka.begin(), mapka.end());
  sort(occurence.begin(), occurence.end(), compare);

  return occurence;
}


