#include <bits/stdc++.h>

using namespace std;

void solve() {
    int n;
    cin >> n;
    map<int, int> odd, even;
    for (int i = 0; i < n; i++) {
        int v; cin >> v;
        if (i % 2 == 0) even[v]++;
        else odd[v]++;
    }

    vector<pair<int, int> > vtodd, vteven;
    for (auto x : odd) vtodd.push_back({x.second, x.first});
    for (auto x : even) vteven.push_back({x.second, x.first});
    sort(vtodd.rbegin(), vtodd.rend());
    sort(vteven.rbegin(), vteven.rend());

    int ans = n;
    for (int i = 0; i < min((int)vtodd.size(), 2); i++) {
        for (int j = 0; j < min((int)vteven.size(), 2); j++) {
            if (vtodd[i].second == vteven[j].second) {
                ans = min(ans, n - vtodd[i].first);
                ans = min(ans, n - vteven[j].first);
            }
            else {
                ans = min(ans, n - vtodd[i].first - vteven[j].first);
            }
        }
    }
    cout << ans;
}

int main() {
    ios::sync_with_stdio(NULL), cin.tie(0), cout.tie(0);
    cout.setf(ios::fixed), cout.precision(20);
    solve();
}

