    if( a.Se != d.Se ) ans = min(ans, c1+c2 - a.Fi - d.Fi );
    if( b.Se != c.Se ) ans = min(ans, c1+c2 - b.Fi - c.Fi );
    if( b.Se != d.Se ) ans = min(ans, c1+c2 - b.Fi - d.Fi );
    if( sz(v1) == 1 ) ans = min(ans, c2);
    if( sz(v2) == 1 ) ans = min(ans, c1);

    printf("%d\n",ans);
