int main()
{
    //freopen("input.txt", "r", stdin);
    int n;
    cin >> n;
    for (int i = 0; i < n; ++i) {
        cin >> m[i];
    }
    for (int i = 0; i < n; i += 2) {
        cnt[m[i]]++;
    }
    int mx = 1;
    for (int i = 2; i < max_n; ++i) {
        if (cnt[i] > cnt[mx]) {
            mx = i;
        }
    }
    int mx1 = 1;
    if (mx == 1) mx1 = 2;
    for (int i = 2; i < max_n; ++i) {
        if (i == mx) continue;
