        if (cnt1[i] > cnt1[mx2]) {
            mx2 = i;
        }
    }
    int mx3 = 1;
    if (mx2 == 1) mx3 = 2;
    for (int i = 2; i < max_n; ++i) {
        if (i == mx2) continue;
