#define MAX_N 100000
//#define DEBUG

int n;
int ar1[MAX_N];
int ar2[MAX_N];
int ans = 0;

void read()
{
    cin >> n;
    ans = n;
    int tmp1;
    int tmp2;
    REP(i, 0, n/2)
    {
        cin >> tmp1 >> tmp2;
        ar1[tmp1]++;
        ar2[tmp2]++;
    }
}
void solve()
{
    pair<int, int> max1 = make_pair(0, 0);
    int max2 = 0;
    pair<int, int> max3 = make_pair(0, 0);
    int max4 = 0;
    REP(i, 0, MAX_N)
    {
        if (ar1[i] > max1.second)
        {
            if (max1.second > max2)
            {
                max2 = max1.second;
            }
            max1.first = i;
            max1.second = ar1[i];
        }
        else if (ar1[i] > max2)
        {
            max2 = ar1[i];
        }
        if (ar2[i] > max3.second)
        {
            if (max3.second > max4)
            {
                max4 = max3.second;
            }
            max3.first = i;
            max3.second = ar2[i];
        }
        else if (ar2[i] > max4)
        {
            max4 = ar2[i];
        }
    }
#ifdef DEBUG
    cout << "候補" << endl;
    cout << max1.first << " : " << max1.second << endl;
    cout << max2 << endl;
    cout << "候補" << endl;
    cout << max3.first << " : " << max3.second << endl;
    cout << max4 << endl;
#endif
    if (max1.first == max3.first)
    {
        if (max1.second > max3.second)
        {
            ans -= max1.second;
            ans -= max4;
        }
        else if (max1.second < max3.second)
        {
            ans -= max3.second;
            ans -= max2;
        }
        else
        {
            if (max2 > max4)
            {
                ans -= max2;
                ans -= max3.second;
            }
            else
            {
                ans -= max1.second;
                ans -= max4;
            }
        }
    }
    else
    {
        ans -= max1.second;
        ans -= max3.second;
    }
}
void print()
{
    cout << ans << endl;
}
int main()
{
#ifdef DEBUG
    cout << "DEBUG MODE" << endl;
#else
    cin.tie(0);
    cout.tie(0);
    ios::sync_with_stdio(false);
#endif
    read();
    solve();
    print();
    return 0;
}
