using namespace std;

class bestValueMaintainer {
 public:
  int best = -1, cand = -1;
  int bestIdx, candIdx;
  void update(int idx, int val) {  
    if (val > best) {
      cand = best; candIdx = bestIdx;
      best = val; bestIdx = idx;
    }
    else if (val > cand) {
      cand = val; candIdx = idx;
    }
  }
};

int sol(const vector<int>& v) {
  vector<int> stat[2];
  stat[0].resize(111111);
  stat[1].resize(111111);
  for (int i = 0 ; i != v.size() ; i++) {
    stat[i%2][v[i]]++;
  }
  bestValueMaintainer bvm[2];
  for (int k = 0 ; k < 2 ; k++) {
    for (int i = 0 ; i != stat[k].size() ; i++)
      bvm[k].update(i, stat[k][i]);
  }
  if (bvm[0].bestIdx != bvm[1].bestIdx) {
    return v.size() - bvm[0].best - bvm[1].best;
  }
  else if (bvm[0].best + bvm[1].cand > bvm[0].cand + bvm[1].best) {
    assert(bvm[1].cand >= 0);
    return v.size() - bvm[0].best - bvm[1].cand;
  }
  else {
    assert(bvm[0].cand >= 0);
    return v.size() - bvm[0].cand - bvm[1].best;
  }
}

int main()
{
  int n;
  cin >> n;
  vector<int> v;
  for (int i = 0 ; i != n ; i++) {
    int a;
    cin >> a;
    v.push_back(a);
  }
  cout << sol(v) << endl;
  return 0;
}

