int main()
{
    cin >> n;
    kazu.resize(n);
    REP(i, n / 2)
    {
        int j, k;
        cin >> j >> k;
        kazu[2 * i] = j;
        kazu[2 * i + 1] = k;
        gu[j]++;
        ki[k]++;
    }
    if (gu.size() == 1 && ki.size() == 1 && kazu[0] != kazu[1]) disp(0);
    if (gu.size() == 1 && ki.size() == 1) disp(n / 2);

    priority_queue<pint, vector<pint>> gus, kis;
    for (auto pa : gu) gus.push(pint(pa.second, pa.first));
    for (auto pa : ki) kis.push(pint(pa.second, pa.first));



    if (gus.top().second != kis.top().second) disp(n - gus.top().first - kis.top().first);
    if (gu.size() == 1)
    {
        while (gus.top().second == kis.top().second) kis.pop();
        disp(n - gus.top().first - kis.top().first);
    }
    if (ki.size() == 1)
    {
        while (gus.top().second == kis.top().second) gus.pop();
        disp(n - gus.top().first - kis.top().first);
    }

    int u = gus.top().first;
    int v = kis.top().first;
    gus.pop();
    kis.pop();
    int ans = max(u + kis.top().first, v + gus.top().first);
    disp(n - ans);
}

