int main () {
	long n;
	cin >> n;
	vector<long> array(n);
	for (int i{0}; i < n; ++i)
		cin >> array[i];

	sort(array.begin(), array.end());

	vector<long> element_array;
	auto array_iter = array.begin();
	auto old_array_iter = array_iter;
	n /= 2;

	while(array_iter++ != array.end()){
		if (*array_iter != *old_array_iter){
			element_array.push_back(n - distance(old_array_iter, array_iter));
			old_array_iter = array_iter;
		}
	}

	sort(element_array.begin(), element_array.end(), [](int i, int j){return abs(i) < abs(j);});

	if (element_array.size() != 1){
		if (element_array[0] * element_array[1] >= 0)
			cout << element_array[0] + element_array[1];
		else
			cout << (element_array[0] > element_array[1]) ? element_array[0] : element_array[1];
	} else
		cout << -element_array[0];

	return 0;
}

