map<int,int> s1,s2;
vector<int> num1,num2;
int main()
{
	int n;
	cin>>n;
	for(int i=1;i<=n;i++)
	{
		int a;
		cin>>a;
		if(i%2)
		{
			s1[a]++;
			num1.pb(a);
		}
		else
		{
			s2[a]++;
			num2.pb(a);
		}
	}
	sort(num1.begin(),num1.end());
	for(int i=0;i<(int)num1.size();i++)
	{
		while(i<(int)num1.size()-1&&num1[i]==num1[i+1])num1.erase(num1.begin()+i);
	}
	for(int i=0;i<(int)num1.size();i++)
	{
		for(int j=i+1;j<(int)num1.size();j++)
		{
			if(s1[num1[i]]<s1[num1[j]])
			{
				swap(num1[i],num1[j]);
				i--;
				break;
			}
		}
	}
	sort(num2.begin(),num2.end());
	for(int i=0;i<(int)num2.size();i++)
	{
		while(i<(int)num2.size()-1&&num2[i]==num2[i+1])num2.erase(num2.begin()+i);
	}
	for(int i=0;i<(int)num2.size();i++)
	{
		for(int j=i+1;j<(int)num2.size();j++)
		{
			if(s2[num2[i]]<s2[num2[j]])
			{
				swap(num2[i],num2[j]);
				i--;
				break;
			}
		}
	}
	int ans1=num1[0],ans2=num2[0];
	if(ans1==ans2)
	{
		if(num1.size()==1)
		{
			if(num2.size()==1)
			{
				cout<<n/2<<endl;
				return 0;
			}
			ans2=num2[1];
		}
		else if(num2.size()==1)ans1=num1[1];
		else
		{
			if(ans1+num2[1]<ans2+num1[1])ans1=num1[1];
			else ans2=num2[1];
		}
	}
	cout<<n-s1[ans1]-s2[ans2]<<endl;
	return 0;
}

