typedef pair<int, int> pii;
const int maxn = 1e5 + 7;
int a[maxn], cnt[maxn];
priority_queue<pii> q1, q2;
int main(){
    #ifdef LOCAL
    freopen("a", "r", stdin);
    #endif // LOCAL
    int n;
    scanf("%d", &n);
    for(int i = 0; i < n; ++i){
        scanf("%d", &a[i]);
    }
    for(int i = 0; i < n; i += 2){
        cnt[a[i]]++;
    }
    for(int i = 0; i < maxn; ++i){
        if(cnt[i]){
            q1.push((pii){cnt[i], i});
        }
    }
    q1.push((pii){0, 0});
    memset(cnt, 0, sizeof(cnt));
    for(int i = 1; i < n; i += 2){
        cnt[a[i]]++;
    }
    for(int i = 0; i < maxn; ++i){
        if(cnt[i]){
            q2.push((pii){cnt[i], i});
        }
    }
    q2.push((pii){0, 0});
    pii top1 = q1.top();q1.pop();
    pii top2 = q2.top();q2.pop();
    if(top1.second != top2.second){
        printf("%d\n", n-top1.first-top2.first);
    }
    else if(top1.first + q2.top().first <= top2.first + q1.top().first){
        printf("%d\n", n-q1.top().first-top2.first);
    }
    else{
        printf("%d\n", n-top1.first-q2.top().first);
    }
}

