    vector<int> v(n);
    for (int i = 0; i < n; ++i) {
        cin>>v[i];
    }
    map<int,int> a;
    map<int,int> b;
    for (int i = 0; i < n-1; i+=2) {
        a[v[i]]+=1;
    }
    for (int i = 1; i < n; i+=2) {
        b[v[i]]+=1;
    }
    priority_queue<pair<int,int>> aq,bq;
    for(auto i:a){
        aq.push(i);
    }
    for(auto i:b){
        bq.push(i);
    }
    int ans=0;
    if(aq.top().first!=bq.top().first){
        ans+=n/2-aq.top().second;
        ans+=n/2-bq.top().second;
        cout<<ans<<endl;
        return 0;
    }
    else {
        if(aq.top().second>bq.top().second){
            bq.pop();
            ans+=n/2-aq.top().second;
            if(bq.empty())ans+=n/2;
            else ans+=n/2-bq.top().second;
            cout<<ans<<endl;
            return 0;
        }
        else {
            aq.pop();
            if(aq.empty())ans+=n/2;
            else ans+=n/2-aq.top().second;
            ans+=n/2-bq.top().second;
            cout<<ans<<endl;
            return 0;
        }
    }
    return 0;
}

