using namespace std;

struct Option
{
    int value;
    int changes;

    bool operator<(const Option &other) const
    {
        return changes < other.changes;
    }
};

pair<Option, Option> FindBest(const vector<int> &count, int total)
{
    Option first = {.value = -1, .changes = total};
    Option second = {.value = -1, .changes = total};

    for (size_t i = 1; i < count.size(); i += 1) {
        Option curr_option = {.value = (int)i, .changes = total - count[i]};
        if (curr_option < first) {
            second = first;
            first = curr_option;
        } else if (curr_option < second) {
            second = curr_option;
        }
    }
    return {first, second};
}

int FindCost(const pair<Option, Option> &odd, const pair<Option, Option> &even)
{
    if (odd.first.value != even.first.value) {
        return odd.first.changes + even.first.changes;
    }
    return min(odd.first.changes + even.second.changes,
               odd.second.changes + even.first.changes);
}

int main()
{
    int n;
    cin >> n;

    constexpr int kMaxVal = 1e5;
    vector<int> count_odd(kMaxVal + 1, 0);
    vector<int> count_even(kMaxVal + 1, 0);

    for (int i = 0; i < n; i += 1) {
        int num;
        cin >> num;

        if (i % 2 == 0) {
            count_even[num] += 1;
        } else {
            count_odd[num] += 1;
        }
    }

    auto best_odd = FindBest(count_odd, n / 2);
    auto best_even = FindBest(count_even, (n + 1) / 2);

    auto res = FindCost(best_odd, best_even);
    cout << res << "\n";

    return 0;
}

