	vector <pii> MPO;
	for(auto it:mpo) {
		MPO.pb(it);
	}
	sort(all(MPO), [] (pii i, pii j) {
		return i.second > j.second;
	});
	int o1 = MPO[0].first;
	int o2 = MPO[1].first;
	cerr << o1 << ' ' << o2 << '\n';

	// find the number of changes required for first type
	int count = 0;
	for(auto it:e) {
		if (it != e1) ++count;
	}
	for(auto it:o) {
		if (it != o2) ++count;
	}
	// second type
	int sum = 0;
	for(auto it:e) {
		if (it != e2) ++sum;
	}
	for(auto it:o) {
		if (it != o1) ++sum;
	}
	cout << min(count, sum);
}

