int main() {
    //  freopen("in.txt", "rt", stdin);
    int n;
    scanf("%d", &n);
    for (int i = 0; i < n; ++i) {
        scanf("%d", arr + i);
        mp[i % 2][arr[i]]++;
    }
    vector<pair<int, int>> v0, v1;
    for (auto x:mp[0]) {
        v0.push_back(x);
        swap(v0.back().first, v0.back().second);
    }
    for (auto x:mp[1]) {
        v1.push_back(x);
        swap(v1.back().first, v1.back().second);
    }
    sort(v1.rbegin(), v1.rend());
    sort(v0.rbegin(), v0.rend());
    int ans = n;
    for (int i = 0; i < n; i += 2) {
        int v = (n / 2) - mp[0][arr[i]];
        for (auto P:v1) {
            if (P.second != arr[i]) {
                ans = min(v + (n / 2 - P.first), ans);
                break;
            }
        }
        ans = min(ans, v + n / 2);
    }
    for (int i = 1; i < n; i += 2) {
        int v = (n / 2) - mp[1][arr[i]];
        for (auto P:v0) {
            if (P.second != arr[i]) {
                ans = min(v + (n / 2 - P.first), ans);
                break;
            }
        }
        ans = min(ans, v + n / 2);
    }
    printf("%d", ans);
}

