#define NMAX 100001
#define INF (1 << 30)

int v[NMAX], a[NMAX], b[NMAX];
vector <int> aux[NMAX];
vector <pair <int, int> > s;

int solve_single(int x[]) {
    int non_zero = 0;
    int m = 0;
    for (int i = 1; i < NMAX; i++) {
        if (x[i] == 0)
            continue;
        non_zero += x[i];
        m = max(m, x[i]);
    }
    return non_zero - m;
}

void build_second_best(int x[]) {
    int non_zero = 0;
    for (int i = 1; i < NMAX; i++) {
        non_zero += x[i];
    }
    for (int i = 1; i < NMAX; i++) {
        if (x[i]) {
            aux[non_zero - x[i]].push_back(i);
        }
    }
    for (int i = 0; i < NMAX; i++) {
        for (const int z : aux[i]) {
            s.emplace_back(i, z);
        }
    }
}

bool get_second_best(int nr, int& cnt) {
    if (s.size() == 1u) {
        if (s[0].second == nr)
            return false;
        cnt += s[0].first;
    } else {
        if (s[0].second == nr) {
            cnt += s[1].first;
        } else {
            cnt += s[0].first;
        }
    }
    return true;
}

int main()
{
    ios::sync_with_stdio(false);

    int n;
    // ifstream cin("code.in");
    cin >> n;
    for (int i = 1; i <= n; i++) {
        cin >> v[i];
    }
    for (int i = 1; i < n; i += 2) {
        a[v[i]]++;
        b[v[i + 1]]++;
    }
    int sol = (n >> 1) + solve_single(b);
    build_second_best(b);
    for (int i = 1; i < NMAX; i++) {
        if (a[i] == 0)
            continue;
        int cnt = (n >> 1) - a[i];

        if (!get_second_best(i, cnt)) {
            cnt += (n >> 1);
        }

        sol = min(sol, cnt);

    }
    cout << sol << '\n';
    return 0;
}

