const int INF = 1e6;

int32_t main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    int n;
    cin >> n;
    vector<int> a(n), b(INF), c(INF);
    vector<pair<int, int>> bs, cs;
    vector<bool> fl(INF);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        if (i % 2 == 0) {
            b[a[i]]++;
        } else c[a[i]]++;
    }
    for (int i = 0; i < INF; i++) {
        if (b[i] == 0 || c[i] == 0) continue;
        fl[i] = true;
        bs.pb({b[i], i});
        cs.pb({c[i], i});
    }
    sort(bs.begin(), bs.end());
    sort(cs.begin(), cs.end());
    reverse(bs.begin(), bs.end());
    reverse(cs.begin(), cs.end());
    int mx1 = 0, mx2 = 0;
    if (bs.size() == 0 && cs.size() != 0) {
        mx2 = cs[0].ff;
    }
    if (bs.size() > 0 && cs.size() == 0) {
        mx1 = bs[0].ff;
    }
    if (cs.size() > 0 && bs.size() > 0 && bs[0].ss != cs[0].ss) {
        mx1 = bs[0].ff;
        mx2 = cs[0].ff;
    }
    for (int i = 0; i < INF; i++) {
        if (fl[i]) continue;
        mx1 = max(mx1, b[i]);
        mx2 = max(mx2, c[i]);
    }
    int ans = n - mx1 - mx2;
    if (cs.size() > 0 && bs.size() > 0 && cs[0].ss == bs[0].ss) {
        ans = min(ans, min(n - max(mx1, bs[0].ff) - max(mx2, (cs.size() == 1 ? mx2 : cs[1].ff)),
            n - max(mx1, (bs.size() == 1 ? mx1 : bs[1].ff) - max(mx2, cs[0].ff))));
    }
    cout << ans;
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
