typedef pair <int, int> ii;

const int Maxm = 100005;

int n;
int a[Maxm];
int freq[Maxm];
ii best[2][2];

void Get(int from)
{
    fill(freq, freq + Maxm, 0);
    for (int i = from; i < n; i += 2)
        freq[a[i]]++;
    for (int i = 1; i < Maxm; i++)
        if (ii(freq[i], i) > best[from][0])
            best[from][1] = best[from][0], best[from][0] = ii(freq[i], i);
        else if (ii(freq[i], i) > best[from][1])
            best[from][1] = ii(freq[i], i);
}

int main()
{
    scanf("%d", &n);
    for (int i = 0; i < n; i++)
        scanf("%d", &a[i]);
    Get(0); Get(1);
    int res = 0;
    if (best[0][0].second == best[1][0].second)
        res = max(best[0][0].first + best[1][1].first,
                  best[0][1].first + best[1][0].first);
    else res = best[0][0].first + best[1][0].first;
    printf("%d\n", n - res);
    return 0;
}

