bool cmp(const std::pair<int,int> &a,const std::pair<int,int> &b)
{
    return a.second>b.second;
}
int main()
{
    scanf("%d",&n);
    for(int i=1;i<=n;i++)
    {
        scanf("%d",&v[i]);
        if(i%2==1) a[v[i]]++;
        if(i%2==0) b[v[i]]++;
    }
    std::vector<std::pair<int,int> > A(a.begin(),a.end());
    std::vector<std::pair<int,int> > B(b.begin(),b.end());
    std::sort(A.begin(),A.end(),cmp);
    std::sort(B.begin(),B.end(),cmp);
    int min=0x7fffffff;
    if(A[0].first!=B[0].first)
    {
        min=std::min(min,n-A[0].second-B[0].second);
    } else
    {
        if(A.size()>1)
        {
            min=std::min(min,n-A[1].second-B[0].second);
        }
        if(B.size()>1)
        {
            min=std::min(min,n-A[0].second-B[1].second);
        }
    }
    if(min==0x7fffffff) min=n/2;
    printf("%d\n",min);
