      REP0(i,A_size){
        if (A_mode_cnt < A_hist[*(A_itr)]) {
          A_mode_cnt = A_hist[*(A_itr)];
          A_mode = *(A_itr);
        }
        A_itr = ++A_itr;
      }
      REP0(i,B_size){
        if (B_mode_cnt < B_hist[*(B_itr)] && A_mode != *(B_itr)) {
          B_mode_cnt = B_hist[*(B_itr)];
          B_mode = *(B_itr);
        }
        B_itr = ++B_itr;
      }
  } else {
