int maxn = -1;

int max(int a,int b){ return a>b?a:b; }

int getCnt(int n,int d[]){
    int res = 0, counter = 0;
    int p = 1;
    while(p<=n){
        int np = p;
        while(np+1<=n && d[np+1]==d[p]) np++;
        int cnt = np-p+1;
        if(cnt>res){
            counter = 1;
            res = cnt;
            maxn = d[p];
        }
        else if(cnt==res) counter++;
        p = np+1;
    }
    if(counter==1) return -res;
    else return res;
}

int getSecond(int n,int d[],int maxn){
    int res = 0;
    int p = 1;
    while(p<=n){
        int np = p;
        while(np+1<=n && d[np+1]==d[p]) np++;
        if(np-p+1!=maxn) res = max(res,np-p+1);
        p = np+1;
    }
    return res;
}

