int count(int n, int *v){
  int cnt[10];
  for(int k=0; k<10; k++){
    cnt[k] = 0;
  }
  for(int i=0; i<n; i++){
    cnt[v[i*2]]++;
  }
  int max = cnt[0];

  for(int k=1; k<10; k++){
    if(cnt[k] > max){
      max = cnt[k];
    }
  }

  return n - max;
}

