			swap(c, dc[1][0]);
			swap(k, dp[1][0]);
		}
		if(dc[1][1] < c) {
			swap(c, dc[1][1]);
			swap(k, dp[1][1]);
		}
	}

	for(int i = 0; i < 2; i++) for(int j = 0; j < 2; j++) {
		if(dp[0][i] == dp[1][j]) continue;
		int c = N - dc[0][i] - dc[1][j];
		if(c < Ans) Ans = c;
	}

	cout << Ans << endl;
	return 0;
}

