int main(){
	int n, ans = 0;
	cin >> n;
	map<int, int> a, b;
	for(int i = 0; i < n; i++){
		int in;
		cin >> in;
		if(i % 2 == 0) a[in]++;
		else b[in]++;
	}
	vector<pair<int, int>> c, d;
	for(auto i : a){
		c.push_back(make_pair(i.first, i.second));
	}
	for(auto i : b){
		d.push_back(make_pair(i.first, i.second));
	}
	sort(c.begin(), c.end(), [](pair<int, int> x, pair<int, int> y) -> int{return (x.second > y.second); });
	sort(d.begin(), d.end(), [](pair<int, int> x, pair<int, int> y) -> int{return (x.second > y.second); });
	int s = 0, t = 0;
	while(1){
		if(c[s].first == d[t].first){
			if(s + 1 == c.size()){
				if(t + 1 == d.size()){
					ans += d[t].second;
					break;
				}else{
					t++;
					continue;
				}
			}else if(t + 1 == d.size()){
				s++;
				continue;
			}else{
				if(c[s + 1].second <= d[t + 1].second) t++;
				else s++;
			}
		}else{
			ans = ((n + 1) / 2 - c[s].second) + (n / 2 - d[t].second);
			break;
		}
	}
	cout << ans << endl;
	return 0;
}

