int get_maxkey(map<int, int> m, bool check = false, int v = 0) {
  int max_val = 0, res = 0;
  for (auto o : m) {
    if (max_val < o.second) {
      if (check && v == o.first)
        continue;
      max_val = o.second;
      res = o.first;
    }
  }
  return res;
}

