void solve() {
  int n; cin >> n;
  vi a(n);
  for (int i = 0; i < n; ++i) {
    cin >> a[i];
  }
  vpii b, c;
  for (auto s : {0, 1}) {
    for (int i = s; i < n; i += 2) {
      int w = 1;
      while (i + 2 < n && a[i] == a[i + 2]) {
        ++w;
        i += 2;
      }
      if (s == 0) {
        b.pb({w, a[i]});
      } else {
        c.pb({w, a[i]});
      }
    }
  }
  trace(a, b, c);
  int sb = 0, sc = 0;
  for (auto x : b) {
    sb += x.x;
  }
  for (auto y : c) {
    sb += y.x;
  }
  int ret = (int)1e9 + 7;
  for (auto x : b) {
    for (auto y : c) {
      if (x.y != y.y) {
        amin(ret, sb - x.x + sc - y.x);
      } else {
        auto e = x, f = y;
        auto eb = sb, ec = sc;
        if (e.x > f.x) {
          swap(e, f);
          swap(eb, ec);
        }
        amin(ret, eb - e.x + ec);
      }
    }
  }
  output(ret);
}

