#include <iostream>

#define SIZE 100001

struct HASH{
		int value[SIZE] = {0};
  	int MAX;
  	int nextMAX;
  	HASH(){
      	this->MAX = 0;
      	this->nextMAX = 0;
    }
  	void CountingValue(int x){
      	++this->value[x];
    }
  	void CountingHindou(){
    	int max_count = 0;
      	for(int i = 1; i < SIZE; i++){
        	int tmp = this->value[i];
          	if(tmp > max_count){
            		max_count = tmp;
              	this->MAX = i;
            }
        }

      	max_count = 0;
      	for(int i = 1; i < SIZE; i++){
          	if(i == this->MAX){
            	continue;
            }

        		int tmp = value[i];
          	if(tmp > max_count){
            		max_count = tmp;
              	this->nextMAX = i;
            }          	
        }
    }
};

int main(void){
		int n;
  	std::cin >> n;
  	HASH odd;
		HASH even;
  	for(int i = 0; i < n; i++){
      	int tmp;
      	std::cin >> tmp;
    		i%2 == 0 ? even.CountingValue(tmp) : odd.CountingValue(tmp);
    }
  	odd.CountingHindou();
  	even.CountingHindou();
  	if(odd.MAX != even.MAX) std::cout << n - odd.value[odd.MAX] - even.value[even.MAX];
  	else{
    	int diff_1 = odd.value[odd.MAX] + even.value[even.nextMAX];
      	int	diff_2 = even.value[even.MAX] + odd.value[odd.nextMAX];
      	diff_1 > diff_2 ? std::cout << n - diff_1 : std::cout << n - diff_2;
    }
  	return 0;
}

