	cin >> a;

	map<int, int> f1, f2;
	for (int i = 0; i < n; i++)
	{
		if (i & 1)
			f2[a[i]]++;
		else
			f1[a[i]]++;
	}

	int ans = 0;
	int x = 0, y = 0;
	int p = INF, q = INF;
	for (auto &it : f1)
	{
		ans += it.S;
		if (it.S > x)
		{
			x = it.S;
			p = it.F;			
		}
	}
	for (auto &it : f2)
	{
		ans += it.S;
		if (it.S > y && it.F != p)
		{
			y = it.S;
			q = it.F;
		}
	}	
	ans -= (x + y);


	int ans1 = 0;
	x = 0, y = 0;
	p = INF, q = INF;

	for (auto &it : f2)
	{
		ans1 += it.S;
		if (it.S > y)
		{
			y = it.S;
			q = it.F;
		}
	}
	for (auto &it : f1)
	{
		ans1 += it.S;
		if (it.S > x && it.F != q)
		{
			x = it.S;
			p = it.F;			
		}
	}
	ans1 -= (x + y);

	ans = min(ans, ans1);
	cout << ans;
}	

