const int N = 100000 + 5;

int n, v;
int cnt[2][N];

void update(pair<int, int> &mx1, pair<int, int> &mx2, pair<int, int> c) {
  if (c.first > mx2.first) {
    swap(c, mx2);
  }
  if (mx2.first > mx1.first) {
    swap(mx1, mx2);
  }
}

int calc(pair<int, int> &mx1, pair<int, int> &mx2) {
  if (mx1.second != mx2.second) {
    return mx1.first + mx2.first;
  }
  return max(mx1.first, mx2.first);
}

