  for (int i = 1; i <= n; i++) {
    scanf("%d", &v);
    cnt[i&1][v]++;
  }
  pair<int, int> mx[2][2];
  for (int i = 1; i < N; i++) {
    for (int p = 0; p < 2; p++) {
      if (cnt[p][i] != 0) {
        update(mx[0][p], mx[1][p], make_pair(cnt[p][i], i));
      }
    }
  }
  int ans = n;
  for (int i = 0; i < 2; i++) {
    for (int j = 0; j < 2; j++) {
      ans = min(ans, n - calc(mx[0][i], mx[1][j]));
    }
  }
  printf("%d\n", ans);
  return 0;
}

