using namespace std;


ll maxK(set<ll>& st, map<ll, ll>& m){
    ll maxx = 0;
    ll k = -1;
    for(auto x : st){
        if(maxx < m[x]){
            maxx = m[x];
            k = x;
        }
    }
    return k;
}

int main(){
    ios::sync_with_stdio(0);
    cin.tie(0);

    ll n;
    cin >> n;
    vector<ll> v(n);
    rep(i, n) cin >> v[i];

    vector<ll> l;
    vector<ll> r;
    rep(i, n){
        if(i%2 == 0) l.push_back(v[i]);
        else         r.push_back(v[i]);
    }

    set<ll> lst;
    set<ll> rst;
    for(auto x : l) lst.insert(x);
    for(auto x : r) rst.insert(x);

    map<ll, ll> lm;
    map<ll, ll> rm;
    for(auto x : l) lm[x]++;
    for(auto x : r) rm[x]++;

    ll lk = maxK(lst, lm);
    ll rk = maxK(rst, rm);

    if(lk == rk){
        lst.erase(lk);
        rst.erase(rk);
        ll llk = maxK(lst, lm);
        ll rrk = maxK(rst, rm);
        if(lm[lk] + rm[rrk] < lm[llk] + rm[rk]) lk = llk;
        else                                    rk = rrk;
        lst.insert(lk);
        rst.insert(rk);
    }

    cout << l.size()-lm[lk] + r.size()-rm[rk] << endl;




    return 0;
}

