const int MAXN = 100005;
const int MAXV = 100005;

pair<int, int> two_maxes(const vector<int> & arr) {
    int m1 = -1, m2 = -1;
    int m1_val = 0, m2_val = 0;
    for (int i = 0; i < MAXV; ++i) {
        if (m1_val < arr[i]) {
            m2_val = m1_val;
            m2 = m1;
            m1_val = arr[i];
            m1 = i;
        } else {
            if (m2_val < arr[i]) {
                m2_val = arr[i];
                m2 = i;
            }
        }
    }
    return {m1, m2};
}

int main() {
    // freopen("input.txt", "r", stdin);

    int n;
    cin >> n;
    int a[MAXN];
