    vector<int> odd(MAXV);

    for (int i = 0; i < n; i += 2) {
        ++even[a[i]];
    }

    for (int i = 1; i < n; i += 2) {
        ++odd[a[i]];
    }

    auto m_even = two_maxes(even);
    auto m_odd = two_maxes(odd);

    if (m_even.first == m_odd.first && m_even.second == -1 && m_odd.second == -1) {
