				er3 = er1;
			}
			er1 = a[i];
		}
	}
	cnt = 0;
	int Min2 = 1e9 + 7;
	int Min4 = 1e9 + 7;
	for(int i = 2; i <= n; i += 2){
		if((n - pos) - vis[a[i]] < Min2){
			Min2 = (n - pos) - vis[a[i]];
