			if(vis2[mp[A[i]]].v>maxn2){
				max2=mp[A[i]],maxn2=vis2[mp[A[i]]].v;
			}
		}
	}
	sort(vis1+1,vis1+1+cnt);
	sort(vis2+1,vis2+1+cnt);
	int l1=1,l2=1;
