void calc_same(vector<int> v,vector<pair<int,int>>& p){
  int val,cnt;
  val=v[0];
  cnt=0;
  for(int i=0;i<v.size();i++){
    if(val!=v[i]){
      p.push_back(make_pair(cnt,val));
      cnt=1;
      val=v[i];
    }else{
      cnt++;
    }
  }
  p.push_back(make_pair(cnt,val));
  sort(p.begin(),p.end(),greater<pair<int,int>>());
}
