vii getCnt(vi &v) {
	vii ans;
	int cnt = 1;
	rep(i, 1, v.size()) {
		if(v[i] == v[i - 1]) {
			cnt++;
		}
		else {
			ans.pb(mp(cnt, v[i - 1]));
			cnt = 1;
		}
	}
