using namespace std;

class Solution {
public:
    int solve(vector<int>&A ) {
        int n = A.size();
        int res = 0;
        vector<vector<pair<int,int>>> C(2);
        for (int beg = 0; beg < 2; ++beg) {
            vector<int> B;
            for (int i = beg; i < n; i += 2) {
                B.push_back(A[i]);
            }
            sort(B.begin(), B.end());
            int mx = 0;
            int m = B.size();
            for (int i = 0; i < m; ++i) {
                int cnt = 1;
                while (i + 1 < m && B[i + 1] == B[i]) {
                    ++i;
                    ++cnt;
                }
                mx = max(mx, cnt);
                C[beg].emplace_back(cnt, B[i]);
            }
            sort(C[beg].begin(), C[beg].end());
            reverse(C[beg].begin(), C[beg].end());
        }

        for (int i = 0; i < C[0].size() && i < 3; ++i) {
            for (int j = 0; j < C[1].size() && j < 3; ++j) {
                // cout << C[0][i].first << " " << C[1][i].second << endl;
                if (C[0][i].second == C[1][j].second) {
                    res = max(res, C[0][i].first);
                    res = max(res, C[1][j].first);
                    continue;
                }
                res = max(res, C[0][i].first + C[1][j].first);
            }
        }
        res = n - res;

        return res;
    }
};

int main(int argc, char** argv) {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n;
    vector<int> A(n);
    for (int i = 0; i < n; ++i) {
        cin >> A[i];
    }

    Solution sol;
    cout << sol.solve(A) << "\n";

    return 0;
}

