const int N=1e5;


void run(){

	int n; cin>>n;

	vi v(n);
	FOR(i,0,n) cin>>v[i];

	map<int, int> m, p;
	int x=0, ans=0, b;

	for(int i=0; i<n; i=i+2){
		if(!m.count(v[i])){
			m[v[i]]=1;
		}
		else m[v[i]]=m[v[i]]+1;

		if(m[v[i]]>x){
			x=m[v[i]]; b=v[i];
		}
	}


	int y=0, c;

	for(int i=1; i<n; i=i+2){
		if(!p.count(v[i])){
			p[v[i]]=1;
		}
		else p[v[i]]=p[v[i]]+1;

		if(p[v[i]]>y){
			y=p[v[i]]; c=v[i];
		}
