using namespace std;
using ll = long long;

ll N;
vector<ll> V;

void input() {
    cin >> N;
    V.resize(N);
    for (auto& v : V)
        cin >> v;
}

ll solve() {
    vector<ll> counts[2] = {vector<ll>(100001), vector<ll>(100001)};
    for (ll i = 0; i < N; i++) {
        counts[i % 2][V[i]]++;
    }
    ll maxif = max_element(counts[0].begin(), counts[0].end()) - counts[0].begin();
    ll maxis = max_element(counts[1].begin(), counts[1].end()) - counts[1].begin();
    if (maxif == maxis) {
        if (counts[0][maxif] > counts[1][maxis]) {
            counts[1][maxis] = 0;
            maxis = max_element(counts[1].begin(), counts[1].end()) - counts[1].begin();
        } else if (counts[0][maxif] < counts[1][maxis]) {
            counts[0][maxif] = 0;
            maxif = max_element(counts[0].begin(), counts[0].end()) - counts[0].begin();
        } else {
            ll pmaxif = maxif, pmaxis = maxis, pmaxcf = counts[0][maxif], pmaxcs = counts[1][maxis];
            counts[0][maxif] = 0;
            maxif = max_element(counts[0].begin(), counts[0].end()) - counts[0].begin();
            counts[1][maxis] = 0;
            maxis = max_element(counts[1].begin(), counts[1].end()) - counts[1].begin();
            if (counts[0][maxif] > counts[1][maxis]) {
                maxis = pmaxis;
                counts[1][pmaxis] = pmaxcs;
            } else {
                maxif = pmaxif;
                counts[0][pmaxif] = pmaxcf;
            }
        }
    }

    return N - counts[0][maxif] - counts[1][maxis];
}


int main() {
    input();
    cout << solve() << endl;
//    solve();

    return 0;
}

