map<int, int> O, E;

int main() {

	boost;
	int n; cin>>n;
	O[-1] = 0, E[-1] = 0;

	for(int i=1; i<=n; i++) {
		int v; cin>>v;
		if(i & 1) O[v]++;
		else E[v]++;
	}

	pii o1 = pii(-1, -1), o2 = pii(-1, -1);
	for(auto it : O) {
		pii pp = pii(it.se, it.fi);
