			e2 = e1;
			e1 = pp;
		}
		else if(pp > e2) {
			e2 = pp;
		}
	}

	int ans = 0;

	if(o1.se != e1.se) {
		ans = n - o1.fi - e1.fi;
	}
	else {
		ans = min(n - o1.fi - e2.fi, n - o2.fi - e1.fi);
	}

	cout<<ans<<"\n";
	return 0;
}

