    int atcode103c(vector<int> v,int n){
        vector<int> vc=v;
        auto it=unique(vc.begin(),vc.end());
        vc.resize( std::distance(vc.begin(),it) );
        if(vc.size()==1) return floor(n/2);
        else{
            vector<int> odd,even;
        for(int i=0;i<n;++i){
            if(i%2==0) even.push_back(v[i]);
            else odd.push_back(v[i]);
        }//divide into two parts.
        vector<int> oc,ec;//receive two parts count.
        for(int j:odd) oc.push_back(count(odd.begin(),odd.end(),j));
        //for(auto l:oc) cout<<l<<" ";
        for(int k:even) ec.push_back(count(even.begin(),even.end(),k));
        //for(auto l:ec) cout<<l<<" ";
        auto it1=find(ec.begin(),ec.end(),*max_element(ec.begin(),ec.end()));
        auto it2=find(oc.begin(),oc.end(),*max_element(oc.begin(),oc.end()));
        int p1=it1-ec.begin();
        int p2=it2-oc.begin();
        //cout<<p1<<" "<<p2<<endl;
        list<int> e1 (even.begin(),even.end());
        list<int> o1 (odd.begin(),odd.end());
        auto evenmaxrepeat=even[p1];
        auto oddmaxrepeat=odd[p2];
        e1.remove(evenmaxrepeat);
        o1.remove(oddmaxrepeat);
        //return e1.size()+o1.size();
        return e1.size()+o1.size();
        }
    }
};
