    unordered_map <int, int> even;
    int max_odd = 1, max_even = 1;
    int odd_num = v[0], even_num = v[n-1];    
    for (int i;i<n;i++){
        cin >> v[i];
        if (i % 2){
            if (odd.find(v[i]) == odd.end())
                odd.insert(make_pair(v[i], 1));
            else{
                odd[v[i]]++;
                if (odd[v[i]] > max_odd){
                    max_odd = odd[v[i]];
                    odd_num = v[i];
                }

            }

        }
        else{

            if (even.find(v[i]) == even.end())
                even.insert(make_pair(v[i], 1));
            else{
                even[v[i]]++;
                if (even[v[i]] > max_even){
                    max_even = even[v[i]];
                    even_num = v[i];
                }
            }
        }
    }
    if (odd_num == even_num){
        if (max_odd > max_even){
            max_even = 0;
            for (int i=0;i<n;i++){
                if (!(i % 2) && v[i] != odd_num && even[v[i]] > max_even)
                    max_even = even[v[i]];
            }
        }
        else{
            max_odd = 0;
            for (int i=0;i<n;i++){
                if (i % 2 && v[i] != even_num && odd[v[i]] > max_odd)
                    max_odd = odd[v[i]];
            }

        }
    }

    cout << (n - max_odd - max_even);
    return 0;

}

