int main()
{
    int n; cin >> n;

    vector<int> A, B;
    int x;
    rep(i, n)
    {
        cin >> x;
        if (i % 2 == 0) A.push_back(x);
        else B.push_back(x);
    }

    map<int, int> a, b;

    rep(i, n/2)
    {
        a[A[i]]++;
        b[B[i]]++;
    }

    priority_queue<pair<int, int>> p, q;
    for (auto& c : a) p.push(make_pair(c.second, c.first));
    for (auto& c : b) q.push(make_pair(c.second, c.first));

    int a_1, a_2, b_1, b_2;
    a_1 = p.top().second;
    b_1 = q.top().second;

    if (a_1 + b_1 == n && p.top() == q.top())
    {
        cout << n / 2 << endl;
        return 0;
    }

    if (!(p.top().first == q.top().first)) cout << n - a_1 - b_1 << endl;
    else
    {
        p.pop();
        q.pop();
        a_2 = p.top().second;
        b_2 = q.top().second;
        cout << n - max(a_1 + b_2, a_2 + b_1) << endl;
    }
    return 0;
}

