  vector<pii> v1, v2;
  for (auto p: cnt1) v1.push_back(p);
  for (auto p: cnt2) v2.push_back(p);
  sort(v1.begin(), v1.end(), [](pii a, pii b) { return a.second > b.second; });
  sort(v2.begin(), v2.end(), [](pii a, pii b) { return a.second > b.second; });

  if (v1.size() == 1 && v2.size() == 1) {
