      cout << n / 2 << endl;
      return 0;
    } else {
      cout << 0 << endl;
      return 0;
    }
  }

  if (v1.size() == 1) {
    if (v1[0].first == v2[0].first) {
      cout << n / 2 - v2[1].second << endl;
      return 0;
    } else {
      cout << n / 2 - v2[0].second << endl;
      return 0;
    }
  }

  if (v2.size() == 1) {
    if (v1[0].first == v2[0].first) {
      cout << n / 2 - v1[1].second << endl;
      return 0;
    } else {
      cout << n / 2 - v1[0].second << endl;
      return 0;
    }
  }

  int ans = n;

  for (auto p1: v1) {
