            for (int x : d[i]) {
                mp[x] ++;
            }
            c[i].emplace_back(d[i].size(), -1);
            for (auto it : mp) {
                c[i].emplace_back(d[i].size() - it.second, it.first);
            }
            sort(ALL(c[i]));
        }
        int ans;
        if (c[0][0].second != c[1][0].second) {
            ans = c[0][0].first + c[1][0].first;
        } else {
            ans = min(c[0][0].first + c[1][1].first, c[0][1].first + c[1][0].first);
        }
        cout << ans << endl;
    }
    return 0;
}

