const ll INF = static_cast<ll>(1e9) + 7ll;
const ll LINF = INF * INF;
const int MAXN = static_cast<int>(1e6) + 17;

int n;
int a[MAXN];

bool read() {
    if (!(cin >> n))
        return false;

    forn (i, n) {
        cin >> a[i];
    }

    return true;
}

void solve() {
    map<int, int> A, B;
    A[0] = 0;
    B[0] = 0;

    forn (i, n) {
        if (i & 1)
            ++A[a[i]];
        else
            ++B[a[i]];
    }

    vector<pair<int, int> > va(A.begin(), A.end());
    vector<pair<int, int> > vb(B.begin(), B.end());

    sort(va.begin(), va.end(), [](pair<int, int> a, pair<int, int> b) {
        return a.second > b.second;
    });
    sort(vb.begin(), vb.end(), [](pair<int, int> a, pair<int, int> b) {
        return a.second > b.second;
    });

    int ans = n;

    for (int i = sz(va) - 1; i >= 0 && i >= sz(va) - 5; --i) {
        for (int j = sz(vb) - 1; j >= 0 && j >= sz(vb) - 5; --j)
            if (va[i].first != vb[j].first)
                ans = min(ans, n - (va[i].second + vb[j].second));
    }

    cout << ans << endl;
}

