	for(int i = 1; i <= 1e5; i++) {
		ans = min(ans, n - (odd[i] + max(pre2[i - 1], suf2[i + 1])));
		ans = min(ans, n - (even[i] + max(pre1[i - 1], suf1[i + 1])));
