    for (auto & bx:b) ++bf[bx];
    vector<int>::iterator ia = max_element(af.begin(), af.end());
    vector<int>::iterator ib = max_element(bf.begin(), bf.end());
    vector<int>::iterator ia2 = max(max_element(af.begin(), ia), max_element(ia+1, af.end()));
    vector<int>::iterator ib2 = max(max_element(bf.begin(), ib), max_element(ib+1, bf.end()));
    idxa1 = distance(af.begin(), ia);
    idxa2 = distance(af.begin(), ia2);
    idxb1 = distance(bf.begin(), ib);
