#define maxn 100005
using namespace std;

int T[maxn << 2][2];
int v[maxn][2];
int a[maxn];

void update(int rt, int l, int r, int pos, int f) {
	if (l == r) {
		T[rt][f] += 1;
		return;
	}
	int mid = (l + r) >> 1;
	if (mid >= pos) update(rt << 1, l, mid, pos, f);
	else	update(rt << 1 | 1, mid + 1, r, pos, f);
	T[rt][f] = max(T[rt << 1][f], T[rt << 1 | 1][f]);
}

int query(int rt, int l, int r, int L, int R, int f) {
	if (L <= l && R >= r) return T[rt][f];
	int mid = (l + r) >> 1, mx = 0;
	if (mid >= L)	mx = max(mx, query(rt << 1, l, mid, L, R, f));
	if (mid < R)	mx = max(mx, query(rt << 1 | 1, mid + 1, r, L, R, f));
	return mx;
}

int main() {
	int n;	scanf("%d", &n);
	for (int i = 1; i <= n; i++) scanf("%d", &a[i]);
	for (int i = 1; i <= n; i += 2) update(1, 1, maxn - 1, a[i], 1);
	for (int i = 1; i <= n; i += 2) v[a[i]][1]++;
	for (int i = 2; i <= n; i += 2) update(1, 1, maxn - 1, a[i], 0);
	for (int i = 2; i <= n; i += 2) v[a[i]][0]++;
	int mi = 0x3f3f3f3f;
	for (int i = 1; i <= n; i += 2) {
		int tmp_sum = v[a[i]][1] + query(1, 1, maxn - 1, a[i] + 1, maxn - 1, 0);
		mi = min(mi, n - tmp_sum);
	}
	for (int i = 2; i <= n; i += 2) {
		int tmp_sum = v[a[i]][0] + query(1, 1, maxn - 1, a[i] + 1, maxn - 1, 1);
		mi = min(mi, n - tmp_sum);
	}
	printf("%d\n", mi);
	return 0;
}

