using namespace std;

int n;
int v[100005];

void init() {
    cin >> n;
    for(int i = 0 ; i < n ; i++) cin >> v[i];
}

void solve() {
    map<int, int> m[2];
    for(int i = 0 ; i < n ; i++) m[i%2][v[i]]++;
    vector<pair<int, int> > v[2];
    for(int i = 0 ; i < 2 ; i++) {
        for(auto j : m[i]) v[i].push_back(make_pair(j.second, j.first));
        sort(v[i].begin(), v[i].end());
        reverse(v[i].begin(), v[i].end());
    }

    if(v[0][0].second == v[1][0].second) {
        if(v[0].size() == 1 && v[1].size() == 1) cout << min(v[0][0].first, v[1][0].first) << '\n';
        else if(v[0].size() == 1) {
            int ans = 0;
            for(int i = 0 ; i < v[1].size() ; i++) ans += v[1][i].first;
            ans -= v[1][1].first;
            cout << ans << '\n';
        }
        else if(v[1].size() == 1) {
            int ans = 0;
            for(int i = 0 ; i < v[0].size() ; i++) ans += v[0][i].first;
            ans -= v[0][1].first;
            cout << ans << '\n';
        }
        else {
            int ans[2]={0};
            for(int i = 0 ; i < 2 ; i++) {
                for(int j = 0 ; j < v[i].size() ; j++) ans[i] += v[i][j].first;
                ans[i] -= v[i][1].first;
            }
            cout << min(ans[0], ans[1]) << '\n';
        }
    }
    else {
        int ans = 0;
        for(int i = 0 ; i < 2 ; i++) for(int j = 1 ; j < v[i].size() ; j++) ans += v[i][j].first;
        cout << ans << '\n';
    }
}

int main() {
    init();
    solve();
}

