using namespace std;

typedef long long int lli;
typedef vector<lli> vi;
typedef pair<lli, lli> ii;

ii max(vi arr) {
  lli ret = 0;
  lli argmax = -1;
  for (lli i=0; i < arr.size(); i++) {
    if (ret < arr[i]) {
      ret = arr[i];
      argmax = i;
    }
  }
  return ii(ret, argmax);
}

ii max(vi arr, lli avoid) {
  lli ret = 0;
  lli argmax = -1;
  for (lli i=0; i < arr.size(); i++) {
    if (ret < arr[i] && i != avoid) {
      ret = arr[i];
      argmax = i;
    }
  }
  return ii(ret, argmax);
}

lli changes(vi a, bool even_first) {
  lli begin = even_first ? 0 : 1;
  lli num = 0;
  vi freq(100005, 0);
  for (lli i=begin; i<a.size(); i += 2) {
    num ++;
    freq[a[i]] ++;
  }
  lli x1 = num - max(freq).first;
  /* cout << "x1 = " << x1 << endl; */
  lli avoid = max(freq).second;
  /* cout << "avoid = " << avoid << endl; */

  begin = even_first ? 1 : 0;
  num = 0;
  freq.clear();
  freq.resize(100005, 0);
  for (lli i=begin; i<a.size(); i += 2) {
    num ++;
    freq[a[i]] ++;
  }
  lli x2;
  if (max(freq, avoid).second == -1) {
    x2 = num;
    /* cout << "x2 = " << x2 << endl; */
  } else {
    x2 = num - max(freq, avoid).first;
    /* cout << "x2 = " << x2 << endl; */
  }
  return x1 + x2;
}

