const int MAXN = 100005;
const int MAXV = 100005;

pair<int, int> two_maxes(const vector<int> & arr) {
    int m1 = -1, m2 = -1;
    int m1_val = 0, m2_val = 0;
    for (int i = 0; i < MAXV; ++i) {
        if (m1_val < arr[i]) {
            m2_val = m1_val;
            m2 = m1;
            m1_val = arr[i];
            m1 = i;
        } else {
            if (m2_val < arr[i]) {
                m2_val = arr[i];
                m2 = i;
            }
        }
    }
    return {m1, m2};
}

int main() {
    freopen("input.txt", "r", stdin);

    int n;
    cin >> n;
    int a[MAXN];
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    vector<int> even(MAXV);
    vector<int> odd(MAXV);

    for (int i = 0; i < n; i += 2) {
        ++even[a[i]];
    }

    for (int i = 1; i < n; i += 2) {
        ++odd[a[i]];
    }

    auto m_even = two_maxes(even);
    auto m_odd = two_maxes(odd);

    if (m_even.first == m_odd.first && m_even.second == -1 && m_odd.second == -1) {
        cout << n / 2;
        return 0;
    }

    if (m_even.first != m_odd.first) {
        cout << n - even[m_even.first] - odd[m_odd.first];
    } else {
        if (even[m_even.first] > odd[m_even.second]) {
            cout << n - even[m_even.first] - odd[m_odd.second];
        } else {
            cout << n - even[m_even.second] - odd[m_odd.first];
        }
    }
    return 0;
}

