template<typename T>
class UnionFind {
public:
  vector<T> data;
  UnionFind(T size) : data(size, -1) {}

  // xの属する木とyの属する木を融合
  bool union_set(T x, T y)
  {
    x = root(x);
    y = root(y);
    if (x != y) {
      if (data[y] < data[x]) {
        swap(x, y);
      }
      data[x] += data[y];
      data[y] = x;
    }
    return x != y;
  }

  // x, yが同じ木に属するならtrue, そうでないならfalse
  bool find_set(T x, T y)
  {
    return root(x) == root(y);
  }

  // xの属する木の根を出力
  T root(T x)
  {
    return data[x] < 0 ? x : data[x] = root(data[x]);
  }

  // xの属する木に含まれる要素の数を出力
  T size(T x)
  {
    return -data[root(x)];
  }
};

