  sort(even, even + MAX, [](const int& a, const int& b){ return a > b; });

  int min_odd = N / 2;
  int min_even = N / 2;
  for (int i = 0; i < MAX; i++) {
    int odd_half = N / 2 - odd[i];
    int even_half = N / 2 - even[i];
    for (int j = i + 1; j < MAX; j++) {
      if (odd[j] == odd_half) {
        if (min_odd > odd[j]) {
          min_odd = odd[j];
        }
      }
      if (even[j] == even_half) {
        if (min_even > even[j]) {
          min_even = even[j];
        }
      }
    }
  }
  if (min_even == N/2 && min_odd == N/2) {
    cout << N / 2 << endl;
  }
  else {
    cout << min_even + min_odd << endl;
  }

  return 0;
}

