using namespace std;

vector< pair<int, int> > majority(vector<int>& nums) {
	map<int, int> cnt;
	vector< pair<int, int> > ans;
	ans.push_back(make_pair(0, -1));
	for (int n: nums) {
		if (cnt.find(n) != cnt.end()) cnt[n]++;
		else cnt[n] = 1;
	}
	for (auto it = cnt.begin(); it != cnt.end(); it++) {
		ans.push_back(make_pair(-it->second, it->first));
	}
	return ans;
}

