		else even.push_back(v);
	}
	vector< pair<int, int> > major_even = majority(even);
	vector< pair<int, int> > major_odd = majority(odd);
	int ans = 0;
	if (major_even[0].second != major_odd[0].second) {
		ans = n + major_even[0].first + major_odd[0].first;
	} else {
		ans = min(n + major_even[0].first + major_odd[1].first,
