	if (v1[0].second != v2[0].second) {
		ret = n - v1[0].first - v2[0].first;
	}
	else if (SZ(v1) == 1 && SZ(v2) == 1) {
		ret = n / 2;
	}
	else if (SZ(v1) == 1) {
		ret = n / 2 - v2[1].first;
