	for(int i=1;i<=n;i++) maxa=max(maxa,a[i]),maxb=max(maxb,b[i]);
	for(int i=1;i<=maxa;i++) aa[i].x=i;
	for(int i=1;i<=maxb;i++) bb[i].x=i;
	for(int i=1;i<=n;i++) aa[a[i]].cnt++,bb[b[i]].cnt++;
