int main() {
  IN(N);

  map<int, int> odd;
  map<int, int> even;
  REP(i, N) {
    IN(v);
    if (i % 2 == 0) {
      if (even.find(v) == even.end())
        even[v] = 0;
      ++even[v];
    } else {
      if (odd.find(v) == odd.end())
        odd[v] = 0;
      ++odd[v];
    }
  }
  int max_odd = 0, max_even = 0;
  int second_odd = -1, second_even = -1;
  for (const auto& e : odd) {
    if (odd[max_odd] < e.second) {
      second_odd = max_odd;
      max_odd = e.first;
    }
  }
  for (const auto& e : even) {
    if (even[max_even] < e.second) {
      second_even = max_even;
      max_even = e.first;
    }
  }
  if (max_odd == max_even) {
    if (second_odd == -1)
      OUT(N - odd[max_odd]- even[second_even]);
    else if (second_even == -1)
      OUT(N - odd[second_odd] - even[max_even]);
    else
      OUT(min(N - odd[second_odd] - even[max_even], N - odd[max_odd]- even[second_even]));
