using namespace std;
int solve() {
    int n;
    cin >> n;
    map<int, int> odd, even;
    for (int i {}, t {}; i < n / 2; i++) {
        cin >> t;
        odd[t] = (odd.find(t) == odd.end() ? 1 : odd[t] + 1);
        cin >> t;
        even[t] = (even.find(t) == even.end() ? 1 : even[t] + 1);
    }
    auto findMax = [](const auto& m) {
        return *max_element(m.begin(), m.end(), [](const auto& p, const auto& q) {
            return p.second < q.second;
        });
    };
    const auto e1 = findMax(even), o1 = findMax(odd);
    even[e1.first] = 0;
    odd[o1.first] = 0;
    const auto e2 = findMax(even), o2 = findMax(odd);
    if (e1.first != o1.first) return n - e1.second - o1.second;
    return min(n - e1.second - o2.second, n - e2.second - o1.second);
}
int main() {
    cout << solve() << endl;
}

