int n,cnt,a[111111],id[111111],w[111111],u[111111],v[111111];
bool vis[111111];
bool cmp(int x,int y){return a[x]<a[y];}
void add(int x,int y){u[++cnt]=x,v[cnt]=y;}
int main(){
	scanf("%d",&n);
	for(int i=1;i<=n;i++)scanf("%d",&a[i]),id[i]=i,w[i]=a[i];
	sort(id+1,id+n+1,cmp),sort(w+1,w+n+1);
	for(int i=n;i>=1;i--)if(!vis[id[i]]){
		int k=id[i],siz=1;
		while(1){
			vis[k]=1;
			int x=siz*2-n+a[k],pos=lower_bound(w+1,w+n+1,x)-w;
			if(w[pos]!=x)break;
			add(id[pos],k);
			if(vis[id[pos]]||pos==1)break;
			k=id[pos],siz++;
		}
	}
	if(cnt!=n-1){printf("-1");return 0;}
