vector<int> MostFrequent(const map<int, int>& m) {
  int result = 0;
  for (auto it : m) result = max(result, it.second);
  vector<int> a;
  for (auto it : m) if (it.second == result) a.push_back(it.first);
  return a;
}

int SecondFrequent(const map<int, int>& m) {
  int result = 0;
  for (auto it : m) result = max(result, it.second);
  int result2 = 0;
  for (auto it : m) {
    if (it.second == result) continue;
    result2 = max(result2, it.second);
  }
  return result2;
}

int main()
{
