    m[i % 2][a]++;
  }
  vector<int> even = MostFrequent(m[0]);
  vector<int> odd = MostFrequent(m[1]);
  if (even.size() > 1 || odd.size() > 1 || even[0] != odd[0]) {
    cout << n - m[0][even[0]] - m[1][odd[0]] << endl;
    return 0;
  }
  cout << n - m[0][even[0]] - max(SecondFrequent(m[0]), SecondFrequent(m[1])) << endl;
  return 0;
}

