void solve(){
  SORT(A); SORT(B);
  int A_conti = 1;
  std::vector<int> A_hist(MAX,1);

  int B_conti = 1;
  std::vector<int> B_hist(MAX,1);

  REP0(i,n/2-1){
    if(A[i]==A[i+1]){
      A_conti++;
      A_hist[A[i]] = A_conti;
    }else{
      A_conti = 1;
    }
    if(B[i]==B[i+1]){
      B_conti++;
      B_hist[A[i]] = B_conti;
    }else{
      B_conti = 1;
    }


  }

  auto A_itr = A_set.begin();
  auto B_itr = B_set.begin();
  int A_size = A_set.size();
  int B_size = B_set.size();
  int A_mode_cnt = 1;
  int A_mode;
  int B_mode_cnt = 1;
  int B_mode;

  if (A_size == 1 && B_size == 1 && A[0]!=B[0]) {
    std::cout << 0 << '\n';
    return;
  }else if(A_size == 1 && B_size == 1 && A[0]==B[0]){
    std::cout << n/2 << '\n';
    return;
  }


  if (A_size <= B_size) {
      REP0(i,A_size){
        if (A_mode_cnt <= A_hist[*(A_itr)]) {
          A_mode_cnt = A_hist[*(A_itr)];
          A_mode = *(A_itr);
        }
        A_itr = ++A_itr;
      }
      REP0(i,B_size){
        if (B_mode_cnt <= B_hist[*(B_itr)] && A_mode != *(B_itr)) {
          B_mode_cnt = B_hist[*(B_itr)];
          B_mode = *(B_itr);
        }
        B_itr = ++B_itr;
      }
  } else {
    REP0(i,B_size){
      if (B_mode_cnt <= B_hist[*(B_itr)]) {
        B_mode_cnt = B_hist[*(B_itr)];
        B_mode = *(B_itr);
      }
      B_itr = ++B_itr;
    }
    REP0(i,A_size){
      if (A_mode_cnt <= A_hist[*(A_itr)] && B_mode != *(A_itr)) {
        A_mode_cnt = A_hist[*(A_itr)];
        A_mode = *(A_itr);
      }
      A_itr = ++A_itr;
    }
  }

  std::cout << n-(A_mode_cnt + B_mode_cnt) << '\n';

}

