        else{
                t.data=b[i];
                t.len=lb;
                cb.push(t),lb=1;
        }
    }
    while(ca.size()&& cb.size()){
        if(ca.front().data==cb.front().data){
            if(ca.front().len>cb.front().len){
                cb.pop();
            }else if(ca.front().len<cb.front().len){
