using namespace std;

int getans(map<int, int> mp) {
    int sum = 0, mx = 0;
    for (auto x : mp) {
        sum += x.second; mx = max(mx, x.second);
    }
    return sum - mx;
}

void solve() {
    int n;
    cin >> n;
    map<int, int> odd, even;
    set<int> st;
    for (int i = 0; i < n; i++) {
        int v; cin >> v;
        if (i % 2 == 0) even[v]++;
        else odd[v]++;
        st.insert(v);
    }
    if (st.size() == 1) {
        cout << n / 2;
        return;
    }
    cout << getans(odd) + getans(even);
}

int main() {
    ios::sync_with_stdio(NULL), cin.tie(0), cout.tie(0);
    cout.setf(ios::fixed), cout.precision(20);
    solve();
}

