int main (int argc, char **argv) {
  int n;
  scanf("%d", &n);
  memset(cnt1, 0, sizeof(cnt1));
  memset(cnt2, 0, sizeof(cnt2));

  int v1[2] = {0}, v2[2] = {0};
  int v;
  for (int i=1; i <= n; i++) {
     scanf("%d", &v);

     if (i&1) {
       if (cnt1[v1[0]] < ++cnt1[v]) {
         v1[0] = v;
       } else if (v1[1] == 0 || cnt1[v] > cnt1[v1[1]]) {
         v1[1] = v;
       }
     } else {
       if (cnt2[v2[0]] < ++cnt2[v]) {
         v2[0] = v;
       } else if (v2[1] == 0 || cnt2[v] > cnt2[v2[1]]) {
         v2[1] = v;
       }
     }
  }

  int ans;
  if (v1[0] == v2[0]) {
    if (v1[1] == 0 && v2[1] == 0) {
      ans = n/2;
    } else if (v1[1] == 0) {
      ans = n/2 - cnt2[v2[1]];
    } else if (v2[1] == 0) {
      ans = n/2 - cnt1[v1[1]];
    } else {
      ans = n - std::max(cnt1[v1[0]] + cnt2[v2[1]], cnt1[v1[1]] + cnt2[v2[0]]);
    }
  } else {
    ans = n - (cnt1[v1[0]] + cnt2[v2[0]]);
  }
  printf("%d\n", ans);
