#include <bits/stdc++.h>
#define REP(i, n) for (int i = 0; (i) < (int)(n); ++ (i))
#define REP3(i, m, n) for (int i = (m); (i) < (int)(n); ++ (i))
#define REP_R(i, n) for (int i = int(n) - 1; (i) >= 0; -- (i))
#define REP3R(i, m, n) for (int i = int(n) - 1; (i) >= (int)(m); -- (i))
#define ALL(x) begin(x), end(x)
using namespace std;
template <class T, class U> inline void chmin(T & a, U const & b) { a = min<T>(a, b); }

int solve(int n, vector<int> const & v) {
    map<int, int> f, g;
    REP (i, n) {
        (i % 2 == 0 ? f : g)[v[i]] += 1;
    }
    vector<pair<int, int> > a, b;
    for (auto it : f) a.emplace_back(it.second, it.first);
    for (auto it : g) b.emplace_back(it.second, it.first);
    a.emplace_back(0, 0);
    b.emplace_back(0, 0);
    sort(ALL(a));
    sort(ALL(b));
    reverse(ALL(a));
    reverse(ALL(b));
    a.resize(2);
    b.resize(2);
    int cnt = n;
    for (auto it1 : a) {
        int k1, a1; tie(k1, a1) = it1;
        for (auto it2 : b) {
            int k2, b2; tie(k2, b2) = it2;
            if (a1 != b2) {
                chmin(cnt, n - k1 - k2);
            }
        }
    }
    return cnt;
}

int main() {
    int n; cin >> n;
    vector<int> v(n);
    REP (i, n) cin >> v[i];
    cout << solve(n, v) << endl;
    return 0;
}

