using namespace std;

class SBSChecker {
private:
  unordered_map<int, int> valMap;
  int maxNVal;
  int type;

public:
  SBSChecker(int t) {
    maxNVal = 0;
    type = t;
  }

  int processNewVal() {
    int v;
    cin >> v;
    valMap[v]++;
    maxNVal = max(maxNVal, valMap[v]);
    return v;
  }

  void getNSameMap(multimap<int, int>& nSameMapOut) {
    for(auto itr=valMap.begin(); itr!=valMap.end(); itr++) {
        nSameMapOut.insert(make_pair(itr->second, itr->first));
    }
  }
};

int main() {
  size_t n;
  cin >> n;

  unordered_map<int, int> valMap;
  SBSChecker sbs1(1);
  SBSChecker sbs2(2);

  int d = 0;
  int hn = n / 2;
  for (size_t i = 0; i < hn; i++) {
    valMap[sbs1.processNewVal()]++;
    valMap[sbs2.processNewVal()]++;
  }

  if (valMap.size() == 1) {
    d = hn;
  } else {
    multimap<int, int> nSameMap1;
    multimap<int, int> nSameMap2;
    sbs1.getNSameMap(nSameMap1);
    sbs2.getNSameMap(nSameMap2);

    int maxNSame = 0;
    for(auto itr=nSameMap1.rbegin(); itr!=nSameMap1.rend(); itr++) {
      for(auto itr2=nSameMap2.rbegin(); itr2!=nSameMap2.rend(); itr2++) {
        if (itr->second != itr2->second) {
           maxNSame = max(maxNSame, itr->first + itr2->first);
           break;
        }
      }
    }

    d = n - maxNSame;
  }

  cout << d << "\n";

  return 0;
}

