vii calc(vector<int>& a) {
  map<int, int> cnt;
  for (int& x : a) cnt[x]++;
  vector<ii> cur;
  for (auto p : cnt)
    cur.push_back({p.second, p.first});
  sort(cur.begin(), cur.end());
  if (cur.size() > 2) cur.resize(2);
  return cur;
}

void solve() {
  int n;
  cin >> n;
  vector<int> even, odd;
  rep(i, 0, n) {
    int u; cin >> u;
    if (i & 1) odd.push_back(u);
    else even.push_back(u);
  }
  auto lhs = calc(even), rhs = calc(odd);

  int res = 0;
  if (lhs[0].second != rhs[0].second) {
    res = lhs[0].first + rhs[0].first;
  } else {
    if (rhs.size() > 1) res = max(res, lhs[0].first + rhs[1].first);
    if (lhs.size() > 1) res = max(res, lhs[1].first + rhs[0].first);
    res = max(res, max(lhs[0].first, rhs[0].first));
  }
  cout << n - res;
}

