        else{
            mp_odd[v_odd[i]]++;
            if(mp_odd[v_odd[i]]>max_odd){
                max2_odd=max_odd;
                max_odd=mp_odd[v_odd[i]];
                num_max_odd=v_odd[i];
            }
        }

        if(mp_even.find(v_even[i])==mp_even.end()){
            mp_even[v_even[i]]=1;
