        even[i]=v[2*i];
        odd[i]=v[2*i+1];
    }

    sort(even,even+n/2);
    sort(odd,odd+n/2);

    int num1[n/2];
    int num2[n/2];

    num1[0]=1;
    for(int i=1; i<n/2; i++){
        if(even[i]==even[i-1]){
            num1[i]=num1[i-1]+1;
        }else{
            num1[i]=1;
        }
    }

    num2[0]=1;
    for(int i=1; i<n/2; i++){
        if(odd[i]==odd[i-1]){
            num2[i]=num2[i-1]+1;
        }else{
            num2[i]=1;
        }
    }

    int max1=0, max2=0, max3=0, max4=0;
    int v1,v2;
    for(int i=0; i<n/2; i++){
        if(i==n/2-1 || num1[i+1]==1){
            if(max1<=num1[i]){
                max2=max1;
                max1=num1[i];
                v1=even[i];
            }
        }

        if(i==n/2-1 || num2[i+1]==1){
            if(max3<=num2[i]){
                max4=max3;
                max3=num2[i];
                v2=odd[i];
            }
        }
    }

    if(v1!=v2){
        cout<<n-max1-max3<<endl;
    }else{
        cout<<n-max(max1+max4, max2+max3)<<endl;
    }

//    cout<<v1<<" "<<v2<<endl;
    return 0;
}

