unordered_map<int, int> cnt[2];

int main() {
  int n;
  scanf("%d", &n);

  int ans = INF;
  int n_odd = n / 2 + (n & 1), n_even = n / 2;

  for (int i = 1; i <= n; i++) {
    int x;
    scanf("%d", &x);

    cnt[i & 1][x]++;
  }

  vector<pair<int, int> > v1, v2;
  for (auto it : cnt[1])
    v1.push_back(it);
  for (auto it : cnt[0])
    v2.push_back(it);

  sort(v1.begin(), v1.end());
  sort(v2.begin(), v2.end());

  reverse(v1.begin(), v1.end());
  reverse(v2.begin(), v2.end());

  int t = n_even;
  for (int i = 0, j = 0; i < (int)v1.size(); i++) {
    while (j < (int)v2.size() && v2[j].first > v1[i].first) {
      t = min(t, n_even - v2[j++].second);
    }

    ans = min(ans, n_odd - v1[i].second + t);
  }

  t = n_odd;
  for (int i = 0, j = 0; i < (int)v2.size(); i++) {
    while (j < (int)v1.size() && v1[j].first > v2[i].first) {
      t = min(t, n_odd - v1[j++].second);
    }

    ans = min(ans, n_even - v2[i].second + t);
  }

  printf("%d\n", ans);

  return 0;
}

