int main(){
  ios::sync_with_stdio(false);
  cin.tie(0);

  int n,m;
  cin >> n >>m;
  vector<pair<int, int> > g[n];  
  int c,a,b;
  rep(i,m){
    cin >> c >> a >> b;
    g[a].pb({b,c});
    g[b].pb({a,c});    
  }
  int dp[n][2];//最小コストとその時のbの本数
  rep(i,n){
    dp[i][0]=INT_MAX;
    dp[i][1]=INT_MAX;
  }
  //  dp[0][0]=0;
  //  dp[0][1]=0;
  priority_queue<tuple<int, int, int>, vector<tuple<int, int, int> >,greater<tuple<int, int, int> > > de; //それまでに通ったbの本数、aの本数、場所
  de.push(mt(0,0,0));
  while(!de.empty()){
    tuple<int,int,int> t=de.top();de.pop();
    int v=get<2>(t);
    int cost=get<1>(t);
    int b=get<0>(t);
    if(dp[v][0]<cost){//記録しない
      if(dp[v][1]>b){
	for(auto j:g[v]){
          int tv=j.first;
          int tc=j.second;
          if(tc==0){
            de.push(mt(b,cost+1,tv));
          }
          else de.push(mt(b+1,cost+(b+1),tv));
	}
      }
      else continue;
    }
    else if(dp[v][0]==cost){
      if(dp[v][1]<=b) continue;
      else{
	dp[v][1]=b;
	for(auto j:g[v]){
	  int tv=j.first;
	  int tc=j.second;
	  if(tc==0){
	    de.push(mt(b,cost+1,tv));
	  }
	  else de.push(mt(b+1,cost+(b+1),tv));
	}
      }
    }
    else{
      dp[v][0]=cost;
      dp[v][1]=b;
      for(auto j:g[v]){
          int tv=j.first;
          int tc=j.second;
          if(tc==0){
            de.push(mt(b,cost+1,tv));
          }
          else de.push(mt(b+1,cost+(b+1),tv));
	}
    }
  }


  rep(i,n){
    cout << dp[i][0] << endl;
  }

  return 0;


}

