	}
	for (int i = 1; i <= n; i ++ ) {
		int d = i & 1;
		bu[d][a[i]] ++ ;
		if (a[i] == id[d][0] || a[i] == id[d][1]) {
			if (a[i] == id[d][1]) {
				if (bu[d][a[i]] > bu[d][id[d][0]]) {
					swap(id[d][0], id[d][1]);
				}
			}
		}
		else {
			if (bu[d][a[i]] > bu[d][id[d][0]]) {
				id[d][1] = id[d][0];
