// 最大公約数
ll gcd(ll a, ll b)
{
  if(b == 0) return a;
  return gcd(b, a % b);
}

// mod m におけるa の逆元
ll modinv(ll a, ll m) {
  ll b = m, u = 1, v = 0;
  while (b) {
    ll t = a / b;
    a -= t * b; swap(a, b);
    u -= t * v; swap(u, v);
  }
  u %= m;
  if (u < 0) u += m;
  return u;
}

// 素因数分解
vector<pair<ll, ll>> prim;
void pf(ll n)
{
  ll s = sqrt(n);
  ll r = 0;
  for(ll i = 2; i <= s; i++) {
    if((n % i) == 0) {
      r = 0;
      do {
	r++;
	n = n / i;
      } while((n % i) == 0);
      prim.push_back({i, r});
    }
  }
  if(n > s) {
    prim.push_back({n, 1});
  }
}

void solve()
{
  ll N; cin >> N;

  vector<ll> a(N); rep(i, N) cin >> a[i];
  map<ll, ll> c0, c1;
  vector<pair<ll, ll>> vp0, vp1;
  ll ans = 0;

  rep(i, N) {
    if(i % 2 == 0) {
      c0[a[i]] ++;
    } else {
      c1[a[i]] ++;
    }
  }

  for(auto itr : c0) {
    vp0.push_back(make_pair(itr.second, itr.first));
  }
  for(auto itr : c1) {
    vp1.push_back(make_pair(itr.second, itr.first));
  }
  sort(vp0.begin(), vp0.end(), greater<pair<ll,ll>>());
  sort(vp1.begin(), vp1.end(), greater<pair<ll,ll>>());

  if(vp0[0].second == vp1[0].second) {
    if(vp0[0].first == vp1[0].first) {
      ans = N - vp0[0].first - max(vp0[1].first, vp1[1].first);
    } else {
      if(vp0[0].first > vp1[0].first) {
	ans = N - vp0[0].first - vp1[1].first;
      } else {
	ans = N - vp1[0].first - vp0[1].first;
      }
    }
  } else {
    ans = N - vp0[0].first - vp1[0].first;
  }
  cout << ans << endl;
}


