	int e_m = -1;

	for (auto e : even) {
		even_max = max(e.second, even_max);
		if (e.second == even_max) e_m = e.first;

	}
	for (auto o : odd) {
		if (o.first != e_m) odd_max = max(o.second, odd_max);
	}
	best = max(best, odd_max + even_max);

	printf("%d\n", n - best);

	return 0;
}

