tuple<int,int,int> fd_mx(map<int,int> mp){
    vector<int> tmp;
    int val = 0;
    int mx = 0;
    for(auto it : mp){
        if(mx < it.second){
            mx = it.second;
            val = it.first;
        }
        tmp.emplace_back(it.second);
    }
    sort(tmp.begin(),tmp.end(),[=](int x,int y){return x > y;});
    int f = tmp[0];
    int s = 0;
    if(tmp.size() > 1) s = tmp[1];

    return tuple<int,int,int>(val,f,s);
}

