#define REP(i,n) FOR(i,0,n)  
#define FORE(i,a,b) for(int i=(a);i<=(b);++i)  
#define REPE(i,n) FORE(i,0,n)  
#define FORSZ(i,a,v) FOR(i,a,SZ(v))  
#define REPSZ(i,v) REP(i,SZ(v))  
typedef long long ll;
typedef unsigned long long ull;
ll gcd(ll a, ll b) { return b == 0 ? a : gcd(b, a%b); }

const int MAXN = 100000;

int n;
int a[MAXN];

int b[MAXN], nb;
int c[MAXN], nc;

pair<int, int> d[MAXN]; int nd;
pair<int, int> e[MAXN]; int ne;

void run() {
	scanf("%d", &n);
	REP(i, n) scanf("%d", &a[i]);

	nb = nc = 0; REP(i, n) if (i % 2 == 0) b[nb++] = a[i]; else c[nc++] = a[i]; sort(b, b + nb); sort(c, c + nc);
	nd = 0; for (int l = 0, r = l; l < nb; l = r) { while (r < nb&&b[l] == b[r]) ++r; d[nd++] = MP(-(r - l), b[l]); } sort(d, d + nd);
	ne = 0; for (int l = 0, r = l; l < nc; l = r) { while (r < nc&&c[l] == c[r]) ++r; e[ne++] = MP(-(r - l), c[l]); } sort(e, e + ne);
	int ret = INT_MAX;
	REPE(di, 2) REPE(ei, 2) {
		int cd = di < nd ? d[di].second : -1, ce = ei < ne ? e[ei].second : -1;
		if (cd != -1 && ce != -1 && cd == ce) continue;
		int cur = nb - (di < nd ? -d[di].first : 0) + nc - (ei < ne ? -e[ei].first : 0);
		ret = min(ret, cur);
	}
	printf("%d\n", ret);
}

int main() {
	run();
	return 0;
}

