template<typename A, typename B>
std::pair<B,A> flip_pair(const std::pair<A,B> &p)
{
    return std::pair<B,A>(p.second, p.first);
}

template<typename A, typename B>
std::multimap<B,A> flip_map(const std::map<A,B> &src)
{
    std::multimap<B,A> dst;
    std::transform(src.begin(), src.end(), std::inserter(dst, dst.begin()),
                   flip_pair<A,B>);
    return dst;
}

ll solve() {
    int N;
    cin >> N;

    map<int, int> o, e;
    REP(i, N) {
        int v;
        cin >> v;
        if (i%2) {
            o[v]++;
        } else {
            e[v]++;
        }
    }

    auto fo = flip_map<int, int>(o);
    auto fe = flip_map<int, int>(e);
    auto ito = fo.rbegin();
    auto ite = fe.rbegin();

    if (ito->second != ite->second) return (N+1)/2 - ito->first + N/2 - ite->first;

    int okeep = (N+1)/2 - ito->first;
    int ekeep = N/2 - ite->first;
    ito++;
    ite++;

    if (ito == fo.rend() && ite == fe.rend()) return N/2;
    else if (ito == fo.rend()) return N/2 - ite->first + okeep;
    else if (ite == fe.rend()) return (N+1)/2 - ito->first + ekeep;

    return min((N+1)/2 - ito->first + ekeep, N/2 - ite->first + okeep);
}

int main() {
    cout << solve() << endl;
}

