		} else {
			int reserve = dp[1][in1];
			dp[1][in1] = 0;
			in2 = max_element(dp[1].begin(), dp[1].end()) - dp[1].begin();
			ans = min(ans, n-dp[0][in1]-dp[1][in2]);
			dp[1][in1] = reserve;
		}
		swap (dp[0], dp[1]);
	}
	cout << ans;
	return 0;
}

