    for (ll i = 0; i < n; i++) {
        cin >> v[i];
    }

    constexpr ll MAX = 1e5;
    vector<vector<ll>> num(2, vector<ll>(MAX + 1, 0));
    for (ll i = 0; i < n; i++) {
        num[i % 2][v[i]]++;
    }

    ll ans = 0;

    ll max_index[2] = { -1, -1 };
    ll max_value[2] = { -1, -1 };

    for (ll i = 0; i < 2; i++) {
        for (ll j = 0; j <= MAX; j++) {
            if (num[i][j] > max_value[i]) {
                max_value[i] = num[i][j];
                max_index[i] = j;
            }
        }
    }

    if (max_index[0] == max_index[1]) {
        ll second_index[2] = { -1, -1 };
        ll second_value[2] = { -1, -1 };

        for (ll i = 0; i < 2; i++) {
            for (ll j = 0; j <= MAX; j++) {
                if (j == max_index[i]) {
                    continue;
                }
                if (num[i][j] > second_value[i]) {
                    second_value[i] = num[i][j];
                    second_index[i] = j;
                }
            }
        }

        ll ans0 = n - max_value[0] - second_value[1];
        ll ans1 = n - max_value[1] - second_value[0];
        ans = min(ans0, ans1);
    } else {
        ans += n - max_value[0] - max_value[1];
    }

    cout << ans << endl;
}

