pii makeSame(const vi& v, int banned) {
  vi slots(1e5+1, 0);
  for (auto i : v) {
    if (i == banned) continue;
    slots[i]++;
  }

  int m = -1;
  int index = -1;
  for (int i=1; i<int(slots.size()); i++) {
    if (m < slots[i]) {
      m = slots[i];
      index = i;
    }
  }

  return make_pair(v.size()-m, index);
}

int main(int argc, char** argv) {
  int n;
  cin >> n;
  vi a(n/2); // even indices
  vi b(n/2); // odd indices
  for (int i=0; i<n/2; i++) {
    cin >> a[i] >> b[i];
  }

  // from even
  auto r1a = makeSame(a, -1);
  int ret1 = r1a.first;
  auto r1b = makeSame(b, r1a.second);
  ret1 += r1b.first;


  // from odd
  auto r2b = makeSame(b, -1);
  int ret2 = r2b.first;
  auto r2a = makeSame(a, r2b.second);
  ret2 += r2a.first;

  cout << min({ret1, ret2}) << endl;

  return 0;
}

