int n,a[N],n1,n2;
map <int,int> M;
pair<int,int> p1[N],p2[N];
int main()
{
	scanf("%d",&n);
	n1=(n+1)/2;
	n2=n/2;
	for(int i=1;i<=n;i++)
		scanf("%d",&a[i]);
	int Ans=0;
	for(int i=1;i<=n;i+=2)
		M[a[i]]++;
	for(int i=1;i<=n;i+=2)
		p1[(i+1)/2]=make_pair(M[a[i]],a[i]);
	M.clear();
	for(int i=2;i<=n;i+=2)
		M[a[i]]++;
	for(int i=2;i<=n;i+=2)
		p2[i/2]=make_pair(M[a[i]],a[i]);
	sort(p1+1,p1+1+n1); sort(p2+1,p2+1+n2);
	n1=unique(p1+1,p1+1+n1)-p1;
	n2=unique(p2+1,p2+1+n2)-p2;
	p1[n1]=make_pair(0,0);
	p2[n2]=make_pair(0,0);
	n1--; n2--;
	if(p1[n1].second!=p2[n2].second)
		Ans=n-p1[n1].first-p2[n2].first;
	else 
		Ans=n-min(p1[n1-1].first+p2[n2].first,p1[n1].first+p2[n2-1].first);
	cout << Ans << endl;

	return 0;
}

