class Counter
{
public:
    void Add(int num)
    {
        count_[num] += 1;
        UpdateBest(num);
    }

    int Count(int num) const
    {
        return count_.count(num) == 0 ? 0 : count_.at(num);
    }

    int FirstCommon() const { return first_; }
    int SecondCommon() const { return second_; }

private:
    void UpdateBest(int num)
    {
        if (first_ == -1 || count_[num] > count_[first_]) {
            second_ = first_;
            first_ = num;
        } else if (num != first_ && (second_ == -1 || count_[num] > count_[second_])) {
            second_ = num;
        }
    }

    map<int, int> count_;
    int first_ = -1;
    int second_ = -1;
};

int main()
{
    int n;
    cin >> n;

    Counter evens;
    Counter odds;

    for (int i = 0; i < n; i += 1) {
        int num;
        cin >> num;
        (i % 2 == 0 ? evens : odds).Add(num);
    }

    pair<int, int> e = {evens.FirstCommon(), evens.SecondCommon()};
    pair<int, int> o = {odds.FirstCommon(), odds.SecondCommon()};

    int res = 0;
    if (e.first != o.first) {
        res = n - evens.Count(e.first) - odds.Count(o.first);
    } else {
        res = n - evens.Count(e.first) - odds.Count(o.second);
        res = min(res, n - evens.Count(e.second) - odds.Count(o.first));
    }

    cout << res << "\n";
    return 0;
}

