    if(n==2){
        printf("0");
        free(input);
        return 0;
    }
    //スペース区切りで数字取得
    int table[EVEN_AND_ODD][100000];//mが偶数、奇数それぞれの時において、table[v_m]=v_mが何回登場したか
    for(int j=0;j<100000;j++){
        table[EVEN][j] = 0;
        table[ODD][j] = 0;
    }
    //v_mが何回出現したかを偶数、奇数番目それぞれについてカウント
    int num = atoi(strtok(input," "));
    table[EVEN][num]++;
    for(int i=1;i<n;i++){
        num = atoi(strtok(NULL," "));
        //printf("num[%d]:%d\n",i,num);
        table[i%2][num]++;
    }
    //要素数 = table[EVEN][最後に取得した文字]+table[ODD][最後に取得した文字]なら全ての数値が同じ
    if(n==table[EVEN][num]+table[ODD][num]){
        printf("%d",table[EVEN][num]);
        free(input);
        return 0;
    }
    //一番回数の大きいやつを除いた総出現数が解
    int max_times[EVEN_AND_ODD] = {0,0};//偶数、奇数番目それぞれについての最大回数
    int mode[EVEN_AND_ODD] = {1,1};//偶数、奇数番目それぞれについての最頻値
    int second_max_times[EVEN_AND_ODD] = {0,0};//偶数、奇数番目それぞれについて、二番目に大きい回数
    int solution[EVEN_AND_ODD] = {0,0};
    for(int c=0;c<100000;c++){
        solution[EVEN] += table[EVEN][c];
        if(max_times[EVEN]<table[EVEN][c]){
            max_times[EVEN] = table[EVEN][c];
            mode[EVEN] = c;
        }
        else if(second_max_times[EVEN]<table[EVEN][c] && table[EVEN][c]<max_times[EVEN]) second_max_times[EVEN] = table[EVEN][c];

        solution[ODD] += table[ODD][c];
        if(max_times[ODD]<table[ODD][c]){
            max_times[ODD] = table[ODD][c];
            mode[ODD] = c;
        }
        else if(second_max_times[ODD]<table[ODD][c] && table[ODD][c]<max_times[ODD]) second_max_times[ODD] = table[ODD][c];
    }
    //
    if(mode[EVEN]==mode[ODD]){
        if(second_max_times[EVEN]+max_times[ODD]>max_times[EVEN]+second_max_times[ODD]){
            solution[EVEN]-=second_max_times[EVEN];
            solution[ODD]-=max_times[ODD];
        }else{
            solution[EVEN]-=max_times[EVEN];
            solution[ODD]-=second_max_times[ODD];
        }
    }else{
        solution[EVEN]-=max_times[EVEN];
        solution[ODD]-=max_times[ODD];
    }

    printf("%d",solution[EVEN]+solution[ODD]);
    free(input);
    return 0;
}

