#define NUM 100001

int most(int *a,int n){
    int num[NUM], ans = a[0], i=0;
    for(i = 0; i < NUM; i++) num[i]=0;
    for(i=0;i<n;i++){
        num[a[i]]++;
    }
    for(i = 1; i < NUM; i++){
        if(num[i-1]<num[i]) ans = i;
    }
    return ans;
}

int most2(int *a,int n){
    int num[NUM], ans = a[0], first = a[0] ,i = 0;
    for(i = 0; i < NUM; i++) num[i]=0;
    for (i = 0; i < n; i++){
        num[a[i]]++;
    }
    for (i = 1; i < NUM; i++){
        if (num[i-1] < num[i]){
            ans = first;
            first = i;
        }
    }
    return ans;
}

