int compare (const void*a,const void*b)
{
    if(*(int*)a-*(int*)b>0) return 1;
    else if(*(int*)a-*(int*)b<0) return -1;
    return 0;
}

int cmp(int *a, int n)
{
  qsort(a,n,sizeof(int),compare); int count=1; int max =-1;
  for(int i=1;i<n;i++)
  {
      if(a[i]==a[i-1])
      {
          count++;
          if(max<count) max=count;
      }
      else count =1;
  }
  return (n-max);
}
