        max_odd_number = i;
      }
    } else {
      count = 1;
    }
  }
  int second_odd_count = 1;
  int second_odd_number;
  count = 1;
  for (int i = 1; i < n; i++) {
    if (odd[i] == odd[i-1]) {
      count++;
      if (i != max_odd_number && count > second_odd_count) {
        second_odd_count = count;
        second_odd_number = i;
      }
    } else {
      count = 1;
    }
  }
  if (max_odd_count == n) {
    second_odd_count = 0;
  }

  qsort(even, n, sizeof(int), cmpnum);
  int max_even_count = 1;
  int max_even_number = 0;
  count = 1;
  for (int i = 1; i < n; i++) {
    if (even[i] == even[i-1]) {
      count++;
      if (count > max_even_count) {
        max_even_count = count;
        max_even_number = i;
      }
    } else {
      count = 1;
    }
  }
  int second_even_count = 1;
  int second_even_number;
  count = 1;
  for (int i = 1; i < n; i++) {
    if (even[i] == even[i-1]) {
      count++;
      if (i != max_even_number && count > second_even_count) {
        second_even_count = count;
        second_even_number = i;
      }
    } else {
      count = 1;
    }
  }
  if (max_even_count == n) {
    second_even_count = 0;
  }

  int answer;
  int case2;
  if (odd[max_odd_number] != even[max_even_number]) {
    answer = n*2-max_odd_count-max_even_count;
  } else {
    answer = n*2-max_odd_count-second_even_count;
    case2 = n*2-second_odd_count-max_even_count;
    if (case2 < answer) {
      answer = case2;
    }
  }
