    printf("%d",(n/2));
    return 0;
  }

  for(i=0;i<(n/2)-1;i++){
    for(j=(n/2)-1;j>i;j--){
      if(odd[j-1]>odd[j]){
        tmp=odd[j-1];
        odd[j-1]=odd[j];
        odd[i]=tmp;
      }
      if(even[j-1]>even[j]){
        tmp=even[j-1];
        even[j-1]=even[j];
        even[i]=tmp;
      }
    }
  }

  now_o=odd[0];
  now_e=even[0];
  for(i=0;i<(n/2);i++){
    if(now_o==odd[i]){
      count_o++;
    } else {
      if(count_o>max_o1){
        max_o2=max_o1;
        max_num_o2=max_num_o1;
        max_o1=count_o;
        max_num_o1=now_o;
        count_o=0;
      } else if(count_o>max_o2){
        max_o2=count_o;
        max_num_o2=now_o;
        count_o=0;
      }
      now_o=odd[i];
    }

    if(now_e==even[i]){
      count_e++;
