      if(count_e>max_e1){
        max_e2=max_e1;
        max_num_e2=max_num_e1;
        max_e1=count_e;
        max_num_e1=now_e;
        count_e=0;
      } else if(count_e>max_e2){
        max_e2=count_e;
        max_num_e2=now_e;
        count_e=0;
      }
      now_e=even[i];
    }
  }

  if(max_num_o1==max_num_e1){
    if(max_o1<max_e1){
      printf("%d",(n-max_o2-max_e1));
    } else {
      printf("%d",(n-max_o1-max_e2));
    }
  } else {
    printf("%d",(n-max_o1-max_e1));
  }
}

