        if (e[i] == e[i - 1])
            x++;
        else
        {
            if (x > ne1)
                ne1 = x;
            e1 = e[i - 1];
            x = 1;
        }
    x = 1;
    for (i = 1; i <= m; i++)
        if (o[i] == o[i - 1])
            x++;
        else
        {
            if (x > no1)
                no1 = x;
            o1 = o[i - 1];
            x = 1;
        }
    if (e1 != o1)
    {
        printf("%d\n", n - ne1 - no1);
        return 0;
    }
