    for (i = 1; i <= m; i++)
        if (e[i] == e[i - 1] && e[i] != e1)
            x++;
        else
        {
            if (x > ne2)
                ne2 = x;
            if (e[i] == e1)
                x = 0;
            else
                x = 1;
        }
    if (o[0] == o1)
