    for (i = 1; i <= m; i++)
        if (o[i] == o[i - 1] && o[i] != o1)
            x++;
        else
        {
            if (x > no2)
                no2 = x;
            if (o[i] == o1)
                x = 0;
            else
                x = 1;
        }
    if (no2 < ne2)
        ne1 = ne2;
    else
        no1 = no2;
