#include <stdio.h>
#include <stdlib.h>

#define NUM 100001

int most(int *a,int n){
    int num[NUM], ans = a[0], i=0;
    for(i = 0; i < NUM; i++) num[i]=0;
    for(i=0;i<n;i++){
        num[a[i]]++;
    }
    for(i = 0; i < NUM; i++){
        if(num[i]<num[i+1]) ans = i;
    }
    return ans+1;
}

int most2(int *a,int n){
    int num[NUM], ans = a[0], first = a[0] ,i = 0;
    for(i = 0; i < NUM; i++) num[i]=0;
    for (i = 0; i < n; i++){
        num[a[i]]++;
    }
    for (i = 0; i < NUM; i++){
        if (num[i] < num[i + 1]){
            first = i;
            ans = first;
        }
    }
    return ans+1;
}

int okikae(int *a, int mos, int n){
    int counter=0,i=0;
    while(i<n){
        if(a[i] != mos) {counter++;}
        i++;
    }
    return counter;
}

