    int n,i=0,count=0,acount=0,bcount=0;
    scanf("%d",&n);
    n = n / 2;
    int *a = malloc(sizeof(int)*n);
    int *b = malloc(sizeof(int)*n);
    for(i = 0; i < n; i++){
        scanf("%d",(a+i));
        scanf("%d",(b+i));
    }
    printf("%d %d\n%d %d\n",a[0],a[1],b[0],b[1]);
    int a1 = most(a,n);
    int b1 = most(b,n);
    int a2 = most2(a,n);
    int b2 = most2(b,n);
    printf("most a1 = %d   a2 = %d   b1 = %d   b2 = %d\n",a1,a2,b1,b2);
    acount += okikae(a, a1, n);
    bcount += okikae(b, b1, n);
    printf("acount=%d bcount=%d\n", acount,bcount);
    if(a1 != b1){
        count = acount + bcount;
    }else{
        acount += okikae(b,b2,n);
        bcount += okikae(a,a2,n);
        if(acount < bcount) count = acount;
        else count = bcount;
    }
    printf("%d\n",count);
    return 0;
}

