fun main(args : Array<String>) {
    val n = Integer.parseInt(readLine())
    val v = readLine()!!.split(" ").map(String::toInt)

    // vのユニークな要素数でArrayを作成
    val array = IntArray(v.max()!! + 1)

    // vの1番目の最頻値と2番目の最頻値を取得
    for (value in v) {
        array[value]++
    }
    val maxIdx1 = array.indices.maxBy { array[it] }
    array[maxIdx1!!] = 0
    val maxIdx2 = array.indices.maxBy { array[it] }

    // 書き換え対象が偶数番目か奇数番目かを判定
    var count = 0
    var i = 0
    var evenCount = 0
    var oddCount = 0
    while(i < n) {
        if (v[i] == maxIdx1) {
            // 偶数・奇数番目にあるmaxIdx1をカウント
            if (i % 2 == 0) {
                evenCount++
            } else {
                oddCount++
            }
        }
        i++
    }

    // 書き換え処理
    // 書き換え対象が偶数番目の場合
    // var output = v.toMutableList()
    i = 0
    if (evenCount >= oddCount) {
        while(i < n) {
            if (i % 2 == 0) {
                if (v[i] != maxIdx1) {
                    // output[i] = maxIdx1!!
                    count++
                }
            } else {
                if (v[i] != maxIdx2) {
                    // output[i] = maxIdx2!!
                    count++
                }
            }
            i++
        }
    // 書き換え対象が奇数番目の場合
    } else {
        while(i < n) {
            if (i % 2 != 0) {
                if (v[i] != maxIdx1) {
                    // output[i] = maxIdx1!!
                    count++
                }
            } else {
                if (v[i] != maxIdx2) {
                    // output[i] = maxIdx2!!
                    count++
                }
            }
            i++
        }
    }

    // println(output)
    println(count)

}

