            ans = Math.min(n - p2.second, ans)
        }
    }
    for (p2 in pairs2) {
        val p1 = pairs1[0]
        if (p1.first != p2.first) {
            ans = Math.min(n - p1.second - p2.second, ans)
        } else {
            ans = Math.min(n - p1.second, ans)
            ans = Math.min(n - p2.second, ans)
        }
    }
    println(ans)
}

fun toCountMap(xs: List<Int>): Map<Int, Int> {
    val count = mutableMapOf<Int, Int>()
    for (x in xs) {
        if (!count.containsKey(x)) {
            count[x] = 1
        } else {
            count[x] = count[x]!! + 1
        }
    }
    return count
}

