		int N = sc.nextInt();
		int[] odd = new int[100001];
		int[] even = new int[100001];
		for (int i = 0; i < N; i++) {
			int v = sc.nextInt();
			if (i % 2 == 0) {
				even[v]++;
			} else {
				odd[v]++;
			}
		}
		int max_odd = 0;
		int max_odd_id = 0;
		int max_even = 0;
		int max_even_id = 0;
