                even2nd = even1st;
                even1st = i;
            }
            if (oddCount[odd1st] <= oddCount[i]) {
                odd2nd = odd1st;
                odd1st = i;
            }
        }

        int evenAdopt;
        int oddAdopt;

        if (even1st != odd1st) {
            evenAdopt = even1st;
            oddAdopt = odd1st;

        } else if (evenCount[even1st] + oddCount[odd2nd] < evenCount[even2nd] + oddCount[odd1st]) {
            evenAdopt = even2nd;
            oddAdopt = odd1st;

        } else {
            evenAdopt = even1st;
            oddAdopt = odd2nd;
        }

