public class Main {

  public static void main(String[] args) {

    Scanner sc = new Scanner(System.in);

    int N = Integer.parseInt(sc.next());

    Map<Integer, Integer> oMap = new HashMap<>();
    Map<Integer, Integer> eMap = new HashMap<>();

    for (int i = 0; i < N; i++) {
      int v = Integer.parseInt(sc.next());
      if (i % 2 == 0) {
        oMap.merge(v, 1, Integer::sum);
      } else {
        eMap.merge(v, 1, Integer::sum);
      }
    }

    List<Entry<Integer, Integer>> list_entries_o = new ArrayList<Entry<Integer, Integer>>(oMap.entrySet());
    Collections.sort(list_entries_o, new Comparator<Entry<Integer, Integer>>() {
      //compareを使用して値を比較する
      public int compare(Entry<Integer, Integer> obj1, Entry<Integer, Integer> obj2) {
        //降順
        return obj2.getValue().compareTo(obj1.getValue());
      }
    });

    List<Entry<Integer, Integer>> list_entries_e = new ArrayList<Entry<Integer, Integer>>(eMap.entrySet());
    Collections.sort(list_entries_e, new Comparator<Entry<Integer, Integer>>() {
      //compareを使用して値を比較する
      public int compare(Entry<Integer, Integer> obj1, Entry<Integer, Integer> obj2) {
        //降順
        return obj2.getValue().compareTo(obj1.getValue());
      }
    });

    int ans = 0;
    if (list_entries_o.get(0).getKey() != list_entries_e.get(0).getKey()) {
      ans = N - list_entries_o.get(0).getValue() - list_entries_e.get(0).getValue();
    } else if (list_entries_o.get(0).getValue() >= list_entries_e.get(0).getValue()) {
      int e = 0;
      if (eMap.size() > 1) {
        e = list_entries_e.get(1).getValue();
      }
      ans = N - list_entries_o.get(0).getValue() - e;
    } else {
      int o = 0;
      if (oMap.size() > 1) {
        o = list_entries_o.get(1).getValue();
      }
      ans = N - o - list_entries_e.get(0).getValue();
    }
    System.out.println(ans);
  }
}

import java.util.Scanner;

public class Main {
    /**
     * @param args
     */
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] v = new int[n];
        for (int i=0; i<n; i++) {
            v[i] = sc.nextInt();
        }

        int ans = solve(n, v);

        System.out.println(ans);
    }

    private static int solve(int n, int[] v) {
        int[] hist = new int[100_001];
        int count = 0;

        for (int i = 0; i < n; i += 2) {
            hist[v[i]]++;
        }
        int[][] ans1 = top(hist);

        hist = new int[100_001];
        for (int i = 1; i < n; i += 2) {
            hist[v[i]]++;
        }
        int[][] ans2 = top(hist);

//        System.err.println(ans1[0][0] + "," + ans1[0][1] + " / " + ans1[1][0] + "," + ans1[1][1]);
//        System.err.println(ans2[0][0] + "," + ans2[0][1] + " / " + ans2[1][0] + "," + ans2[1][1]);

        if (ans1[0][1] != ans2[0][1]) {
            count = n - ans1[0][0] - ans2[0][0];
        } else {
            count = Math.min(n - ans1[0][0] - ans2[1][0], n - ans1[1][0] - ans2[0][0]); 
        }

        return count;
    }

    private static int[][] top(int[] hist) {
        int[][] ans = new int[2][2];
        for (int i=0; i<hist.length; i++) {
            if (hist[i] > 0) {
              if (hist[i] >= ans[0][0]) {
                  ans[1][0] = ans[0][0];
                  ans[1][1] = ans[0][1];

                  ans[0][0] = hist[i];
                  ans[0][1] = i;
              } else if (hist[i] > ans[1][0]) {
                  ans[1][0] = hist[i];
                  ans[1][1] = i;
              }
            }
        }

        return ans;
    }
}

