public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        C solver = new C();
        solver.solve(1, in, out);
        out.close();
    }

    static class C {
        ArrayList<Pair<Integer, Integer>> minChanges(int[] a, int off) {
            int[] dp = new int[100_001];
            int m = 0;
            for (int i = off; i < a.length; i += 2) {
                dp[a[i]]++;
                m++;
            }
            for (int i = 0; i < dp.length; i++) {
                dp[i] = m - dp[i];
            }
            ArrayList<Pair<Integer, Integer>> res = new ArrayList<>();
            for (int i = 0; i < dp.length; i++) {
                res.add(new Pair<>(i, dp[i]));
            }
            res.sort(Comparator.comparingInt(o -> o.second));
            return res;
        }

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.NextInt();
            int[] v = in.NextIntArray(n);
            ArrayList<Pair<Integer, Integer>> res1 = minChanges(v, 0), res2 = minChanges(v, 1);
            int best = n;
            for (Pair<Integer, Integer> i : res1) {
                best = Math.min(best, i.second + getBest(i.first, res2));
            }
            out.println(best);
        }

        private int getBest(int first, ArrayList<Pair<Integer, Integer>> res2) {
            for (int i = 0; i < res2.size(); i++) {
                Pair<Integer, Integer> v = res2.get(i);
                if (v.first == first) continue;
                return v.second;
            }
            return 0;
        }

    }

    static class InputReader {
        BufferedReader reader;
        StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine(), " \t\n\r\f,");
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int NextInt() {
            return Integer.parseInt(next());
        }

        public int[] NextIntArray(int n) {
            return NextIntArray(n, 0);
        }

        public int[] NextIntArray(int n, int offset) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = NextInt() + offset;
            }
            return a;
        }

    }

    static class Pair<T1, T2> {
        public T1 first;
        public T2 second;

        public Pair(T1 f, T2 s) {
            first = f;
            second = s;
        }

    }
}

import java.io.PrintWriter;
import java.util.*;

public class ARC103C {

    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    int[] even = new int[n/2];
    int[] odd = new int[n/2];

    HashMap<Integer, Integer> mapEven = new HashMap<>();
    HashMap<Integer, Integer> mapOdd = new HashMap<>();

    PrintWriter out = new PrintWriter(System.out);


    public static void main(String[] args) {
        new ARC103C().run();
    }

    void run() {
        for (int i=0; i<n; i++) {
            if (i%2==0) even[i/2] = sc.nextInt();
            if (i%2!=0) odd[i/2] = sc.nextInt();
        }

        int cnt = 0;
        for (int i=0; i<n/2; i++) {
            if (even[i]==odd[i]) cnt++;
        }

        if (cnt==n/2) {
            out.print(n/2);
            out.flush();
            return;
        }

        for (int i=0; i<n/2; i++) {
            if (!mapEven.containsKey(even[i])) {
                mapEven.put(even[i], 1);
            } else {
                int tmp = mapEven.get(even[i]);
                mapEven.put(even[i], tmp+1);
            }

            if (!mapOdd.containsKey(odd[i])) {
                mapOdd.put(odd[i], 1);
            } else {
                int tmp = mapOdd.get(odd[i]);
                mapOdd.put(odd[i], tmp+1);
            }
        }


        TreeMap<Integer, Integer> newmapEven = sortMapByValue(mapEven);
        TreeMap<Integer, Integer> newmapOdd = sortMapByValue(mapOdd);

//        out.println(newmapEven);
//        out.println(newmapOdd);



        Map.Entry<Integer, Integer> entryEven = newmapEven.entrySet().iterator().next();
        Map.Entry<Integer, Integer> entryOdd = newmapOdd.entrySet().iterator().next();

        if (entryEven.getKey()!=entryOdd.getKey()) {
            out.print(n-entryEven.getValue()-entryOdd.getValue());
        } else {
            if (n/2-entryEven.getValue() < n/2-entryOdd.getValue()) {
                newmapOdd.entrySet().iterator().next();
                Map.Entry<Integer, Integer> entryOddSecond = newmapOdd.entrySet().iterator().next();
                out.print(n-entryEven.getValue()-entryOddSecond.getValue());
            } else {
                newmapEven.entrySet().iterator().next();
                Map.Entry<Integer, Integer> entryEvenSecond = newmapEven.entrySet().iterator().next();
                out.print(n-entryOdd.getValue()-entryEvenSecond.getValue());
            }
        }

        out.flush();

    }

    public TreeMap<Integer, Integer> sortMapByValue(HashMap<Integer, Integer> map){
        Comparator<Integer> comparator = new ValueComparator(map);
        //TreeMap is a map sorted by its keys.
        //The comparator is used to sort the TreeMap by keys.
        TreeMap<Integer, Integer> result = new TreeMap<Integer, Integer>(comparator);
        result.putAll(map);
        return result;
    }

    class ValueComparator implements Comparator<Integer>{

        HashMap<Integer, Integer> map = new HashMap<Integer, Integer>();

        public ValueComparator(HashMap<Integer, Integer> map){
            this.map.putAll(map);
        }

        @Override
        public int compare(Integer s1, Integer s2) {
            if(map.get(s1) >= map.get(s2)){
                return -1;
            }else{
                return 1;
            }
        }
    }
}

