            {
                if(te.containsKey(a[i]))
                    te.put(a[i], te.get(a[i])+1);
                else
                    te.put(a[i], 1);
            }else{
                if(to.containsKey(a[i]))
                    to.put(a[i], to.get(a[i])+1);
                else
                    to.put(a[i], 1);
            }
        }
        int me=-1;
        int mo=-1;
