    static class InputReader {

        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new UnknownError();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new UnknownError();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int peek() {
            if (numChars == -1) {
                return -1;
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    return -1;
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar];
        }

        public void skip(int x) {
            while (x-- > 0) {
                read();
            }
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public String nextString() {
            return next();
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuffer res = new StringBuffer();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));

            return res.toString();
        }

        public String nextLine() {
            StringBuffer buf = new StringBuffer();
            int c = read();
            while (c != '\n' && c != -1) {
                if (c != '\r') {
                    buf.appendCodePoint(c);
                }
                c = read();
            }
            return buf.toString();
        }

        public double nextDouble() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            double res = 0;
            while (!isSpaceChar(c) && c != '.') {
                if (c == 'e' || c == 'E') {
                    return res * Math.pow(10, nextInt());
                }
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            }
            if (c == '.') {
                c = read();
                double m = 1;
                while (!isSpaceChar(c)) {
                    if (c == 'e' || c == 'E') {
                        return res * Math.pow(10, nextInt());
                    }
                    if (c < '0' || c > '9') {
                        throw new InputMismatchException();
                    }
                    m /= 10;
                    res += (c - '0') * m;
                    c = read();
                }
            }
            return res * sgn;
        }

        public boolean hasNext() {
            int value;
            while (isSpaceChar(value = peek()) && value != -1) {
                read();
            }
            return value != -1;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Map.Entry;
import java.util.Scanner;

public class Main {

  public static void main(String[] args) {

    Scanner sc = new Scanner(System.in);

    int N = Integer.parseInt(sc.next());

    Map<Integer, Integer> oMap = new HashMap<>();
    Map<Integer, Integer> eMap = new HashMap<>();

    for (int i = 0; i < N; i++) {
      int v = Integer.parseInt(sc.next());
      if (i % 2 == 0) {
        oMap.merge(v, 1, Integer::sum);
      } else {
        eMap.merge(v, 1, Integer::sum);
      }
    }

    List<Entry<Integer, Integer>> list_entries_o = new ArrayList<Entry<Integer, Integer>>(oMap.entrySet());
    Collections.sort(list_entries_o, new Comparator<Entry<Integer, Integer>>() {
      //compareを使用して値を比較する
      public int compare(Entry<Integer, Integer> obj1, Entry<Integer, Integer> obj2) {
        //降順
        return obj2.getValue().compareTo(obj1.getValue());
      }
    });

    List<Entry<Integer, Integer>> list_entries_e = new ArrayList<Entry<Integer, Integer>>(eMap.entrySet());
    Collections.sort(list_entries_e, new Comparator<Entry<Integer, Integer>>() {
      //compareを使用して値を比較する
      public int compare(Entry<Integer, Integer> obj1, Entry<Integer, Integer> obj2) {
        //降順
        return obj2.getValue().compareTo(obj1.getValue());
      }
    });

    int ans = 0;
    if (!list_entries_o.get(0).getKey().equals(list_entries_e.get(0).getKey())) {
      ans = N - list_entries_o.get(0).getValue() - list_entries_e.get(0).getValue();
    } else {
      int e = 0, o = 0;
      if (eMap.size() > 1) {
        e = list_entries_e.get(1).getValue();
      }
      if (oMap.size() > 1) {
        o = list_entries_o.get(1).getValue();
      }
      ans = Math.min(N - list_entries_o.get(0).getValue() - e, N - o - list_entries_e.get(0).getValue());
    }
    System.out.println(ans);
  }
}

