    private static int solution_2(int length, int[] seq) {
        int overflow = 0;
        int p1 = seq[0];
        int p2 = seq[1];

        for (int i = 2; i< seq.length; i++){
            if (p1 == p2){
                overflow++;
            }
            else if (i %2 == 0){
                if (seq[i] != p1)
                    overflow++;
                p1 = seq[i];
            }
            else if (i%2 != 0){
                if (seq[i] != p2)
                    overflow++;
            }
        }
        return overflow;
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main{

    public static void main(String[] args) {

        Scanner scan = new Scanner(System.in);

        int N = scan.nextInt();

        int[] M = new int[N];


        for(int i = 0; i < N ; i ++){
            M[i] = scan.nextInt();
        }

        scan.close();

        //1つあけて出現回数の多い数字二つを求める
        //

        List<Integer> numList = new ArrayList<Integer>();

        List<Integer> fstList = new ArrayList<Integer>();

        List<Integer> scdList = new ArrayList<Integer>();

        for(int i = 0; i < N ; i ++){


            numList.add(M[i]);

            if( 0 == (i % 2)){
                fstList.add(M[i]);
            }
            else{
                scdList.add(M[i]);
            }

        }


        int ans = 0;

        int fstMostNum = 0;
        int fstCnt = 0;
        int fstCntTemp = 0;


        for(int i =0; i < N/2 ; i++){
            //ループの最初でリストはリセット
            List<Integer> fstListTemp = new ArrayList<Integer>(fstList);
            fstCntTemp = 0;

            while(true){
                //数字の数を計算する。
                if(!(fstListTemp.remove(fstList.get(i)))){
                    break;
                }
                else{
                    //リストにまだ単語があればカウント＋
                    fstCntTemp++;

                    //最も出現した数字の更新
                    if(fstCnt <= fstCntTemp){
                        fstMostNum = numList.get(i);
                        fstCnt = fstCntTemp;
                    }
                }
            }
        }

        int scdMostNum = 0;
        int scdCnt = 0;
        int scdCntTemp = 0;

        for(int i =1; i < N/2 ; i++){
            //ループの最初でリストはリセット
            List<Integer> scdListTemp = new ArrayList<Integer>(scdList);
            scdCntTemp = 0;

            while(true){
                //数字の数を計算する。
                if(!(scdListTemp.remove(scdList.get(i)))){
                    break;
                }
                else{
                    //リストにまだ単語があればカウント＋
                    scdCntTemp++;

                    //最も出現した数字の更新
                    if(scdCnt <= scdCntTemp){
                        scdMostNum = numList.get(i);
                        scdCnt = scdCntTemp;
                    }
                }
            }
        }

        ans += (numList.size()/2 - fstCnt) + (numList.size()/2 - scdCnt);

        if(fstMostNum == scdMostNum){
            ans = numList.size()/2;
        }

        System.out.println(ans);

    }
}

