public class Main {
    public static void main(String[] args) {
        StringBuilder out = new StringBuilder();
        solve(out);
        PrintWriter pw = new PrintWriter(System.out);
        pw.println(out);
        pw.flush();
        pw.close();
    }

    public static void solve(StringBuilder out) {
        int n = In.ni();
        int[] v = In.ni(n);
        int[] ce = new int[100001];
        int[] co = new int[100001];
        int em = 0, om = 0;
        int emi = 0, omi = 0;
        for (int i = 0; i < n; i+= 2) {
            ce[v[i]]++;
            if (em < ce[v[i]]) {
                em = ce[v[i]];
                emi = v[i];
            }
        }
        for (int i = 1; i < n; i += 2) {
            co[v[i]]++;
            if (om < co[v[i]]) {
                om = co[v[i]];
                omi = v[i];
            }
        }
        if (emi != omi) {
            out.append(n - om - em);
            return;
        }
        int sem = 0, som = 0;
        for (int i = 0; i <= 100000; i++) {
            if (sem < ce[i] && i != emi) sem = ce[i];
        }
        for (int i = 0; i <= 100000; i++) {
            if (som < co[i] && i != omi) som = co[i];
        }
        out.append(n - Math.max(em + som, sem + om));
    }
}


