                p0.poll();
            else if (p0.peek().value>p1.peek().value)
                p1.poll();
            else
            {
                int max0 = p0.poll().value;
                int max1= p1.poll().value;
                if (p0.peek().value>=p1.peek().value)
                {
                    p0.add(new pair(0,max0));

                }
                else
                    p1.add(new pair(0,max1));
