/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author prakharjain
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        TaskA solver = new TaskA();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskA {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.nextInt();

            int[] a = new int[n];

            for (int i = 0; i < n; i++) {
                a[i] = in.nextInt();
            }

            Map<Integer, Integer> m1 = new HashMap<>();
            for (int i = 0; i < n; i += 2) {
                m1.merge(a[i], 1, (x, y) -> x + y);
            }

            Map<Integer, Integer> m2 = new HashMap<>();
            for (int i = 1; i < n; i += 2) {
                m2.merge(a[i], 1, (x, y) -> x + y);
            }

            List<num> l1 = new ArrayList<>();
            for (int key : m1.keySet()) {
                l1.add(new num(key, m1.get(key)));
            }

            List<num> l2 = new ArrayList<>();
            for (int key : m2.keySet()) {
                l2.add(new num(key, m2.get(key)));
            }

            l1.sort((n1, n2) -> n2.cnt - n1.cnt);

            l2.sort((n1, n2) -> n2.cnt - n1.cnt);


            num num00 = l1.get(0);
            num num01 = l2.get(0);

            int ans = n - 2;
            if (num00.num != num01.num) {
                ans = n - num00.cnt - num01.cnt;
            } else {
                if (l2.size() >= 2)
                    ans = Math.min(n - num00.cnt - (l2.size() >= 2 ? l2.get(1).cnt : 1), ans);
                if (l1.size() >= 2)
                    ans = Math.min(ans, n - (l1.size() >= 2 ? l1.get(1).cnt : 1) - num01.cnt);
            }

            out.println(ans);
        }

        class num {
            int num;
            int cnt;

            public num(int num, int cnt) {
                this.num = num;
