		int max = -1;
		for (int val : map.keySet()) {
			if (max == -1) {
				max = val;
			} else if (map.get(max) < map.get(val)) {
				max = val;
			}
		}
		return max;
	}

	public static int getSecond(Map<Integer, Integer> map) {
		int[] arr = new int[map.size()];
		int idx = 0;
		for (int val : map.keySet()) {
			arr[idx++] = val;
		}
		Arrays.sort(arr);
		int sec = arr[1];
		int ans = 0;
		for (int val : map.keySet()) {
			if (sec == map.get(val)) {
				ans = val;
