				ans = val;
			} else if (map.get(ans) < map.get(val)) {
				ans = val;
			}
		}
		return ans;
	}

	public static int countChange(int max, Map<Integer, Integer> map) {
		int ans = 0;
		for (int val : map.keySet()) {
			if (max == val) {
				continue;
			}
			ans += map.get(val);
		}
		return ans;
	}

	public static int getSecondVal(Map<Integer, Integer> map, int max) {
		int[] arr = new int[map.size()];
		int idx = 0;
		for (int val : map.keySet()) {
			arr[idx++] = map.get(val);
		}
		Arrays.sort(arr);
