        PriorityQueue<pair> p0 = new PriorityQueue<>();
        PriorityQueue<pair> p1 = new PriorityQueue<>();
        for (int i =0;i<100001;i++)
        {
            p0.add(new pair(i,-nums0[i]));
            p1.add(new pair(i,-nums1[i]));
        }
         if (p0.peek().key==p1.peek().key)
         {
             if (p0.peek().value<=p1.peek().value)
                 p0.poll();
             else
                 p1.poll();
         }
         int ans = (n/2)+p0.poll().value;
        ans+=(n/2)+p1.poll().value;
        out.printLine(ans);
        out.flush();
    }
    static void MergeSort(int[] a,   int p, int r)
    {
        if (p < r)
        {
            int q = (r + p) / 2;
            MergeSort(a,   p, q);
            MergeSort(a,   q + 1, r);
            Merge(a, p, q, r);
        }
    }
    static void Merge(int[] a,int p, int q, int r)
    {
        int n1 = q - p + 1;
        int n2 = r - q;
        int[] R = new int[n1 + 1];
        int[] L = new int[n2 + 1];
        for (int i = 0; i < n1; i++)
        {
            R[i] = a[p + i];

        }
        R[n1] = Integer.MAX_VALUE;
        for (int i = 0; i < n2; i++)
        {
            L[i] = a[q + i + 1];


        }
        L[n2] =Integer.MAX_VALUE;
        int n = a.length;
        int j = 0;
        int k = 0;
        for (int i = p; i <= r; i++)
        {
            if (L[j] < R[k])
            {
                a[i] = L[j];


                j++;
            }
            else
            {
                a[i] = R[k];


                k++;
            }

        }
    }

