	public void run() throws Exception {
		FastIO file = new FastIO();
		TreeSet<Integer> a = new TreeSet<>();
		TreeSet<Integer> b = new TreeSet<>();
		int n = file.nextInt();
		int[] c = new int[n];
		for (int i = 0; i < n; i++) {
			c[i] = file.nextInt();
			if (i % 2 == 0) a.add(c[i]);
