	public int gcd(int a, int b) {
		if (a == 0) {
			return b;	
		}
		return gcd(b % a, a);
	}

	public void solve() {
		int n = in.nextInt();
		int[] v = new int[n];
		for (int i = 0; i < v.length; i++) {
			v[i] = in.nextInt() - 1;
		}
		int[] n0 = new int[100000];
		int[] n1 = new int[100000];
		for (int i = 0; i < v.length; i += 2) {
			n0[v[i]]++;
			n1[v[i + 1]]++;
		}
		int m01 = 0;
		int x01 = -1;
		int m02 = 0;
		int x02 = -1;
		int m11 = 0;
		int x11 = -1;
		int m12 = 0;
		int x12 = -1;
		for (int i = 0; i < n0.length; i++) {
			if (n0[i] > m01) {
				m02 = m01;
				x02 = x01;
				x01 = i;
				m01 = n0[i];
			} else if (n0[i] > m02) {
				m02 = n0[i];
				x02 = i;
			}
			if (n1[i] > m11) {
				m12 = m11;
				x12 = x11;
				x11 = i;
				m11 = n1[i];
			} else if (n1[i] > m12) {
				m12 = n1[i];
				x12 = i;
			}
		}
//		System.out.println(x01 + " " + m01 + " " + x02 + " ");
		int ans = n / 2;
		if (x01 != x11) {
			ans = Math.min(ans, n - m01 - m11);
		}
		if (x01 != x12) {
			ans = Math.min(ans, n - m01 - m12);
		}
		if (x02 != x11) {
			ans = Math.min(ans, n - m02 - m11);
		}
		if (x02 != x12) {
			ans = Math.min(ans, n - m02 - m12);
		}
		out.println(ans);
	}

	public void run() {
		try {
			if (systemIO) {
				in = new FastScanner(System.in);
				out = new PrintWriter(System.out);
			} else {
				in = new FastScanner(new File("input.txt"));
				out = new PrintWriter(new File("output.txt"));
