        int aMax = 0;
        int aMax2 = 0;
        int bMax = 0;
        int bMax2 = 0;

        for (int i = 0; i < n; ++i) {
            int current = scanner.nextInt();
            if (i % 2 == 0) {
                int count = a.getOrDefault(current, 0) + 1;
                a.put(current, count);
                if (count >= aMaxCount) {
                    aMax2Count = aMaxCount;
                    aMax2 = aMax;
                    aMaxCount = count;
                    aMax = current;
                } else if (count >= aMax2Count && count < aMaxCount) {
                    aMax2Count = count;
                    aMax2 = current;
                }
            } else {
                int count = b.getOrDefault(current, 0) + 1;
                b.put(current, count);
                if (count >= bMaxCount) {
                    bMax2Count = bMaxCount;
                    bMax2 = bMax;
                    bMaxCount = count;
                    bMax = current;
                } else if (count >= bMax2Count && count < bMaxCount) {
                    bMax2Count = count;
                    bMax2 = current;
                }
            }
