        for(int i=0;i<n;i+=2) {
            int a = arr[i];
            map1.put(a, map1.getOrDefault(a, 0) + 1);
        }
        for(int i=1;i<n;i+=2) {
            int a = arr[i];
            map2.put(a, map2.getOrDefault(a, 0) + 1);
        }

        int modeA1 = 0, modeA2 = 0, modeB1 = 0, modeB2 = 0;
        int ans1A = 0, ans1B = 0, ans2A = 0, ans2B = 0;

        for(int i : map1.keySet()) {
            int val = map1.get(i);
            if(val > modeA1) {
                modeA2 = modeA1;
                modeA1 = val;
                ans1A = i;
            }
            else if(val > modeA2) {
                modeA2 = val;
                ans1B = i;
            }
        }
        for(int i : map2.keySet()) {
            int val = map2.get(i);
            if(val > modeB1) {
                modeB2 = modeB1;
                modeB1 = val;
                ans2A = i;
