import java.util.*;

public class Main {

  static Scanner sc = new Scanner(System.in);

  static int N;

  public static void main(String[] args) {

    int n = sc.nextInt();
    N = n/2;

    ArrayList<Integer> a = new ArrayList(N);
    ArrayList<Integer> b = new ArrayList(N);

    for (int i=0; i<N; i++) {
      a.add(sc.nextInt());
      b.add(sc.nextInt());
    }

    ArrayList<Integer[]> rankingA = getRanking(a); //[0] 個数 [1] 数値
    ArrayList<Integer[]> rankingB = getRanking(b);

    if (!rankingA.get(0)[1].equals(rankingB.get(0)[1])) {
      System.out.println(2 * N - rankingA.get(0)[0] - rankingB.get(0)[0]);
    } else {
      System.out.println(2 * N - Math.max(
              rankingA.get(0)[0] + rankingB.get(1)[0],
              rankingA.get(1)[0] + rankingB.get(0)[0]
      ));
    }

  }

  static ArrayList<Integer[]> getRanking(ArrayList<Integer> list) {
    ArrayList<Integer[]> ranking = new ArrayList(N);

    list.sort(null);

    for (int i=0; i<N;) {
      for (int j=i+1; j<=N; j++) {
        if (j == N || list.get(j) != list.get(i)) {
          ranking.add(new Integer[]{j-i, list.get(i)});
          i = j;
          break;
        }
      }
    }

    ranking.sort((x, y) -> y[0]-x[0]);

    if (ranking.size() == 1) {
      ranking.add(new Integer[]{0, -1});
    }

    return ranking;
  }

}

import java.util.Scanner;

public class Main {

	public static void main(String[] args) {

		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		int[] a = new int[n / 2];
		int[] b = new int[n / 2];

		//配列vの奇数行・偶数行を2つの配列a,bに分ける。(O(N))
		for (int i = 0; i < n / 2; i++) {
			a[i] = sc.nextInt();
			b[i] = sc.nextInt();
		}

		//a,bそれぞれについて、値が出現した回数を配列s,tでカウントする。(O(2 * 10^5))
		int[] s = new int[100_005];
		int[] t = new int[100_005];

		for (int i = 0; i < n / 2; i++) {
			s[a[i]]++;
			t[b[i]]++;
		}


		//ans = n - (sの最大値) - (tの最大値) (O(2 * 10^5))
		int ms = 0;
	    int mt = 0;
	    int sms = 0;
		int smt = 0;

	    int ma = 0;
	    int mb = 0;
	    int sma = 1;
	    int smb = 1;
		for (int i = 0 ; i < 100_005; i++) {
			if (s[i] > ms) {
				sms = ms;
				ms = s[i];

				sma = ma;
				ma = i;
			}
			if (t[i] > mt) {
				smt = mt;
				mt = t[i];

				smb = mb;
				mb = i;
			}
		}

		//ms,mtをとるiの値が一致するとき、sとtのセカンドmaxをms,mtとして、
		//最小化のansを求める。
		int ans = 0;
		if (ma != mb) {
			ans = n - ms - mt;
		} else {
			ans = Math.min(n - ms - smt, n - sms - mt);
		}

		System.out.println(ans);

	}

}

