public class Main {
	static InputStream is;
	static PrintWriter out;
	static String INPUT = "";

	static void solve()
	{
		int n = ni();
		int[] a = na(n);
		Map<Integer, Integer> map0 = new HashMap<>();
		Map<Integer, Integer> map1 = new HashMap<>();
		for(int i = 0;i < n;i++){
			if(i % 2 == 0){
				map0.put(a[i], map0.getOrDefault(a[i], 0) + 1);
			}else{
				map1.put(a[i], map1.getOrDefault(a[i], 0) + 1);
			}
		}
		int[] b = go(map0);
		int[] c = go(map1);
		if(b[1] != c[1]){
			out.println(n- (b[0] + c[0]));
		}else{
			out.println(n- Math.max(b[0] + c[2], b[2] + c[0]));
		}
	}

	static int[] go(Map<Integer, Integer> map0)
	{
		int max0 = 0;
		int arg0 = -1;
		int max02 = 0;
		int arg02 = -1;
		for(int v : map0.keySet()){
			if(map0.get(v) > max0){
				max02 = max0;
				max0 = map0.get(v);
				arg02 = arg0;
				arg0 = v;
			}else if(map0.get(v) > max02){
				max02 = map0.get(v);
				arg02 = v;
			}
		}
		return new int[]{max0, arg0, max02, arg02};
	}

	public static void main(String[] args) throws Exception
	{
		long S = System.currentTimeMillis();
		is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
		out = new PrintWriter(System.out);

		solve();
		out.flush();
		long G = System.currentTimeMillis();
		tr(G-S+"ms");
	}

	private static boolean eof()
	{
		if(lenbuf == -1)return true;
		int lptr = ptrbuf;
		while(lptr < lenbuf)if(!isSpaceChar(inbuf[lptr++]))return false;

		try {
			is.mark(1000);
			while(true){
				int b = is.read();
				if(b == -1){
					is.reset();
					return true;
				}else if(!isSpaceChar(b)){
					is.reset();
					return false;
				}
			}
		} catch (IOException e) {
			return true;
		}
	}

	private static byte[] inbuf = new byte[1024];
	static int lenbuf = 0, ptrbuf = 0;

	private static int readByte()
	{
		if(lenbuf == -1)throw new InputMismatchException();
		if(ptrbuf >= lenbuf){
			ptrbuf = 0;
			try { lenbuf = is.read(inbuf); } catch (IOException e) { throw new InputMismatchException(); }
			if(lenbuf <= 0)return -1;
		}
		return inbuf[ptrbuf++];
	}

	private static boolean isSpaceChar(int c) { return !(c >= 33 && c <= 126); }
//	private static boolean isSpaceChar(int c) { return !(c >= 32 && c <= 126); }
	private static int skip() { int b; while((b = readByte()) != -1 && isSpaceChar(b)); return b; }

	private static double nd() { return Double.parseDouble(ns()); }
	private static char nc() { return (char)skip(); }

	private static String ns()
	{
		int b = skip();
		StringBuilder sb = new StringBuilder();
		while(!(isSpaceChar(b))){
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}

	private static char[] ns(int n)
	{
		char[] buf = new char[n];
		int b = skip(), p = 0;
		while(p < n && !(isSpaceChar(b))){
			buf[p++] = (char)b;
			b = readByte();
		}
		return n == p ? buf : Arrays.copyOf(buf, p);
	}

	private static char[][] nm(int n, int m)
	{
		char[][] map = new char[n][];
		for(int i = 0;i < n;i++)map[i] = ns(m);
		return map;
	}

	private static int[] na(int n)
	{
		int[] a = new int[n];
		for(int i = 0;i < n;i++)a[i] = ni();
		return a;
	}

	private static int ni()
	{
		int num = 0, b;
		boolean minus = false;
		while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
		if(b == '-'){
			minus = true;
			b = readByte();
		}

		while(true){
			if(b >= '0' && b <= '9'){
				num = num * 10 + (b - '0');
			}else{
				return minus ? -num : num;
			}
			b = readByte();
		}
	}

	private static long nl()
	{
		long num = 0;
		int b;
		boolean minus = false;
		while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
		if(b == '-'){
			minus = true;
			b = readByte();
		}

		while(true){
			if(b >= '0' && b <= '9'){
				num = num * 10 + (b - '0');
			}else{
				return minus ? -num : num;
			}
			b = readByte();
		}
	}

	private static void tr(Object... o) { if(INPUT.length() != 0)System.out.println(Arrays.deepToString(o)); }
}

import java.io.PrintWriter;
import java.util.*;

public class Main {

    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    int[] even = new int[n/2];
    int[] odd = new int[n/2];

    HashMap<Integer, Integer> mapEven = new HashMap<>();
    HashMap<Integer, Integer> mapOdd = new HashMap<>();

    PrintWriter out = new PrintWriter(System.out);


    public static void main(String[] args) {
        new Main().run();
    }

    void run() {
        for (int i=0; i<n; i++) {
            if (i%2==0) even[i/2] = sc.nextInt();
            if (i%2!=0) odd[i/2] = sc.nextInt();
        }

        int cnt = 0;
        for (int i=0; i<n/2; i++) {
            if (even[i]==odd[i]) cnt++;
        }

        if (cnt==n/2) {
            out.print(n/2);
            out.flush();
            return;
        }

        for (int i=0; i<n/2; i++) {
            if (!mapEven.containsKey(even[i])) {
                mapEven.put(even[i], 1);
            } else {
                int tmp = mapEven.get(even[i]);
                mapEven.put(even[i], tmp+1);
            }

            if (!mapOdd.containsKey(odd[i])) {
                mapOdd.put(odd[i], 1);
            } else {
                int tmp = mapOdd.get(odd[i]);
                mapOdd.put(odd[i], tmp+1);
            }
        }


        TreeMap<Integer, Integer> newmapEven = sortMapByValue(mapEven);
        TreeMap<Integer, Integer> newmapOdd = sortMapByValue(mapOdd);

//        out.println(newmapEven);
//        out.println(newmapOdd);



        Map.Entry<Integer, Integer> entryEven = newmapEven.entrySet().iterator().next();
        Map.Entry<Integer, Integer> entryOdd = newmapOdd.entrySet().iterator().next();

        if (entryEven.getKey()!=entryOdd.getKey()) {
            out.print(n-entryEven.getValue()-entryOdd.getValue());
        } else {
            if (n/2-entryEven.getValue() < n/2-entryOdd.getValue()) {
                newmapOdd.entrySet().iterator().next();
                Map.Entry<Integer, Integer> entryOddSecond = newmapOdd.entrySet().iterator().next();
                out.print(n-entryEven.getValue()-entryOddSecond.getValue());
            } else {
                newmapEven.entrySet().iterator().next();
                Map.Entry<Integer, Integer> entryEvenSecond = newmapEven.entrySet().iterator().next();
                out.print(n-entryOdd.getValue()-entryEvenSecond.getValue());
            }
        }

        out.flush();

    }

    public TreeMap<Integer, Integer> sortMapByValue(HashMap<Integer, Integer> map){
        Comparator<Integer> comparator = new ValueComparator(map);
        //TreeMap is a map sorted by its keys.
        //The comparator is used to sort the TreeMap by keys.
        TreeMap<Integer, Integer> result = new TreeMap<Integer, Integer>(comparator);
        result.putAll(map);
        return result;
    }

    class ValueComparator implements Comparator<Integer>{

        HashMap<Integer, Integer> map = new HashMap<Integer, Integer>();

        public ValueComparator(HashMap<Integer, Integer> map){
            this.map.putAll(map);
        }

        @Override
        public int compare(Integer s1, Integer s2) {
            if(map.get(s1) >= map.get(s2)){
                return -1;
            }else{
                return 1;
            }
        }
    }
}

