		for (int i = 0; i < n / 2; i++) {
			s[a[i]]++;
			t[b[i]]++;
		}


		//ans = n - (sの最大値) - (tの最大値) (O(2 * 10^5))
		int ms = 0;
	    int mt = 0;
	    int sms = 0;
		int smt = 0;

	    int ma = 0;
	    int mb = 0;
	    int sma = 0;
	    int smb = 0;
		for (int i = 0 ; i < 100_005; i++) {
			if (s[i] > ms) {
				sms = ms;
				ms = s[i];

				sma = ma;
				ma = i;
			}
			if (t[i] > mt) {
				smt = mt;
				mt = t[i];

				smb = mb;
				mb = i;
			}
		}

		//ms,mtをとるiの値が一致するとき、sとtのセカンドmaxをms,mtとして、
		//最小化のansを求める。
		int ans = 0;
		if (ma != mb) {
			ans = n - ms - mt;
		} else {
			ans = Math.min(n - ms - smt, n - sms - mt);
		}

		System.out.println(ans);

	}

}

