            if (p1 == p2){
                overflow++;
            }
            else if (i %2 == 0){
                if (seq[i] != p1)
                    overflow++;
                p1 = seq[i];
            }
            else if (i%2 != 0){
                if (seq[i] != p2)
                    overflow++;
            }
        }
        return overflow;
    }

