			o.remove(O.getKey());
			e.remove(E.getKey());
			Entry<Integer,Integer> O2=o.entrySet().stream().max(c).orElse(null);
			Entry<Integer,Integer> E2=e.entrySet().stream().max(c).orElse(null);
			r=Math.max(
					O.getValue()+(E2==null?0:E2.getValue()),
					E.getValue()+(O2==null?0:O2.getValue())
					);
