import java.util.*;

public class Main {

  static Scanner sc = new Scanner(System.in);

  static int N;

  public static void main(String[] args) {

    int n = sc.nextInt();
    N = n/2;

    ArrayList<Integer> a = new ArrayList(N);
    ArrayList<Integer> b = new ArrayList(N);

    for (int i=0; i<N; i++) {
      a.add(sc.nextInt());
      b.add(sc.nextInt());
    }

    ArrayList<Integer[]> rankingA = getRanking(a); //[0] 個数 [1] 数値
    ArrayList<Integer[]> rankingB = getRanking(b);

    if (rankingA.get(0)[1] != rankingB.get(0)[1]) {
      System.out.println(2 * N - rankingA.get(0)[0] - rankingB.get(0)[0]);
    } else {
      System.out.println(2 * N - Math.max(
              rankingA.get(0)[0] + rankingB.get(1)[0],
              rankingA.get(1)[0] + rankingB.get(0)[0]
      ));
    }

  }

  static ArrayList<Integer[]> getRanking(ArrayList<Integer> list) {
    ArrayList<Integer[]> ranking = new ArrayList(N);
    for (int i=0; i<N;) {
      for (int j=i+1; j<=N; j++) {
        if (j == N || list.get(j) != list.get(i)) {
          ranking.add(new Integer[]{j-i, list.get(i)});
          i = j - 1;
          break;
        }
      }
    }

    ranking.sort((x, y) -> y[0]-x[0]);

    if (ranking.size() == 1) {
      ranking.add(new Integer[]{0, -1});
    }

    return ranking;
  }

}

import java.util.Scanner;

public class Main {
    /**
     * @param args
     */
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] v = new int[n];
        for (int i=0; i<n; i++) {
            v[i] = sc.nextInt();
        }

        int ans = solve(n, v);

        System.out.println(ans);
    }

    private static int solve(int n, int[] v) {
        int[] hist = new int[100_001];
        int count = 0;

        for (int i = 0; i < n; i += 2) {
            hist[v[i]]++;
        }
        int[][] ans1 = top(hist);

        hist = new int[100_001];
        for (int i = 1; i < n; i += 2) {
            hist[v[i]]++;
        }
        int[][] ans2 = top(hist);

//        System.err.println(ans1[0][0] + "," + ans1[0][1] + " / " + ans1[1][0] + "," + ans1[1][1]);
//        System.err.println(ans2[0][0] + "," + ans2[0][1] + " / " + ans2[1][0] + "," + ans2[1][1]);

        if (ans1[0][1] != ans2[0][1]) {
            count = n - ans1[0][0] - ans2[0][0];
        } else {
            if (ans1[0][0] > ans2[0][0]) {
                count = n - ans1[0][0] - ans2[1][0];
            } else {
                count = n - ans1[1][0] - ans2[0][0];
            }
        }

        return count;
    }

    private static int[][] top(int[] hist) {
        int[][] ans = new int[2][2];
        for (int i=0; i<hist.length; i++) {
            if (hist[i] > 0) {
              if (hist[i] >= ans[0][0]) {
                  ans[1][0] = ans[0][0];
                  ans[1][1] = ans[0][1];

                  ans[0][0] = hist[i];
                  ans[0][1] = i;
              } else if (hist[i] > ans[1][0]) {
                  ans[1][0] = hist[i];
                  ans[1][1] = i;
              }
            }
        }

        return ans;
    }
}

