using System;
using System.Collections.Generic;
using System.Linq;

namespace ABC111_C
{
    class Program
    {
        static void Main(string[] args)
        {
            var n = long.Parse(Console.ReadLine());
            var v = Console.ReadLine().Split().Select(long.Parse).ToArray();

            if (v.Distinct().Count() == 1)
            {
                Console.WriteLine(n / 2);
                return;
            }

            var ve = new Dictionary<long, long>();
            var vo = new Dictionary<long, long>();

            for (long i = 0; i < v.Length; i++)
            {
                if (i % 2 == 0 || i == 0)
                {
                    if (ve.Keys.Contains(v[i])) ve[v[i]]++;
                    else ve.Add(v[i], 1);
                }
                else
                {
                    if (vo.Keys.Contains(v[i])) vo[v[i]]++;
                    else vo.Add(v[i], 1);
                }
            }

            var veMost = ve.OrderByDescending(x => x.Value).ToList();
            var voMost = vo.OrderByDescending(x => x.Value).ToList();

            var veTop = veMost[0].Key;
            var voTop = voMost[0].Key;

            if (veTop==voTop)
            {
                if (veMost[0].Value > voMost[0].Value) voTop = voMost[1].Key;
                else if (veMost[0].Value < voMost[0].Value) veTop = veMost[1].Key;
                else
                {
                    if (veMost[1].Value < voMost[1].Value) voTop = voMost[1].Key;
                    else veTop = veMost[1].Key;
                }
            }

            ve.Remove(veTop);
            vo.Remove(voTop);

            var cntve = ve.Select(x => x.Value).Sum();
            var cntvo = vo.Select(x => x.Value).Sum();

            Console.WriteLine(cntve + cntvo);
        }
    }
}

