namespace SummerVacation
{
    class Program
    {
        static void Main(string[] args)
        {
            Console.ReadLine();
            string[] tmpstr=Regex.Split(Console.ReadLine(), @"\s+");

            Hashtable ht1 = new Hashtable();
            Hashtable ht2 = new Hashtable();

            for (int i = 0; i < tmpstr.Length; i += 2)
            {
                HashTableMake(ref ht1, tmpstr[i]);
                HashTableMake(ref ht2, tmpstr[i + 1]);   
            }

            while (true)
            {
                int Topnum = 0, Topnum2 = 0;
                string Indexnum = "", Indexnum2 = "";
                int tmpht1 = 0, tmpht2 = 0;
                bool flag;

                HaTa(ref ht1, ref Topnum, ref Indexnum, ref tmpht1);
                HaTa(ref ht2, ref Topnum2, ref Indexnum2, ref tmpht2);

                if (!(Indexnum == Indexnum2))
                {
                    Console.WriteLine(tmpstr.Length - Topnum - Topnum2);
                    break;
                }
                else
                {
                    if (tmpht1 == 0 && tmpht2 == 0)
                    {
                        Console.WriteLine(tmpstr.Length / 2);
                        break;
                    }
                    else if (Topnum+tmpht2 > Topnum2 + tmpht1 || tmpht1==0)
                    {
                        flag = true;
                    }
                    else if (Topnum + tmpht2 < Topnum2 + tmpht1 || tmpht2==0)
                    {
                        flag = false;
                    }
                    else
                    { 
                        if (tmpht1 > tmpht2)
                            flag = false;
                        else if (tmpht1 == tmpht2)
                        {
                            if (Topnum > Topnum2)
                                flag = false;
                            else
                                flag = true;
                        }
                        else
                            flag = true;
                    }
                }
                if (flag)
                    ht2.Remove(Indexnum2);
                else
                    ht1.Remove(Indexnum);
            }
        }

        public static void HaTa(ref Hashtable ht1, ref int Topnum,ref string Indexnum,ref int tmpht1)
        {
            foreach (DictionaryEntry x in ht1)
            {
                if (Topnum < (int)x.Value)
                    tmpht1 = Topnum;
                    Topnum = (int)x.Value;
                    Indexnum = (string)x.Key;
            }
        }

        public static void HashTableMake(ref Hashtable ht,string tmpstr)
        {
            if (ht.ContainsKey(tmpstr))
                ht[tmpstr] = (int)ht[tmpstr] + 1;
            else
                ht[tmpstr] = 1;
        }
    }
}

