            odd = new Dictionary<int,int>(); 
            even = new Dictionary<int,int>(); 
            for(int i=0;i<n/2;i++){
                var e = array[2*i];
                var o = array[2*i+1];
                if(even.ContainsKey(e))
                    even[e] = even[e]+1;
                else
                    even.Add(array[2*i], 1);
                if(odd.ContainsKey(o))
                    odd[o] = odd[o] + 1;
                else
                    odd.Add(array[2*i+1], 1);
            }
            var odd2 = odd.OrderByDescending(x=>x.Value).ToArray();
            var even2 = even.OrderByDescending(x=>x.Value).ToArray();
            if(odd2[0].Key == even2[0].Key){
                if(odd2.Count() == 1 && even2.Count() == 1){
