namespace ARC103C
{
    class Program
    {
        static void Solve()
        {
            var n = Input.NextInt();
            var v = Input.NextInt(n);

            // 奇数か偶数番目の内でそれぞれ一番使用されている数を採用する
            var vodd = v
                .Select((x, i) => new { Value = x, Index = i })
                .Where(x => (x.Index) % 2 != 0)
                .ToList();
            var voddMax = vodd
                .GroupBy(x => x.Value)
                .Select(x => new { Key = x.Key, Count = x.Count() })
                .OrderByDescending(x => x.Count)
                .ToArray();

            var veven = v
                .Select((x, i) => new { Value = x, Index = i })
                .Where(x => (x.Index % 2) == 0)
                .ToList();
            var vevenMax = veven
                .GroupBy(x => x.Value)
                .Select(x => new { Key = x.Key, Count = x.Count() })
                .OrderByDescending(x => x.Count)
                .ToArray();

            if (n == 2)
            {
                if (v[0] == v[1])
                {
                    Console.WriteLine(1);
                }
                else
                {
                    Console.WriteLine(0);
                }
                return;
            }

            // 最大値がかぶっていたなら、次の値が大きい方を変える
            if (voddMax[0].Key == vevenMax[0].Key)
            {
                var vodd2 = voddMax.Count() > 1 ? voddMax[1].Count : 0;
                var veven2 = vevenMax.Count() > 1 ? vevenMax[1].Count : 0;

                if (veven2 < vodd2)
                {
                    // evenの方が2個目の数が小さいので、evenをそのまま採用する
                    Console.WriteLine(vodd.Count() - vodd2
                        + veven.Count() - vevenMax[0].Count);
                }
                else
                {
                    // oddの方をそのまま採用する
                    // 2個目のカウントが同じ場合はどっちでもよい
                    Console.WriteLine(vodd.Count() - voddMax[0].Count
                        + veven.Count() - veven2);
                }
            }
            else
            {
                Console.WriteLine(vodd.Count() - voddMax[0].Count
                    + veven.Count() - vevenMax[0].Count);
            }
        }

        #region Competitive Template
        public static void Main(string[] args)
        {
            var needsFlushOutput = true;
            if (needsFlushOutput)
            {
                // 細かく出力しないようにする
                var sw = new System.IO.StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
                Console.SetOut(sw);
            }

            // 仮想的に標準入力をセットする
            // NextLine系を使っていると使えない
            //Input.SetText("");

            Solve();

            Console.Out.Flush();
        }

        static class Input
        {
            static char[] separator = { ' ' };
            public static bool IsEof { get; set; }
            static Queue<string> q { get; set; }

            static Input()
            {
                IsEof = false;
                q = new Queue<string>();
            }

            /// <summary>
            /// 入力予約
            /// </summary>
            /// <param name="items"></param>
            public static void SetText(IEnumerable<string> items)
            {
                foreach (var item in items)
                {
                    SetText(item);
                }
            }

            /// <summary>
            /// 入力予約
            /// </summary>
            /// <param name="s"></param>
            /// <returns></returns>
            public static bool SetText(string s)
            {
                if (s == null) return false;

                foreach (var elem in s.Trim().Split(separator, StringSplitOptions.RemoveEmptyEntries))
                {
                    q.Enqueue(elem);
                }

                return true;
            }

            /// <summary>
            /// 内部queueに入力からの値をsplitして格納する
            /// </summary>
            /// <returns></returns>
            static bool read()
            {
                var s = Console.ReadLine();
                if (s == null) return false;

                foreach (var elem in s.Trim().Split(separator, StringSplitOptions.RemoveEmptyEntries))
                {
                    q.Enqueue(elem);
                }

                if (!q.Any()) return read();

                return true;
            }

            /// <summary>
            /// 次のstringを一つ読み込む
            /// </summary>
            /// <returns></returns>
            public static string Next()
            {
                if (!q.Any())
                {
                    if (!read())
                    {
                        IsEof = true;
                        return "";
                    }
                }

                return q.Dequeue();
            }

            public static int NextInt() => int.Parse(Next());
            public static long NextLong() => long.Parse(Next());
            public static double NextDouble() => double.Parse(Next());

            public static List<string> Next(int n) => Enumerable.Range(0, n).Select(_ => Next()).ToList();
            public static List<int> NextInt(int n) => Next(n).Select(x => int.Parse(x)).ToList();
            public static List<long> NextLong(int n) => Next(n).Select(x => long.Parse(x)).ToList();
            public static List<double> NextDouble(int n) => Next(n).Select(x => double.Parse(x)).ToList();

            public static List<string> NextLine() => Console.ReadLine().Trim().Split(separator, StringSplitOptions.RemoveEmptyEntries).ToList();
            public static List<int> NextIntLine() => NextLine().Select(x => int.Parse(x)).ToList();
            public static List<long> NextLongLine() => NextLine().Select(x => long.Parse(x)).ToList();
            public static List<double> NextDoubleLine() => NextLine().Select(x => double.Parse(x)).ToList();
        }
        #endregion
    }
}

