			for (int i = 0; i < n; i++)
			{
				if (i % 2 == 0)
				{
					if (sd1.ContainsKey(v[i])) sd1[v[i]]++;
					else sd1.Add(v[i], 1);
				}
				else
				{
					if (sd2.ContainsKey(v[i])) sd2[v[i]]++;
					else sd2.Add(v[i], 1);
				}
			}
			var pq1 = new PriorityQueue<(int Key, int Value)>(new ReverseComparer<(int key, int value)>(Comparer<(int key, int value)>.Default));
			var pq2 = new PriorityQueue<(int Key, int Value)>(new ReverseComparer<(int key, int value)>(Comparer<(int key, int value)>.Default));

			foreach (var e in sd1)
			{
				pq1.Enqueue((e.Value, e.Key));
			}
			foreach (var e in sd2)
			{
				pq2.Enqueue((e.Value, e.Key));
			}
			if (pq1.Peek.Value != pq2.Peek.Value) Console.WriteLine(n - pq1.Peek.Key - pq1.Peek.Key);
			else
			{
				if (pq1.Count == 1 && pq2.Count == 1) Console.WriteLine(n / 2);
				else
				{
					var pq10 = pq1.Dequeue().Key;
					var pq20 = pq2.Dequeue().Key;
					var ans = n - pq10 - pq2.Peek.Key;
					Chmin(ref ans, n - pq20 - pq1.Peek.Key);
					Console.WriteLine(ans);
				}
			}
		}

		class ReverseComparer<T> : IComparer<T>
		{
			private IComparer<T> comparer;

			public ReverseComparer(IComparer<T> comparer)
			{
				this.comparer = comparer;
			}

			public int Compare(T x, T y)
			{
				// 指定する引数の順序を逆にすることで、元になったIComparer<T>とは逆の結果を返す
				return comparer.Compare(y, x);
			}
		}

