class quiz
{
    public int solve(int n, int[] v)
    {
        int[] odd = new int[100000 + 1];
        int[] even = new int[100000 + 1];
        int[] no = new int[100000 + 1];
        int[] ne = new int[100000 + 1];

        for (int i = 0; i < n / 2; i++)
        {
            odd[v[2 * i]]++;
            even[v[2 * i + 1]]++;
        }

        for (int i = 0; i < 100000 + 1; i++)
        {
            no[i] = i;
            ne[i] = i;
        }

        Array.Sort(odd, no);
        Array.Sort(even, ne);

        if (no[100000] != ne[100000])
            return n - odd[100000] - even[100000];
        if (odd[100000] + even[99999] >= odd[99999] + even[100000])
            return n - odd[100000] - even[99999];
        else
            return n - odd[99999] - even[100000];
    }

    public int[] ParseIntBySpace(string str)
    {
        int[] array = new int[str.Length];
        int lastloc = 0, spaceloc = -1;

        for (int i = 0; i < str.Length; i++)
        {
            if (str[i] == ' ')
            {
                array[lastloc++] = int.Parse(str.Substring(spaceloc + 1, i - spaceloc - 1));
                spaceloc = i;
            }
            else if (i == str.Length - 1)
            {
                array[lastloc++] = int.Parse(str.Substring(spaceloc + 1, i - spaceloc));
            }
        }

        Array.Resize(ref array, lastloc);

        return array;
    }
}

