                    evens[vs[i]]++;
                else
                    evens.Add(vs[i], 1);
                if (odds.ContainsKey(vs[i + 1]))
                    odds[vs[i + 1]]++;
                else
                    odds.Add(vs[i + 1], 1);
            }

            var sortedEvens = evens.OrderByDescending(p => p.Value).ToArray();
            var sortedOdds = odds.OrderByDescending(p => p.Value).ToArray();

            if (sortedEvens.Length == 1 && sortedOdds.Length == 1)
            {
                if (sortedEvens[0].Key == sortedOdds[0].Key)
                {
                    return sortedEvens[0].Value;
                }
                else return 0;
            }


            if (sortedEvens[0].Key == sortedOdds[0].Key)
            {
                if (sortedEvens.Length == 1)
                {
                    return N / 2 - sortedOdds[1].Value;
                }
                if (sortedOdds.Length == 1)
                {
                    return N / 2 - sortedEvens[1].Value;
                }
                if (sortedOdds[1].Value > sortedEvens[1].Value)
                    return N - sortedOdds[1].Value- sortedEvens[0].Value;
                else
                    return N - sortedOdds[0].Value - sortedEvens[1].Value;
            }

