using System;
using System.Collections.Generic;
using System.Linq;

class quiz
{
    public int solve(int n, int[] v)
    {
        int[] odd = new int[(int)n / 2];
        int[] even = new int[(int)n / 2];
        Dictionary<int, int> odic = new Dictionary<int, int>();
        Dictionary<int, int> edic = new Dictionary<int, int>();

        for (int i = 0; i < n / 2; i++)
        {
            even[i] = v[2 * i];
            odd[i] = v[2 * i + 1];
        }

        for (int i = 0; i < n / 2; i++)
        {
            edic[even[i]] = 0;
            odic[odd[i]] = 0;
        }

        for (int i = 0; i < n / 2; i++)
        {
            edic[even[i]]++;
            odic[odd[i]]++;
        }

        if(edic.Count == 1 && odic.Count == 1)
        {
            if (odd[0] != even[0])
                return 0;
            else
                return (int)n / 2;
        }

        var ne = edic.OrderBy(x => x.Value);
        var no = odic.OrderBy(x => x.Value);

        if(ne.ElementAt(0).Key != no.ElementAt(0).Key)
        {
            return n - ne.ElementAt(0).Value - no.ElementAt(0).Value;
        }
        else if(ne.ElementAt(0).Value >= no.ElementAt(0).Value)
        {
            return n - ne.ElementAt(0).Value - no.ElementAt(1).Value;
        }
        else
        {
            return n - ne.ElementAt(1).Value - no.ElementAt(0).Value;
        }

        return -1;
    }

    public int[] ParseIntBySpace(string str)
    {
        int[] array = new int[str.Length];
        int lastloc = 0, spaceloc = -1;

        for (int i = 0; i < str.Length; i++)
        {
            if (str[i] == ' ')
            {
                array[lastloc++] = int.Parse(str.Substring(spaceloc + 1, i - spaceloc - 1));
                spaceloc = i;
            }
            else if (i == str.Length - 1)
            {
                array[lastloc++] = int.Parse(str.Substring(spaceloc + 1, i - spaceloc));
            }
        }

        Array.Resize(ref array, lastloc);

        return array;
    }
}

