using System;
using System.Collections.Generic;
using System.Linq;

class Solution
{
    static void Main()
    {
        var n = int.Parse(Console.ReadLine());
        var v = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
        var a = new Dictionary<int, int>();
        var b = new Dictionary<int, int>();

        for (int i = 0; i < v.Length; i++)
        {
            if (i % 2 == 0)
            {
                if (!a.ContainsKey(v[i]))
                {
                    a[v[i]] = 0;
                }
                a[v[i]]++;
            }
            else
            {
                if (!b.ContainsKey(v[i]))
                {
                    b[v[i]] = 0;
                }
                b[v[i]]++;
            }
        }

        var a1 = a.OrderByDescending(x => x.Value).First();
        var a2 = new KeyValuePair<int, int>(-1, 0);
        if (a.Any(x => x.Key != a1.Key))
        {
            a2 = a.Where(x => x.Key != a1.Key).OrderByDescending(x => x.Value).First();
        }
        var b1 = b.OrderByDescending(x => x.Value).First();
        var b2 = new KeyValuePair<int, int>(-1, 0);
        if (b.Any(x => x.Key != b1.Key))
        {
            b2 = b.Where(x => x.Key != b1.Key).OrderByDescending(x => x.Value).First();
        }

        int result;
        if (a1.Key != b1.Key || a1.Value == a2.Value || b1.Value == b2.Value)
        {
            result = (n / 2 - a1.Value) + (n / 2 - b1.Value);
        }
        else
        {
            if (a1.Value == b1.Value)
            {
                result = Math.Min(n / 2 - a2.Value, n / 2 - b2.Value) + (n / 2 - a1.Value);
            }
            else if (a1.Value > b1.Value)
            {
                result = (n / 2 - a1.Value) + (n / 2 - b2.Value);
            }
            else
            {
                result = (n / 2 - a2.Value) + (n / 2 - b1.Value);
            }
        }

        Console.WriteLine(result);
    }
}

