            {
                if (i % 2 == 0)
                    oddDict[array[i]]++;
                else
                    eveDict[array[i]]++;
            }

            var oddMaxs = oddDict.Where(x => x.Value == oddDict.Max(m => m.Value)).ToDictionary(t => t.Key, t => t.Value);
            var eveMaxs = eveDict.Where(x => x.Value == eveDict.Max(m => m.Value)).ToDictionary(t => t.Key, t => t.Value);
            var oddMax = 0;
            var eveMax = 0;

            // 最大値が同じ場合はずらせないか考慮する
            foreach (var o in oddMaxs)
            {
                foreach (var e in eveMaxs)
                {
                    if (o.Key != e.Key)
                    {
                        oddMax = o.Key;
                        eveMax = e.Key;
                        break;
                    }
                }
            }

            // それでも同じ場合は特殊処理
            if (oddMax == eveMax)
            {
                Console.WriteLine(n / 2);
                return;
