    class ProgressionManager
    {
        private List<int> evenList = new List<int>();
        private List<int> oddList = new List<int>();

        public ProgressionManager(string[] prgs,string N_str)
        {
            if (!ParseProgession(prgs, N_str))
            {
                throw new Exception();
            }
        }

        private bool ParseProgession(string[] prgs,string N_str)
        {
            int N;
            if(int.TryParse(N_str,out N) && N % 2 == 0)
            {
                for(int i = 0; i < prgs.Count(); i++)
                {
                    int prg_int;
                    if (!int.TryParse(prgs[i], out prg_int))
                    {
                        return false;
                    }
                    else
                    {
                        if (i % 2 == 0)
                        {
                            evenList.Add(prg_int);
                        }
                        else
                        {
                            oddList.Add(prg_int);
                        }
                    }
                }
                return true;
            }
            else
            {
                return false;
            }
        }

        public Tuple<int,int> CalcChangeMin()
        {
            var criteria1 = CalcCriteria(evenList);
            var criteria2 = CalcCriteria(oddList);

            int evenChangeCnt = 0;
            int oddChangeCnt = 0;
            for(int i = 1; i < evenList.Count; i++)
            {
                if(evenList[i] != criteria1)
                {
                    evenChangeCnt += 1;
                }
                if(oddList[i] != criteria2)
                {
                    oddChangeCnt += 1;
                }
            }
            return Tuple.Create(evenChangeCnt, oddChangeCnt);

        }

        private int CalcCriteria(List<int> tar)
        {
            var groups = tar.GroupBy(v => v);

            int maxCount = 0;
            int criteria = 0;
            foreach(var g in groups)
            {
                if(g.Count() > maxCount)
                {
                    maxCount = g.Count();
                    criteria = g.Key;
                }
            }
            return criteria;
        }
}

