        {
            var line = Console.ReadLine().Trim();
            var N = int.Parse(line);
            line = Console.ReadLine().Trim();
            var A = Array.ConvertAll(line.Split(' '), new Converter<string, int>(s => int.Parse(s)));
            for(var i = 0; i < N; ++i)
            {
                if(i % 2 == 0)
                {
                    if (odd.ContainsKey(A[i]))
                    {
                        odd[A[i]]++;
                    }
                    else
                    {
                        odd.Add(A[i], 1);
                    }
                }
                else
                {
                    if (even.ContainsKey(A[i]))
                    {
                        even[A[i]]++;
                    }
                    else
                    {
                        even.Add(A[i], 1);
                    }
                }
            }
            var oddList = searchPair(odd);
            var evenList = searchPair(even);
            if(oddList[0].Item1 != evenList[0].Item1)
            {
                Console.WriteLine(N - oddList[0].Item2 - evenList[0].Item2);
            }
            else
            {
                if(oddList.Count == 1 || evenList.Count == 1)
                {
                    if(oddList.Count == 1 && evenList.Count == 1)
                    {
                        Console.WriteLine(N / 2);
                    }
                    else if (oddList.Count == 1)
                    {
                        Console.WriteLine(N / 2 - evenList[1].Item2);
                    }
                    else
                    {
                        Console.WriteLine(N / 2 - oddList[1].Item2);
                    }
                }
                else
                {
                    var oddN1 = oddList[0].Item2;
                    var oddN2 = oddList[1].Item2;
                    var evenN1 = oddList[0].Item2;
                    var evenN2 = oddList[1].Item2;
                    Console.WriteLine(N - (oddN1 + evenN2 > oddN2 + evenN1 ? oddN1 + evenN2 : oddN2 + evenN1));
                }
            }
        }


        private static List<Tuple<int,int>> searchPair(Dictionary<int, int> list)
        {
            List<Tuple<int, int>> t = new List<Tuple<int, int>>();
            foreach(var k in list.Keys)
            {
                t.Add(new Tuple<int, int>(k, list[k]));
            }
            t.Sort((x,y) => x.Item2 - y.Item2);
            return t;
        }
    }
