public class ABC
{
    struct counter
    {
        public int number;
        public int count;

        public void plus()
        {
            this.count = this.count+1;
        }
        public counter(int number)
        {
            this.number = number;
            this.count = 1;
        }
        public void setcounter(int count)
        {
            this.count = count;
        }
    }



    public static void Main()
    {
        int n = int.Parse(Console.ReadLine());
        int[] v = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();

        int firstmax = 0;
        int output = 0;
        for (int counter = 0; counter < 2; counter++)
        {
            List<counter> d = new List<counter>();
            List<int> exist = new List<int>();
            for (int i = counter; i < n; i = i + 2)
            {
                if (exist.Contains(v[i]))
                {
                    for (int j = 0; j < d.Count; j++)
                    {
                        if (d[j].number == v[i])
                        {
                            counter c = new counter(d[j].number);
                            c.setcounter(d[j].count + 1);
                            d.RemoveAt(j);
                            d.Add(c);
                            break;
                        }
                    }
                }
                else
                {
                    exist.Add(v[i]);
                    d.Add(new counter(v[i]));
                }
            }

            d.Sort(Compare);
            d.Reverse();

            if (counter == 1 && firstmax == d[0].number)
            {
                output += n / 2 - d[1].count;
            }
            else
            {
                output += n / 2 - d[0].count;
            }
            firstmax = d[0].number;
        }
        Console.WriteLine(output);
    }

    private static int Compare(counter x, counter y)
    {
        if (x.count > y.count) return 1;
        if (x.count == y.count) return 0;
        return -1;
    }
}

