namespace AtCoder
{
    class Program
    {
        private static string Read() { return Console.ReadLine(); }
        private static int ReadInt() { return int.Parse(Read()); }
        private static long ReadLong() { return long.Parse(Read()); }
        private static double ReadDouble() { return double.Parse(Read()); }
        private static int[] ReadInts() { return Array.ConvertAll(Read().Split(), int.Parse); }
        private static long[] ReadLongs() { return Array.ConvertAll(Read().Split(), long.Parse); }
        private static double[] ReadDoubles() { return Array.ConvertAll(Read().Split(), double.Parse); }

        static int Solve(int N, int[] V)
        {
            var e = new Dictionary<int, int>();
            var o = new Dictionary<int, int>();
            e[0] = 0;
            o[0] = 0;
            for (int i = 0; i < N; ++i)
            {
                if (i % 2 == 0)
                {
                    if (!e.ContainsKey(V[i])) { e[V[i]] = 0; }
                    ++e[V[i]];
                }
                else
                {
                    if (!o.ContainsKey(V[i])) { o[V[i]] = 0; }
                    ++o[V[i]];
                }
            }
            var x = e.ToArray();
            var y = o.ToArray();
            Array.Sort(x, (a, b) => b.Value.CompareTo(a.Value));
            Array.Sort(y, (a, b) => b.Value.CompareTo(a.Value));
            int e0 = x[0].Value;
            int o0 = y[0].Value;
            int e1 = x[1].Value;
            int o1 = y[1].Value;
            return (x[0].Key != y[0].Key) ? N - e0 - o0 : Math.Min(N - o0 - e1, N - o1 - e0);
        }
        static void Main(string[] args)
        {
            int N = ReadInt();
            var V = ReadInts();
            Console.WriteLine(Solve(N, V));
        }
    }
}

