    {

        static void Main(string[] args)
        {
            int n = int.Parse(Console.ReadLine());
            string str = Console.ReadLine();
            var progression = str.Split(' ').Select(int.Parse);
            var twoProgressions = progression.Select((p, i) => new { Content = p, Index = i });
            var evenProgression = twoProgressions.Where(p => p.Index % 2 == 0).Select(p => p.Content);
            var oddProgression = twoProgressions.Where(p => p.Index % 2 == 1).Select(p => p.Content);

            int modNumEvenProg = evenProgression.Mode();
            int modNumOddProg = oddProgression.Mode();

            if (modNumOddProg == modNumEvenProg && evenProgression.Count() == oddProgression.Count())
            {
                Console.WriteLine(n / 2);
            }

            // 修正する箇所の数を計測
            int count;
            count = evenProgression.Count(ep => ep != modNumEvenProg);
            count += oddProgression.Count(op => op != modNumOddProg);
            Console.WriteLine(count);
        }
    }

    public static class MyExtension 
    {
        public static int Mode(this IEnumerable<int> progression)
        {
            var NumsOfElements = new Dictionary<int, int>();
            progression.Distinct().ToList().ForEach(p =>
            {
                NumsOfElements.Add(p, 0);
            });
            progression.ToList().ForEach(p =>
            {
                NumsOfElements[p]++;
            });
            var elements = NumsOfElements.OrderByDescending(noe => noe.Value);
            return elements.ElementAt(0).Key;
        }
    }
}

