public class Progression{
    List<int> evenPro;
    List<int> oddPro;
    int evenMaxNum;
    int oddMaxNum;
    int cnt;

    public void setProgression(string[] pro){
        cnt = 0;
        evenPro = new List<int>();
        oddPro = new List<int>();
        for(var i = 0; i < pro.Length; i++){
            var tmp = int.Parse(pro[i]);
            if(i % 2 == 0){
                evenPro.Add(tmp);
            }else{
                oddPro.Add(tmp);
            }
        }
    }

    public void setMax(){
        var evenHashList = new Dictionary<int,int>();//配列内の数字, 出現回数
        for(var i = 0; i < evenPro.Count; i++){
            if(evenHashList.ContainsKey(evenPro[i])){//配列内の数字が存在するかどうか
                evenHashList[evenPro[i]]++;
            }else{
                evenHashList.Add(evenPro[i],1);//配列内の数字を追加
            }
        }
        //出現回数をもとに後順に並び替えて先頭の配列内の数字値を取得
        var evenPair = evenHashList.OrderByDescending(x => x.Value).First();
        evenMaxNum = evenPair.Key;

        var oddHashList = new Dictionary<int,int>();//配列内の数字, 出現回数

        for(var i = 0; i < oddPro.Count; i++){
            if(oddHashList.ContainsKey(oddPro[i])){//配列内の数字が存在するかどうか
                oddHashList[oddPro[i]]++;
            }else{
                oddHashList.Add(oddPro[i],1);//配列内の数字を追加
            }
        }
        //出現回数をもとに後順に並び替えて先頭の配列内の数字値を取得
        var oddPair = oddHashList.OrderByDescending(x => x.Value).First();
        oddMaxNum = oddPair.Key;
        if(evenMaxNum == oddMaxNum){
            if(evenHashList.Count > 1 && oddHashList.Count > 1){
                evenHashList.Remove(evenMaxNum);
                oddHashList.Remove(oddMaxNum);
                evenPair = evenHashList.First();
                oddPair = oddHashList.First();
                if(evenPair.Value > oddPair.Value){
                    evenMaxNum = evenPair.Value;
                }else{
                    oddMaxNum = oddPair.Value;
                }
            }else{
                oddMaxNum--;
            }
        }
    }

    public int cntUp(){

        for(var i = 0; i < evenPro.Count; i++){
            if(evenMaxNum != evenPro[i]){
                cnt++;
            }
            if(oddMaxNum != oddPro[i]){
                cnt++;
            }
        }
        return cnt;
    }
}

