		public static void Solve(Scanner cin)
		{
			int n = cin.ReadInt();
			var v = cin.ReadIntArray(n);
			var sd1 = new SortedDictionary<int, int>(new ReverseComparer<int>(Comparer<int>.Default));
			var sd2 = new SortedDictionary<int, int>(new ReverseComparer<int>(Comparer<int>.Default));
			for (int i = 0; i < n; i++)
			{
				if (i % 2 == 0)
				{
					if (sd1.ContainsKey(v[i])) sd1[v[i]]++;
					else sd1.Add(v[i], 1);
				}
				else
				{
					if (sd2.ContainsKey(v[i])) sd2[v[i]]++;
					else sd2.Add(v[i], 1);
				}
			}
			if (sd1.First().Key != sd2.First().Key) Console.WriteLine(n - sd1.First().Value - sd2.First().Value);
			else
			{
				if (sd1.Count == 1 && sd2.Count == 1) Console.WriteLine(n / 2);
				else
				{
					var sd10 = sd1.First().Value;
					var sd20 = sd2.First().Value;
					sd1.Remove(sd1.First().Key);
					sd2.Remove(sd2.First().Key);
					var ans = n - sd10 - sd2.First().Value;
					Chmin(ref ans, n - sd20 - sd1.First().Value);
					Console.WriteLine(ans);
				}
			}
		}

		class ReverseComparer<T> : IComparer<T>
		{
			private IComparer<T> comparer;

			public ReverseComparer(IComparer<T> comparer)
			{
				this.comparer = comparer;
			}

			public int Compare(T x, T y)
			{
				// 指定する引数の順序を逆にすることで、元になったIComparer<T>とは逆の結果を返す
				return comparer.Compare(y, x);
			}
		}

		public static void Main(string[] args)
		{
			var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
