namespace Myatcoder
{
    public class Program
    {
        public static void Main(string[] args)
        {
            int n = int.Parse(Console.ReadLine());
            int[] A = Console.ReadLine().Split().Select(x => int.Parse(x)).ToArray();
            Dictionary<int, int> Even = new Dictionary<int, int>(n / 2);
            Dictionary<int, int> Odd = new Dictionary<int, int>(n / 2);
            for (int i = 0; i < n / 2; i++) {
                if (Even.ContainsKey(A[i * 2]) && !Odd.ContainsKey(A[i * 2])) Even[A[i * 2]]++;
                else Even[A[i * 2]] = 1;
                if (Odd.ContainsKey(A[i * 2 + 1]) && !Even.ContainsKey(A[i * 2 + 1])) Odd[A[i * 2 + 1]]++;
                else Odd[A[i * 2 + 1]] = 1;
            }
            int count = 0;
            for (int i = 1; i < n; i++) {
                if (A[0] == A[i]) count++;
                else break;
            }
            if (count != n - 1) Console.WriteLine(n - Even.Values.Max() - Odd.Values.Max());
            else Console.WriteLine(n / 2);
        }
    }
