namespace AtCoder_BeginerContest
{
    class Program
    {

        static void Main(string[] args)
        {
            int n = int.Parse(Console.ReadLine());
            string str = Console.ReadLine();
            var progression = str.Split(' ').Select(int.Parse);
            var twoProgressions = progression.Select((p, i) => new { Content = p, Index = i });
            var evenProgression = twoProgressions.Where(p => p.Index % 2 == 0).Select(p => p.Content);
            var oddProgression = twoProgressions.Where(p => p.Index % 2 == 1).Select(p => p.Content);

            int modNumEvenProg = evenProgression.Mode();
            int modNumOddProg = oddProgression.Mode();

            if (modNumOddProg == modNumEvenProg)
            {
                Console.WriteLine(n / 2);
            }

            // 修正する箇所の数を計測
            int count;
            count = evenProgression.Count(ep => ep != modNumEvenProg);
            count += oddProgression.Count(op => op != modNumOddProg);
            Console.WriteLine(count);
        }
    }

    public static class MyExtension 
    {
        public static int Mode(this IEnumerable<int> progression)
        {
            var NumsOfElements = new Dictionary<int, int>();
            progression.Distinct().ToList().ForEach(p =>
            {
                NumsOfElements.Add(p, 0);
            });
            progression.ToList().ForEach(p =>
            {
                NumsOfElements[p]++;
            });
            var elements = NumsOfElements.OrderByDescending(noe => noe.Value);
            return elements.ElementAt(0).Key;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

class quiz
{
    public int solve(int n, int[] v)
    {
        int[] odd = new int[(int)n / 2];
        int[] even = new int[(int)n / 2];
        Dictionary<int, int> odic = new Dictionary<int, int>();
        Dictionary<int, int> edic = new Dictionary<int, int>();

        for (int i = 0; i < n / 2; i++)
        {
            even[i] = v[2 * i];
            odd[i] = v[2 * i + 1];
        }

        for (int i = 0; i < n / 2; i++)
        {
            edic[even[i]] = 0;
            odic[odd[i]] = 0;
        }

        for (int i = 0; i < n / 2; i++)
        {
            edic[even[i]]++;
            odic[odd[i]]++;
        }

        if (edic.Count == 1 && odic.Count == 1)
        {
            if (odd[0] != even[0])
                return 0;
            else
                return (int)n / 2;
        }

        var ne = edic.OrderBy(x => x.Value);
        var no = odic.OrderBy(x => x.Value);

        if (ne.ElementAt(ne.Count() - 1).Key != no.ElementAt(no.Count() - 1).Key)
            return n - ne.ElementAt(ne.Count() - 1).Value - no.ElementAt(no.Count() - 1).Value;

        if (ne.Count() == 1)
            return n - ne.ElementAt(ne.Count() - 1).Value - no.ElementAt(no.Count() - 2).Value;

        if (no.Count() == 1)
            return n - ne.ElementAt(ne.Count() - 2).Value - no.ElementAt(no.Count() - 1).Value;

        if (ne.ElementAt(ne.Count() - 1).Value + no.ElementAt(no.Count() - 2).Value >= ne.ElementAt(ne.Count() - 2).Value + no.ElementAt(no.Count() - 1).Value)
            return n - ne.ElementAt(ne.Count() - 1).Value - no.ElementAt(no.Count() - 2).Value;

        else
            return n - ne.ElementAt(ne.Count() - 2).Value - no.ElementAt(no.Count() - 1).Value;

        return -1;
    }

    public int[] ParseIntBySpace(string str)
    {
        int[] array = new int[str.Length];
        int lastloc = 0, spaceloc = -1;

        for (int i = 0; i < str.Length; i++)
        {
            if (str[i] == ' ')
            {
                array[lastloc++] = int.Parse(str.Substring(spaceloc + 1, i - spaceloc - 1));
                spaceloc = i;
            }
            else if (i == str.Length - 1)
            {
                array[lastloc++] = int.Parse(str.Substring(spaceloc + 1, i - spaceloc));
            }
        }

        Array.Resize(ref array, lastloc);

        return array;
    }
}

