namespace AtCoder_BeginerContest
{
    class Program
    {

        static void Main(string[] args)
        {
            int n = int.Parse(Console.ReadLine());
            string str = Console.ReadLine();
            var progression = str.Split(' ').Select(int.Parse).ToList();
            var evenProgression = progression.Select((p, i) => new { Content = p, Index = i })
                                            .Where(p => p.Index % 2 == 0).Select(p => p.Content);
            var oddProgression = progression.Select((p, i) => new { Content = p, Index = i })
                                            .Where(p => p.Index % 2 == 1).Select(p => p.Content);
            int index = 0;
            var flag = false;
            evenProgression.ToList().ForEach(ep =>
            {
                if (ep == oddProgression.ElementAt(index))
                {
                    flag = true;
                }
                index++;
            });
            if (flag)
            {
                Console.WriteLine(n/2);
                return;
            }
            int modNumEvenProg = evenProgression.Mode();
            int modNumOddProg = oddProgression.Mode();

            // 修正する箇所の数を計測
            int count;
            count = evenProgression.Count(ep => ep != modNumEvenProg);
            count += oddProgression.Count(op => op != modNumOddProg);
            Console.WriteLine(count);
        }
    }

    public static class MyExtension 
    {
        public static int Mode(this IEnumerable<int> progression)
        {
            var NumsOfElements = new Dictionary<int, int>();
            progression.Distinct().ToList().ForEach(p =>
            {
                NumsOfElements.Add(p, 0);
            });
            progression.ToList().ForEach(p =>
            {
                NumsOfElements[p]++;
            });
            var elements = NumsOfElements.OrderByDescending(noe => noe.Value);
            var havinglargestValueElement = elements.ElementAt(0);
            return havinglargestValueElement.Key;
        }
    }
}

