                    a[v[i]] = 0;
                }
                a[v[i]]++;
            }
            else
            {
                if (!b.ContainsKey(v[i]))
                {
                    b[v[i]] = 0;
                }
                b[v[i]]++;
            }
        }

        var a1 = a.OrderByDescending(x => x.Value).First();
