                if (flag)
                    ht2.Remove(Indexnum2);
                else
                    ht1.Remove(Indexnum);
            }
        }

        public static void HaTa(ref Hashtable ht1, ref int Topnum,ref string Indexnum,ref int tmpht1)
        {
            foreach (DictionaryEntry x in ht1)
            {
                if (Topnum < (int)x.Value)
                    tmpht1 = Topnum;
                    Topnum = (int)x.Value;
                    Indexnum = (string)x.Key;
            }
        }

        public static void HashTableMake(ref Hashtable ht,string tmpstr)
        {
            if (ht.ContainsKey(tmpstr))
                ht[tmpstr] = (int)ht[tmpstr] + 1;
            else
                ht[tmpstr] = 1;
        }
    }
