using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace AtCorder
{
	public class Program
	{
		static void Main(string[] args)
		{
			long n = long.Parse(Console.ReadLine());
			List<long> v = Console.ReadLine().Split(' ').Select(long.Parse).ToList();
			long[] odd = new long[100001];
			long[] even = new long[100001];
			for (int i = 0; i < n; i+=2) {
				odd[v[i]]++;
				even[v[i + 1]]++;
			}

			var oo = odd.ToList();
			var ee = even.ToList();
			long maxo = oo.Max();
			long maxe = ee.Max();
			int indexo = oo.IndexOf(maxo);
			int indexe = ee.IndexOf(maxe);
			if (indexo == indexe) {
				oo.Sort();
				ee.Sort();
				if (oo[oo.Count - 2] > ee[oo.Count - 2]) {
					maxo = oo[oo.Count - 2];
				} else {
					maxe = ee[oo.Count - 2];
				}
			}

			long ans = n - maxo - maxe;
			Console.WriteLine(ans);
		}
	}
}

using System;
