            var input = Console.ReadLine().Split(' ').Select(int.Parse).ToList();

            for (var i = 0; i < n; i++)
            {
                if (i % 2 == 0)
                {
                    if (d1.ContainsKey(input[i]))
                    {
                        d1[input[i]]++;
                    }
                    else
                    {
                        d1[input[i]] = 1;
                    }
                }
                else
                {
                    if (d2.ContainsKey(input[i]))
                    {
                        d2[input[i]]++;
                    }
                    else
                    {
                        d2[input[i]] = 1;
                    }
                }
