public class AtCoderA
{
    static void Main()
    {
        var sc = new Scanner();

        long n = sc.NextLong();
        long[] v = sc.LongArray();

        Dictionary<long, long> oddDic = new Dictionary<long, long>();
        Dictionary<long, long> evenDic = new Dictionary<long, long>();

        for (int i = 0; i < n; i++)
        {
            if (i % 2 == 0)
            {
                if (evenDic.ContainsKey(v[i]))
                {
                    evenDic[v[i]]++;
                }
                else
                {
                    evenDic.Add(v[i], 1);
                }
            }
            else
            {
                if (oddDic.ContainsKey(v[i]))
                {
                    oddDic[v[i]]++;
                }
                else
                {
                    oddDic.Add(v[i], 1);
                }
            }
        }

        var oddList = oddDic.OrderByDescending(i => i.Value).ToList();
        var evenList = evenDic.OrderByDescending(i => i.Value).ToList();

        var oddMax = oddList[0].Value;
        var evenMax = evenList[0].Value;

        if (oddList[0].Key == evenList[0].Key)
        {
            if (oddList.Count == 1 && evenList.Count == 1)
            {
                evenMax = 0;
            }
            else if (oddList.Count == 1)
            {
                evenMax = evenList[1].Value;
            }
            else if (evenList.Count == 1)
            {
                oddMax = oddList[1].Value;
            }
            else
            {
                if (oddList[1].Value > evenList[1].Value)
                {
                    oddMax = oddList[1].Value;
                }
                else
                {
                    evenMax = evenList[1].Value;
                }
            }
        }

        long answer = n - oddMax - evenMax;

        Console.WriteLine(answer);
    }

    class Scanner
    {
        private string[] _line;
        private int _index;
        private const char Separator = ' ';

        public Scanner()
        {
            _line = new string[0];
            _index = 0;
        }

        public string Next()
        {
            while (_index >= _line.Length)
            {
                _line = Console.ReadLine().Split(Separator);
                _index = 0;
            }

            return _line[_index++];
        }

        public int NextInt() => int.Parse(Next());
        public long NextLong() => long.Parse(Next());
        public double NextDouble() => double.Parse(Next());
        public decimal NextDecimal() => decimal.Parse(Next());
        public char NextChar() => Next()[0];
        public char[] NextCharArray() => Next().ToCharArray();

        public string[] Array()
        {
            _line = Console.ReadLine().Split(Separator);
            _index = _line.Length;
            return _line;
        }

        public int[] IntArray() => Array().Select(int.Parse).ToArray();
        public long[] LongArray() => Array().Select(long.Parse).ToArray();
        public double[] DoubleArray() => Array().Select(double.Parse).ToArray();
        public decimal[] DecimalArray() => Array().Select(decimal.Parse).ToArray();
    }
}

