            System.Console.WriteLine(n - (oddCount.First().Count() + evenCount.First().Count()));
        else
        {
            System.Console.WriteLine(
                Math.Min(
                n - (oddCount.First().Count() + (evenCount.Skip(1).Any() ? evenCount.Skip(1).First().Count() : 0)),
                n - ((oddCount.Skip(1).Any() ? oddCount.Skip(1).First().Count() : 0) + evenCount.First().Count()))
                );
        }
    }

