namespace ARC103C
{
    public class Program
    {
        struct Result
        {
            public int ReplaceCount;
            public int RemainNumber;
        }

        void Solve(StreamScanner ss, StreamWriter sw)
        {
            //---------------------------------
            var N = ss.Next(int.Parse);
            var V = ss.Next(int.Parse, N);
            var odds = V.Where((_, i) => i % 2 == 0);
            var evens = V.Where((_, i) => i % 2 == 1);

            var oddsRes = GetResult(odds);
            var evensRes = GetResult(evens);
            if (oddsRes.RemainNumber != evensRes.RemainNumber)
            {
                Console.WriteLine(oddsRes.ReplaceCount + evensRes.ReplaceCount);
                return;
            }

            var res1 = GetResult(odds, 0).ReplaceCount + GetResult(evens, 1).ReplaceCount;
            var res2 = GetResult(odds, 1).ReplaceCount + GetResult(evens, 0).ReplaceCount;
            Console.WriteLine(Math.Max(res1, res2));
            //---------------------------------
        }

        Result GetResult(IEnumerable<int> seq, int rank = 0)
        {
            var counts = new Dictionary<int, int> {{0, 0}};

            foreach (var x in seq)
            {
                if (!counts.ContainsKey(x)) counts.Add(x, 0);
                counts[x]++;
            }

            var remain = counts.OrderByDescending(pair => pair.Value).ToArray()[rank];
            return new Result{ReplaceCount = seq.Count() - remain.Value, RemainNumber = remain.Key};
        }

        static void Main()
        {
            var ss = new StreamScanner(new StreamReader(Console.OpenStandardInput()));
            var sw = new StreamWriter(Console.OpenStandardOutput()) {AutoFlush = false};
            new Program().Solve(ss, sw);
            sw.Flush();
        }

        static readonly Func<string, string> String = s => s;
    }

    public class StreamScanner
    {
        static readonly char[] Sep = {' '};
        readonly Queue<string> buffer = new Queue<string>();
        readonly TextReader textReader;

        public StreamScanner(TextReader textReader)
        {
            this.textReader = textReader;
        }

        public T Next<T>(Func<string, T> parser)
        {
            if (buffer.Count != 0) return parser(buffer.Dequeue());
            var nextStrings = textReader.ReadLine().Split(Sep, StringSplitOptions.RemoveEmptyEntries);
            foreach (var nextString in nextStrings) buffer.Enqueue(nextString);
            return Next(parser);
        }

        public T[] Next<T>(Func<string, T> parser, int x)
        {
            var ret = new T[x];
            for (var i = 0; i < x; ++i) ret[i] = Next(parser);
            return ret;
        }

        public T[][] Next<T>(Func<string, T> parser, int x, int y)
        {
            var ret = new T[y][];
            for (var i = 0; i < y; ++i) ret[i] = Next(parser, x);
            return ret;
        }
    }
}

