        public static void HaTa(ref Hashtable ht1, ref int Topnum,ref string Indexnum,ref int tmpht1)
        {
            foreach (DictionaryEntry x in ht1)
            {
                if (Topnum < (int)x.Value)
                {
                    tmpht1 = Topnum;
                    Topnum = (int)x.Value;
                    Indexnum = (string)x.Key;
                }
            }
        }

        public static void HashTableMake(ref Hashtable ht1,string tmp_string)
        {
            if (ht1.ContainsKey(tmp_string))
            {
                ht1[tmp_string] = (int)ht1[tmp_string] + 1;
            }
            else
            {
                ht1[tmp_string] = 1;
            }
        }
