            r2[v[i] - 1]++;
        }
        if(Array.IndexOf(r1, r1.Max()) == Array.IndexOf(r2, r2.Max())) {
            Console.WriteLine(n / 2);
        } else {
            Console.WriteLine((n / 2 - r1.Max()) + (n / 2 - r2.Max()));
        }
    }
    static T ChangeT<T>(string s) => (T)Convert.ChangeType(s, typeof(T));
    static void Input<A>(out A a) {
        var words = Console.ReadLine().Split(new[] { ' ' }, options: StringSplitOptions.RemoveEmptyEntries);
        a = ChangeT<A>(words[0]);
    }
