namespace Algorithm
{
    class Program
    {
        static void Main(string[] args)
        {
            var n = int.Parse(Console.ReadLine());
            var array = Console.ReadLine().Split().Select(z => int.Parse(z)).ToArray();

            var oddDict = new Dictionary<int, int>();
            var eveDict = new Dictionary<int, int>();

            for (var i = 0; i < n; i++)
            {
                if (i % 2 == 0)
                    oddDict[array[i]] = 0;
                else
                    eveDict[array[i]] = 0;
            }

            for (var i = 0; i < n; i++)
            {
                if (i % 2 == 0)
                    oddDict[array[i]]++;
                else
                    eveDict[array[i]]++;
            }

            var oddMax = oddDict.First(x => x.Value == oddDict.Max(m => m.Value)).Key;
            var eveMax = eveDict.First(x => x.Value == eveDict.Max(m => m.Value)).Key;

            // oddとeveが同じ場合は特殊処理
            if (oddMax == eveMax)
            {
                Console.WriteLine(n / 2);
                return;
            }

            // oddMaxとeveMaxではない数値を数える
            var total = 0;

            for (var i = 0; i < n; i++)
            {
                if (i % 2 == 0 && array[i] != oddMax)
                    total++;

                if (i % 2 == 1 && array[i] != eveMax)
                    total++;
            }

            Console.WriteLine(total);
        }
    }
}

