        number_maps[1] = new Dictionary<int, int>();

        for (int i = 0; i < Vs.Length; i++)
        {
            Dictionary<int, int> map = number_maps[i%2];

            if (map.ContainsKey(Vs[i])) map[Vs[i]]++;
            else map.Add(Vs[i], 1);
        }

        int[] first_even = new int[2];
        int[] first_odd = new int[2];
        int[] second_even = new int[2];
        int[] second_odd = new int[2];

        for (int i = 0; i < number_maps.Length; i++)
        {
            int[] first = i % 2 == 0 ? first_even : first_odd;
            int[] second = i % 2 == 0 ? second_even : second_odd;
            foreach (var item in number_maps[i])
            {
                if (item.Value > second[1])
                {
                    second[0] = item.Key;
                    second[1] = item.Value;
                }

                if (first[1] < second[1])
                {
                    int[] move = new int[2] { first[0], first[1] };
                    first = second;
                    second = move;
                }
            }
        }

        int e = 0;
        int o = 0;

        if (first_even[0]!=first_odd[0])
        {
            e = first_even[1];
            o = first_odd[1];
        }
        else
        {
            if (first_even[1] + second_odd[1] > first_odd[1] + second_even[1])
            {
                e = first_even[1];
                o = second_odd[1];
            }
            else
            {
                e = second_even[1];
                o = first_odd[1];
            }
        }



