        private static long[] ReadLongs() { return Array.ConvertAll(Read().Split(), long.Parse); }
        private static double[] ReadDoubles() { return Array.ConvertAll(Read().Split(), double.Parse); }

        static int Solve(int N, int[] V)
        {
            var e = new Dictionary<int, int>();
            var o = new Dictionary<int, int>();
            for (int i = 0; i < N; ++i)
            {
                if (i % 2 == 0)
                {
                    if (!e.ContainsKey(V[i])) { e[V[i]] = 0; }
                    ++e[V[i]];
                }
                else
                {
                    if (!o.ContainsKey(V[i])) { o[V[i]] = 0; }
                    ++o[V[i]];
                }
            }
            if (e.Count == 1 && o.Count == 1 && V[0] == V[1]) { return N / 2; }
            return N - e.Values.Max() - o.Values.Max();
        }
        static void Main(string[] args)
        {
            int N = ReadInt();
            var V = ReadInts();
            Console.WriteLine(Solve(N, V));
        }
    }
}

