namespace Algorithm
{
    class Program
    {
        static void Main(string[] args)
        {
            var n = int.Parse(Console.ReadLine());
            var array = Console.ReadLine().Split().Select(z => int.Parse(z)).ToArray();

            var oddDict = new Dictionary<int, int>();
            var eveDict = new Dictionary<int, int>();

            for (var i = 0; i < n; i++)
            {
                if (i % 2 == 0)
                    oddDict[array[i]] = 0;
                else
                    eveDict[array[i]] = 0;
            }

            for (var i = 0; i < n; i++)
            {
                if (i % 2 == 0)
                    oddDict[array[i]]++;
                else
                    eveDict[array[i]]++;
            }

            oddDict = oddDict.OrderByDescending(k => k.Value).ToDictionary(t => t.Key, t => t.Value);
            eveDict = eveDict.OrderByDescending(k => k.Value).ToDictionary(t => t.Key, t => t.Value);

            var oddMax = oddDict.First().Key;
            var eveMax = eveDict.First().Key;

            // 最大値が同じ場合はずらせないか考慮する
            // 2番目に大きい数値が大きいほうをずらす
            var oddArrayKey = oddDict.Keys.ToArray();
            var oddArrayValue = oddDict.Values.ToArray();
            var eveArrayKey = eveDict.Keys.ToArray();
            var eveArrayValue = eveDict.Values.ToArray();

            // 完全に同じ条件の場合は特殊処理
            if (oddArrayKey.Length == 1 && eveArrayKey.Length == 1 && oddArrayKey[0] == eveArrayKey[0])
            {
                Console.WriteLine(n / 2);
                return;
            }

            for (var i = 0; i < n / 2; i++)
            {
                if (oddArrayKey[i] == eveArrayKey[i])
                {
                    var ooo = oddArrayValue[i] + eveArrayValue[i + 1];
                    var eee = eveArrayValue[i] + oddArrayValue[i + 1];
                    if (ooo > eee)
                    {
                        oddMax = oddArrayKey[i];
                        eveMax = eveArrayKey[i + 1];
                        break;
                    }
                    else
                    {
                        oddMax = oddArrayKey[i + 1];
                        eveMax = eveArrayKey[i];
                        break;
                    }

                }
                else break;
            }

            // oddMaxとeveMaxではない数値を数える
            var total = 0;

            for (var i = 0; i < n; i++)
            {
                if (i % 2 == 0 && array[i] != oddMax)
                    total++;

                if (i % 2 == 1 && array[i] != eveMax)
                    total++;
            }

            Console.WriteLine(total);
        }
    }
}

