using System.Linq;
using System.Web;

namespace Competitive
{
    internal class Solution
    {
        public int N;
        public long MOD = 1000000007;
        public int[] V;

        public void Run()
        {
            N = Input.ReadInt();
            V = Input.ReadIntArray();

            var dic1 = new Dictionary<int, int>();
            var dic2 = new Dictionary<int, int>();

            {
                for (int i = 0; i < N; i += 2)
                {
                    int v = V[i];
                    if (!dic1.ContainsKey(v))
                    {
                        dic1.Add(v, 0);
                    }

                    dic1[v]++;
                }
            }

            {
                for (int i = 1; i < N; i += 2)
                {
                    int v = V[i];
                    if (!dic2.ContainsKey(v))
                    {
                        dic2.Add(v, 0);
                    }

                    dic2[v]++;
                }
            }

            var ts1 = Top2(dic1);
            var ts2 = Top2(dic2);
            int ret = int.MaxValue;

            if (ts1[0] != ts2[0]) ret = Math.Min(ret, V.Length - ts1[1] - ts2[1]);
            if (ts1[0] != ts2[2]) ret = Math.Min(ret, V.Length - ts1[1] - ts2[3]);
            if (ts1[2] != ts2[0]) ret = Math.Min(ret, V.Length - ts1[3] - ts2[1]);
            if (ts1[2] != ts2[2]) ret = Math.Min(ret, V.Length - ts1[3] - ts2[3]);

            Console.WriteLine(ret);

        }

        public int[] Top2(Dictionary<int, int> dic)
        {
            // top2
            int t1 = -1;
            int v1 = 0;
            int t2 = -2;
            int v2 = 0;
            foreach (var k in dic.Keys)
            {
                int v = dic[k];
                if (v >= v1)
                {
                    t2 = t1;
                    v2 = v1;
                    t1 = k;
                    v1 = v;
                }
                else if (v >= v2)
                {
                    t2 = k;
                    v2 = v;
                }
            }

            return new int[] {t1, v1, t2, v2};
        }
    }

