using System;
using System.Collections.Generic;
using System.Linq;

class Solution
{
    static void Main()
    {
        var n = int.Parse(Console.ReadLine());
        var v = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
        var a = new Dictionary<int, int>();
        var b = new Dictionary<int, int>();

        for (int i = 0; i < v.Length; i++)
        {
            if (i % 2 == 0)
            {
                if (!a.ContainsKey(v[i]))
                {
                    a[v[i]] = 0;
                }
                a[v[i]]++;
            }
            else
            {
                if (!b.ContainsKey(v[i]))
                {
                    b[v[i]] = 0;
                }
                b[v[i]]++;
            }
        }

        var a1st = a.OrderByDescending(x => x.Value).First();
        KeyValuePair<int, int>? a2nd = null;
        if (a.Any(x => x.Key != a1st.Key))
        {
            a2nd = a.Where(x => x.Key != a1st.Key).OrderByDescending(x => x.Value).First();
        }
        var b1st = b.OrderByDescending(x => x.Value).First();
        KeyValuePair<int, int>? b2nd = null;
        if (b.Any(x => x.Key != b1st.Key))
        {
            b2nd = b.Where(x => x.Key != b1st.Key).OrderByDescending(x => x.Value).First();
        }

        int result;
        if (a1st.Key == b1st.Key)
        {
            if (a2nd == null && b2nd == null)
            {
                result = n / 2;
            }
            else if (a2nd == null)
            {
                result = n / 2 - ((KeyValuePair<int, int>)b2nd).Value;
            }
            else if (b2nd == null)
            {
                result = n / 2 - ((KeyValuePair<int, int>)a2nd).Value;
            }
            else
            {
                var a2 = ((KeyValuePair<int, int>)a2nd);
                var b2 = ((KeyValuePair<int, int>)b2nd);

                if (a1st.Value == b1st.Value)
                {
                    result = Math.Min(n / 2 - a2.Value, 2 / n - b2.Value) + (n / 2 - a1st.Value);
                }
                if (a1st.Value > b1st.Value)
                {
                    result = (n / 2 - a1st.Value) + (n / 2 - a2.Value);
                }
                else
                {
                    result = (n / 2 - a2.Value) + (n / 2 - b1st.Value);
                }
            }
        }
        else
        {
            result = (n / 2 - a1st.Value) + (n / 2 - b1st.Value);
        }

        Console.WriteLine(result);
    }
}

