	var input = input.split('\n');
	var n = toInt(input[0]);
	var vs = toIntArr(input[1].split(' '));
	var odd = [];
	var even = [];
	for(var i = 0; i < n; i++){
		if(i%2===1){
			even[vs[i]] = !even[vs[i]]? 1: even[vs[i]] + 1; 
		}else{
			odd[vs[i]] = !odd[vs[i]]? 1: odd[vs[i]] + 1; 
		}
	}
	var xs = odd.map((e,ind,arr)=>({el:e,ind:ind})).filter(el=>el.el>0).sort((a,b)=>b.el-a.el);
	var ys = even.map((e,ind,arr)=>({el:e,ind:ind})).filter(el=>el.el>0).sort((a,b)=>b.el-a.el);
	var ans = 0;
	if(xs[0].ind === ys[0].ind){
		if(xs.length === 1){
			if(ys.length === 1){
				ans = n/2;
			}else{
				ans = n/2 - ys[1].el;
			}
		}else{
			if(ys.length === 1){
				ans = n/2 - xs[1].el;
			}else{
				ans = min(n - xs[0].el - ys[1].el, n - xs[1].el - ys[0].el);
			}
		}
