	for i := 1; i < n; i += 2 {
		rvals[v[i]] += 1
	}

	lmv, lmn := 0, 0
	for k, v := range lvals {
		if lmn < v {
			lmv = k
			lmn = v
		}
	}
	rmv, rmn := 0, 0
	for k, v := range rvals {
		if rmn < v {
			rmv = k
			rmn = v
		}
	}

	if lmv != rmv {
		fmt.Println(n - lmn - rmn)
		return
	}

	l2n := 0
	for k, v := range lvals {
		if k != lmv && l2n < v {
			l2n = v
		}
