	scanner = bufio.NewScanner(os.Stdin)
)

func main() {
	scanner.Split(bufio.ScanWords)
	n := scanInt()
	len := n / 2
	e := make([]int, len)
	ec := make(map[int]int, len)
	o := make([]int, len)
	oc := make(map[int]int, len)

	for i := 0; i < n; i++ {
		j := i / 2
		if i%2 == 0 {
			e[j] = scanInt()
			ec[e[j]]++
		} else {
			o[j] = scanInt()
			oc[o[j]]++
		}
	}

	mn := func(m map[int]int) (int, int, int) {
		r1, r2 := 0, 0
		maxnum := 0
		for k, v := range m {
			if v > r1 {
				r1, r2 = v, r1
				maxnum = k
			} else if v > r2 {
				r2 = v
			}
		}
		return r1, r2, maxnum
	}

	e1, e2, em := mn(ec)
	o1, o2, om := mn(oc)

	if em != om {
		fmt.Println((len - e1) + (len - o1))
		return
	}

	t1 := (len - e1) + (len - o2)
	t2 := (len - e2) + (len - o1)

	if t1 < t2 {
		fmt.Println(t1)
	} else {
		fmt.Println(t2)
	}
}

func scanInt() int {
	i, _ := strconv.Atoi(scanText())
	return i
}

func scanInts(size int) []int {
	ints := make([]int, size)
	for i := 0; i < size; i++ {
		ints[i] = scanInt()
	}
	return ints
}

func scanFloat64() float64 {
	f, _ := strconv.ParseFloat(scanText(), 64)
	return f
}

func scanFloat64s(size int) []float64 {
	f := make([]float64, size)
	for i := 0; i < size; i++ {
		f[i] = scanFloat64()
	}
	return f
}

func scanText() string {
	scanner.Scan()
	return scanner.Text()
}

func scanTexts(size int) []string {
	s := make([]string, size)
	for i := 0; i < size; i++ {
		s[i] = scanText()
	}
	return s
}

func abs(n int) int {
	if n < 0 {
		return -n
	}
	return n
}

func pow(x, y int) int {
	return int(math.Pow(float64(x), float64(y)))
}

// greatest common divisor(最大公約数)
func gcd(a, b int) int {

	if a < b {
		a, b = b, a
	}

	for {
		mod := a % b
		if mod == 0 {
			return b
		}
		a, b = b, mod
	}
}

// latest common multiple(最小公倍数)
func lcm(a, b int) int {
	return (a / gcd(a, b)) * b
}

