type pair struct {
	index  int64
	p1, p2 interface{}
}
type pairs []pair

func (slice pairs) Len() int {
	return len(slice)
}

func (slice pairs) Less(i, j int) bool {
	return slice[i].index < slice[j].index
}

func (slice pairs) Swap(i, j int) {
	slice[i], slice[j] = slice[j], slice[i]
}

type number struct {
	n   int64
	cnt int64
}
type numbers []number

func (slice numbers) Len() int {
	return len(slice)
}

func (slice numbers) Less(i, j int) bool {
	return slice[i].cnt > slice[j].cnt
}

func (slice numbers) Swap(i, j int) {
	slice[i], slice[j] = slice[j], slice[i]
}

