	n := readInt()
	v := make([]int64, n)
	var o numbers
	var e numbers
	var osum, esum int64
	mo := make(map[int64]int64, n)
	me := make(map[int64]int64, n)
	for i := int64(0); i < n; i++ {
		v[i] = readInt()
		if i%2 == 0 {
			mo[v[i]]++
			osum++
		} else {
			me[v[i]]++
			esum++
		}
	}
	for k, v := range mo {
		o = append(o, number{k, v})
	}
	for k, v := range me {
		e = append(e, number{k, v})
	}
	sort.Sort(o)
	sort.Sort(e)
	// 最頻値が異なる場合
	if o[0].n != e[0].n {
		fmt.Println(n - o[0].cnt - e[0].cnt)
		return
	}
	// 最頻値が同じ場合
	// 偶数番目の数列eをE1で書き換える
	// 奇数番目の数列oをO2で書き換える
	var e1wo2w int64 = n
	for i := 1; i < len(e); i++ {
		e1wo2w -= e[i].cnt
	}
	for i := 0; i < len(o); i++ {
		if i == 1 {
			continue
		}
		e1wo2w -= o[i].cnt
	}

	var e2wo1w int64 = n
	for i := 0; i < len(e); i++ {
		if i == 1 {
			continue
		}
		e2wo1w -= e[i].cnt
	}
	for i := 1; i < len(o); i++ {
		e2wo1w -= o[i].cnt
	}
	fmt.Println(min(e1wo2w, e2wo1w))
}

