type Tuple struct {
	key   int
	value int
	which int
}

func main() {
	sc := NewScanner()
	N := sc.NextInt()
	A := sc.NextIntArray()

	mp := make(SortInterFace, 2e5+1)

	for i := 0; i < N; i += 2 {
		P := A[i]
		mp[P].key = P
		mp[P].value++
	}
	for i := 1; i < N; i += 2 {
		P := A[i]
		mp[P+1e5].key = P
		mp[P+1e5].which = 1
		mp[P+1e5].value++
	}

	sort.Sort(mp)

	used := mp[0].key
	total := N/2 - mp[0].value
	which := mp[0].which
	checked := false
	for i := 1; i < len(mp); i++ {
		if which != mp[i].which && used != mp[i].key {
			total += N/2 - mp[i].value
			checked = true
			break
		}
	}
	if !checked {
		total += N / 2
	}
	fmt.Println(total)
}

