        let c2 = S.cardinal set2 in
        if c1 > 1 && c2 > 1 then (
            let (v3, i3) = S.max_elt (S.remove m1 set1) in
            let (v4, i4) = S.max_elt (S.remove m2 set2) in
            max (n - v3 - v2) (n - v1 - v4)
        ) else if c1 > 1 then (
            let (v3, i3) = S.max_elt (S.remove m1 set1) in
            n - v3 - v2
        ) else if c2 > 1 then (
            let (v4, i4) = S.max_elt (S.remove m2 set2) in
            n - v1 - v4
        ) else n / 2
    )
)

