void main() {
  long N;
  scanln(N);
  long[] vs = readln.split.to!(long[]);
  long[] as = N.floor(2).iota.map!(i => vs[2*i]).array;
  long[] bs = N.floor(2).iota.map!(i => vs[2*i+1]).array;

  auto f(long[] xs) {
    long[long] aa;
    foreach(x; xs) {
      aa[x]++;
    }
    aa[-1] = 0;
    return aa.byPair.array.sort!"a.value>b.value".array;
  }

  auto cs = f(as);
  auto ds = f(bs);

  long ans = INF;
  if (cs[0].key != ds[0].key) ans.ch!min(N - cs[0].value - ds[0].value);
  if (cs[0].key != ds[1].key) ans.ch!min(N - cs[0].value - ds[1].value);
  if (cs[1].key != ds[0].key) ans.ch!min(N - cs[1].value - ds[0].value);
  ans.writeln;
}

