					swap(first, second);
					firstkey = key;
				}
			}
		}
		ans += first;
		if (p == 0) {
			memkey = firstkey;
			memdiff = first-second;
		} else if (memkey == firstkey) {
			int diff = first-second;
			ans -= min(memdiff, diff);
		}
	}
