def basket_count(arr):
    basket = []
    tmp = arr[0]
    cnt_ele = 0
    for ele in arr:
        if ele == tmp:
            cnt_ele += 1
        else:
            basket.append([tmp, cnt_ele])
            # reset count for basket
            tmp = ele
            cnt_ele = 1
    basket.append([tmp, cnt_ele])
    return basket

def solve():
    n = int(raw_input())
    v = [int(_) for _ in raw_input().split()]
    v0 = []
    v1 = []
    for i in range(n):
        if i % 2 == 0:
            v0.append(v[i])
        else:
            v1.append(v[i])
    v0.sort()
    v1.sort()
    bask_v0 = basket_count(v0)
    bask_v0.sort(reverse = True, key = lambda x: x[1])
    bask_v1 = basket_count(v1)
    bask_v1.sort(reverse = True, key = lambda x: x[1])
    if bask_v0[0][0] != bask_v1[0][0]:
        ret = n - (bask_v0[0][1] + bask_v1[0][1])
    elif len(bask_v1) <= 1:
        if len(bask_v0) > 1:
            ret = n - (bask_v0[1][1] + bask_v1[0][1])
        else:
            ret = n - bask_v0[0][1]
    else: # len(bask_v1) > 1
        if len(bask_v0) <= 1:
            ret = n - (bask_v0[0][1] + bask_v1[1][1])
        else:
            ret = n - max(bask_v0[0][1] + bask_v1[1][1], \
                          bask_v0[1][1] + bask_v1[0][1])
    print str(ret)

