INF = float("inf")


def solve(n: int, v: "List[int]"):
    c0 = Counter(v[0::2])
    c1 = Counter(v[1::2])

    c0[0] = 0
    c1[0] = 0

    mc0 = c0.most_common(1)[0]
    mc1 = c1.most_common(1)[0]
    if mc0[0] == mc1[0]:
        if mc0[1] >= mc1[1]:
            del c1[mc1[0]]
            mc1 = c1.most_common(1)[0]
        else:
            del c0[mc0[0]]
            mc0 = c0.most_common(1)[0]
    print(n - mc0[1] - mc1[1])

    return


