import sys


def get_histogram(arr):
    count = [[i, 0] for i in range(100000)]
    appeared = []
    for i in arr:
        count[i][1] += 1
        if not i in appeared:
            appeared.append(i)
    histogram = sorted(count, key=lambda x: x[1], reverse=True)
    return histogram  # [:len(appeared)]


def count_not_majority(historgram):
    count = 0
    for hist in historgram[1:]:
        count += hist[1]
    return count


def main(argv):
    n = int(input())
    nums_input = input()
    nums = list(map(lambda x: int(x), nums_input.split(' ')))

    hist_odd = get_histogram(nums[::2])
    count_odd = sum([hist[1] for hist in hist_odd])
    hist_even = get_histogram(nums[1::2])
    count_even = sum([hist[1] for hist in hist_even])

    # print(hist_even[:5], count_even, hist_odd[:5], count_odd)

    if hist_even[0][0] != hist_odd[0][0]:
        print(count_not_majority(hist_even) + count_not_majority(hist_odd))
    else:
        if count_even - hist_even[1][1] > count_odd - hist_odd[1][1]:
            print(count_not_majority(hist_even) + count_odd - hist_odd[1][1])
        else:
            print(count_not_majority(hist_odd) + count_even - hist_even[1][1])


