def slove():
    import sys
    import collections
    input = sys.stdin.readline
    do = collections.defaultdict(int)
    de = collections.defaultdict(int)
    n = int(input().rstrip('\n'))
    v = list(map(int, input().rstrip('\n').split()))
    for i, vv in enumerate(v):
        if i % 2 == 0:
            de[vv] += 1
        else:
            do[vv] += 1
    do = sorted(do.items(), key=lambda x: x[1], reverse=True)
    de = sorted(de.items(), key=lambda x: x[1], reverse=True)
    if do[0][0] == de[0][0]:
        if len(do) == len(de) == 1:
            print(min(de[0][1], do[0][1]))
        else:
            m = 10 ** 20
            if len(do) != 1:
                m = min(m, n // 2 - do[1][1] + n // 2 - de[0][1])
            if len(de) != 1:
                m = min(m, n // 2 - do[0][1] + n // 2 - de[1][1])
            print(m)
    else:
        print(n // 2 - do[0][1] + n // 2 - de[0][1])


