import operator
def solve():
  n = int(input())
  s = {}
  k = {}
  for i, x in enumerate(list(map(int, input().split(' ')))):
    if i % 2 == 0:
      s[x] = s.get(x, 0) + 1
    else:
      k[x] = k.get(x, 0) + 1
  s = sorted(s.items(), key=operator.itemgetter(1), reverse=True)
  k = sorted(k.items(), key=operator.itemgetter(1), reverse=True)
  if s[0][0] != k[0][0]:
    return (n / 2 - s[0][1]) + (n / 2 - k[0][1])
  else:
    if s[0][1] == n / 2 and k[0][1] == n / 2:
      return n / 2
    if s[0][1] > k[0][1]:
      return (n / 2 - s[0][1]) + (n / 2 - k[1][1])
    else:
      return (n / 2 - s[1][1]) + (n / 2 - k[0][1])
