def main(n, a):

    if 0 == n%2:
        even_list = [a[2*i] for i in range(0, int(n/2))]
        odd_list = [a[2*i+1] for i in range(0, int(n/2))]
    else:
        even_list = [a[2*i] for i in range(0, int(n/2)+1)]
        odd_list = [a[2*i+1] for i in range(0, int(n/2))]

    if len(set(even_list)) == 1 and len(set(odd_list)) == 1:
        if even_list[0] == odd_list[0]:
            print(int(n/2))
        else:
            print(0)
        return

    # print(even_list)
    # print(odd_list)
    col_even = collections.Counter(even_list)
    col_odd = collections.Counter(odd_list)
    sort_col_even = sorted(col_even.items(), key = lambda x: -x[1])
    sort_col_odd  = sorted(col_odd.items(),  key = lambda x: -x[1])
    # print(sort_col_even)
    # print(sort_col_odd)

    if sort_col_even[0][0] != sort_col_odd[0][0]:
        retval = n - ( sort_col_even[0][1] + sort_col_odd[0][1])
        print(retval)
    else:
        if sort_col_even[1][0] >= sort_col_odd[1][0]:
            retval = n - ( sort_col_even[0][1] + sort_col_odd[1][1])
        else:
            retval = n - ( sort_col_even[1][1] + sort_col_odd[0][1])
        print(retval)


if __name__ == '__main__':
    try:
