import sys

def DistanceFromVV(seq, elA, elB):
    """Return the number of edits required to make seq into a VV sequence
    using elA and elB as seq[0] and seq[1], respectively
    """

    dist = 0
    for i in range(0, len(seq), 2):
        if seq[i] != elA:
            dist += 1
    for j in range(1, len(seq), 2):
        if seq[j] != elB:
            dist += 1
    return dist

def CountElements(seq):
    count = {}
    for el in seq:
        if el in count:
            count[el] += 1
        else:
            count[el] = 1
    return count

def MinChanges(seq):
    """Return the minimum number of changes which must be made to the given 
    sequence in order to make it "VV"
    """

    element_count = CountElements(seq)
    elements_descending = sorted(element_count, 
                                 key=lambda key: element_count[key], 
                                 reverse=True)

    if (len(elements_descending) == 1):
        return len(seq) // 2

    best = len(seq) + 1
    for i in range(len(elements_descending)-1):
        for j in range(i+1, len(elements_descending)):
            changesA = DistanceFromVV(seq, elements_descending[i], 
                                      elements_descending[j])
            changesB = DistanceFromVV(seq, elements_descending[j], 
                                      elements_descending[i])
            best = min(best, changesA, changesB)
    return best

