    return [int(_) for _ in arys.split(' ')]

def solve(ary):
    if len(set(ary)) < 2:
        return len(ary) // 2

    freq = {}
    nums = list(set(ary))
    for _ in nums:
        freq[_] = ary.count(_)

    even, odd = [], []
    for i, _ in enumerate(ary):
        if i % 2 == 0:
            even.append(_)
        else:
            odd.append(_)

    if odd[0] != even[0] and len(set(odd)) == len(set(even)):
        return 0

    curr_max = 0
    most_freq_key = 0

    for n, f in freq.items():
        if curr_max < f:
            curr_max = f
            most_freq_key = n

    freq.pop(most_freq_key)

    curr_max = 0
    sec_freq_key = 0

    for n, f in freq.items():
        if curr_max < f:
            curr_max = f
            sec_freq_key = n

    e_size, o_size = len(even), len(odd)

    return min(e_size - even.count(most_freq_key)
               + o_size - odd.count(sec_freq_key),
               e_size - even.count(sec_freq_key)
               + o_size - odd.count(most_freq_key))


