from collections import Counter

class Solver(object):
    def __init__(self):
        self._input()
        self.solve()

    def _input(self):
        self.n = int(input())
        self.v_s = list(map(int, input().split(" ")))
        self.evens = []
        self.odds = []
        for i, v in enumerate(self.v_s):
            if i % 2 == 0:
                self.evens.append(v)
            else:
                self.odds.append(v)
        self.evens = Counter(self.evens)
        self.odds = Counter(self.odds)

    def solve(self):
        if max(self.evens.values()) > max(self.odds.values()):
            self.count_adjust(self.evens, self.odds)
        else:
            self.count_adjust(self.odds, self.evens)

    def count_adjust(self, major, minor):
        major_prime = (-1, -1)
        for x, count in major.items():
            if count > major_prime[1]:
                major_prime = (x, count)
        minor_prime = (-1, -1)
        for x, count in minor.items():
            if (count > minor_prime[1]) and (x != major_prime[0]):
                minor_prime = (x, count)
        ans = 0
        for x, count in major.items():
            if x != major_prime[0]:
                ans += count
        if minor_prime == (-1, -1):
            ans += list(minor.values())[0]
        else:
            for x, count in minor.items():
                if x != minor_prime[0]:
                    ans += count
        print(ans)


