import sys
import numpy as np


def get_histogram(arr):
    count_dic = {}
    appeared = []
    for i in arr:
        if i in appeared:
            count_dic[i] += 1
        else:
            appeared.append(i)
            count_dic[i] = 1
    return sorted(count_dic.items(), key=lambda x: x[1], reverse=True)


def count_replace(histogram, target):
    count = 0
    if target >= len(histogram):
        for h in histogram:
            count += h[1]
        return count
    for i, h in enumerate(histogram):
        if i != target:
            count += h[1]
    return count


def main(argv):
    n = int(input())
    nums_input = input()
    nums = list(map(lambda x: int(x), nums_input.split(' ')))

    hist_odd = get_histogram(nums[::2])
    hist_even = get_histogram(nums[1::2])

    if hist_even[0][0] != hist_odd[0][0]:
        print(count_replace(hist_even, 0) + count_replace(hist_odd, 0))
    else:
        if count_replace(hist_even, 1) > count_replace(hist_odd, 1):
            print(count_replace(hist_even, 0) + count_replace(hist_odd, 1))
        else:
            print(count_replace(hist_even, 1) + count_replace(hist_odd, 0))


if __name__ == "__main__":
    main(sys.argv[:1])

