def anser(n, p):
    # 例外① 全部同じ数
    if len(set(p)) == 1:
        return int(n/2)
    o = [t[1] for t in enumerate(p) if t[0] % 2 == 0]
    e = [t[1] for t in enumerate(p) if t[0] % 2 == 1]
    # 例外② すでにVMVMになっているもの ①以外なのでo!=e
    if len(set(o)) == 1 and len(set(e)) == 1:
        return 0
    # case ① 片一方は0
    if len(set(o)) == 1:
        return count(e)
    if len(set(e)) == 1:
        return count(o)
    return count(o)+count(e)

