def basket_count(arr):
    basket = []
    tmp = arr[0]
    cnt_ele = 0
    for ele in arr:
        if ele == tmp:
            cnt_ele += 1
        else:
            basket.append([tmp, cnt_ele])
            # reset count for basket
            tmp = ele
            cnt_ele = 0
    basket.append([tmp, cnt_ele])
    return basket

