fn solve() {
    let n = get!(usize);
    let xs = get!([usize]);

    let mut even = vec![0; 100001];
    let mut odd = vec![0; 100001];

    for (i, x) in xs.into_iter().enumerate() {
        if i % 2 == 0 {
            even[x] += 1;
        } else {
            odd[x] += 1;
        }
    }

    let mut v1: Vec<usize> = (0..100001).collect();
    let mut v2: Vec<usize> = (0..100001).collect();

    v1.sort_by_key(|&i| even[i]);
    v1.reverse();
    v2.sort_by_key(|&i| odd[i]);
    v2.reverse();

    let mut ans = n;
    for i in 0..2 {
        for j in 0..2 {
            if v1[i] != v2[j] {
                ans = min(ans, n - even[v1[i]] - odd[v2[j]]);
            }
        }
    }

    println!("{}", ans);
}

