fn solve(input: String) -> String {
    input!(input=>(n:usize)(list:[usize]));
    let a = {
        let mut vec = Vec::new();
        vec.resize(100001, 0);
        for (i, x) in list.clone().into_iter().enumerate() {
            if i % 2 == 0 {
                vec[x] += 1;
            }
        }
        let mut max_x = (0, 0);
        for (i, x) in vec.into_iter().enumerate() {
            if max_x.1 < x {
                max_x = (i, x);
            }
        }
        max_x
    };

    let b = {
        let mut vec = Vec::new();
        vec.resize(100001, 0);
        for (i, x) in list.clone().into_iter().enumerate() {
            if i % 2 == 1 {
                vec[x] += 1;
            }
        }
        let mut max_x = (0, 0);
        for (i, x) in vec.into_iter().enumerate() {
            if max_x.1 < x {
                max_x = (i, x);
            }
        }
        max_x
    };

    if a.0 == b.0 { n / 2 } else { n - a.1 - b.1 }.to_string()
}

