/// Rustで競技プログラミングの入力をスッキリ記述するマクロ
///
/// https://qiita.com/tanakh/items/0ba42c7ca36cd29d0ac8
macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

fn main() {
    input!{
        n: usize,
        v_a: [u64; n],
    }

    let mut v_o = HashMap::with_capacity(n/2);
    let mut v_e = HashMap::with_capacity(n/2);

    for v_p in v_a.chunks(2) {
        *v_o.entry(v_p[0]).or_insert(0) += 1;
        *v_e.entry(v_p[1]).or_insert(0) += 1;
    }

    let max_o = v_o.iter().max_by_key(|&(_, v)| v).unwrap();
    let max_e = v_e.iter().max_by_key(|&(_, v)| v).unwrap();

    let ans = if max_o.0 != max_e.0 {
        n - max_o.1 - max_e.1
    } else {
        let second_o = match v_o.iter()
            .filter(|&a| a != max_o)
            .max_by_key(|&(_, v)| v) {
                Some((_, second_o)) => *second_o,
                _ => 0,
            };

        let second_e = match v_e.iter()
            .filter(|&a| a != max_e)
            .max_by_key(|&(_, v)| v) {
                Some((_, second_e)) => *second_e,
                _ => 0,
            };

        std::cmp::min(n - second_o - max_e.1, n - max_o.1 - second_e)
    };

    println!("{}", ans);
}

