        vec.resize(100001, 0);
        for (i, x) in list.clone().into_iter().enumerate() {
            if i % 2 == 0 {
                vec[x] += 1;
            }
        }
        let mut max_x = (0, 0);
        for (i, x) in vec.into_iter().enumerate() {
            if max_x.1 < x {
                max_x = (i, x);
            }
        }
        max_x
    };

    let b = {
