    let stdin = std::io::stdin();
    if let Err(err) = stdin.read_line(&mut input_buffer) {
        error!("Cannot read a line from stdin: {}", err);
        return;
    }
    let input_buffer = input_buffer.trim();

    let sequence_length: usize = match input_buffer.parse() {
        Ok(n) => n,
        Err(err) => {
            error!("\"{}\" is not a positive integer: {}", input_buffer, err);
            return;
        },
    };

    if sequence_length == 0 {
        error!("The length has to be a positive (non-zero) even integer. ");
        return;
    }
    if sequence_length % 2 != 0 {
        error!("The length of sequence has to be even. ");
        return;
    }

    let mut input_buffer = String::new();
    if let Err(err) = stdin.read_line(&mut input_buffer) {
        error!("Cannot read a line from stdin: {}", err);
        return;
    }
    let input_buffer = input_buffer.trim();

    let sequence = input_buffer
        .split(' ')
        .map(|s| s.parse::<i32>())
        .collect::<Result<Vec<_>, _>>();
    let sequence = match sequence {
        Ok(s) => s, 
        Err(err) => {
            error!("\"{}\" are not integers: {}", input_buffer, err);
            return;
        }, 
    };

    if sequence.len() != sequence_length {
        error!("The length of sequence is different from reserved one: {} reserved, {} used. ", sequence_length, sequence.len());
        return;
    }

    let mut even_items: HashMap<i32, i32> = HashMap::new();
    let mut odd_items: HashMap<i32, i32> = HashMap::new();
    for pair in sequence.chunks(2) {
        *even_items.entry(pair[0]).or_insert(0) += 1;
        *odd_items.entry(pair[1]).or_insert(0) += 1;
    }
    let even_items = even_items;
    let odd_items = odd_items;

    let even_items_sorted: Vec<(i32, i32)> = even_items.into_iter().sorted_by(|a, b| a.1.cmp(&b.1)).rev().collect();
    let odd_items_sorted: Vec<(i32, i32)> = odd_items.into_iter().sorted_by(|a, b| a.1.cmp(&b.1)).rev().collect();

    let even_max = even_items_sorted[0];
    let odd_max = odd_items_sorted[0];
    if even_max.0 != odd_max.0 {
        println!("{}", sequence_length as i32 - (even_max.1 + odd_max.1));
    }
    else {
        let odd_max2 = *odd_items_sorted.get(1).unwrap_or(&(even_max.0 + 1, 0i32));
        let even_max2 = *even_items_sorted.get(1).unwrap_or(&(odd_max.0 + 1, 0i32));
        println!("{}", sequence_length as i32 - std::cmp::max(even_max2.1 + odd_max.1, even_max.1 + odd_max2.1));
    }
}

