            return;
        }
    }

    let mut vodd_vallist :HashMap<usize,usize> = HashMap::new();
    for j in 0..(n/2) {
        let count = vodd_vallist.entry(v[2*j]).or_insert(0);
        *count += 1;
    }
    let mut vodd :Vec<(usize,usize)> = vodd_vallist.iter().map(|(&x,&y)| (x,y) ).collect();
    vodd.sort_by(|&y,&w| (w.1).cmp(&y.1));


    let mut veven_vallist :HashMap<usize,usize> = HashMap::new();
    for j in 0..(n/2) {
        let count = veven_vallist.entry(v[2*j+1]).or_insert(0);
        *count += 1;
    }
    let mut veven :Vec<(usize,usize)> = veven_vallist.iter().map(|(&x,&y)| (x,y) ).collect();
    veven.sort_by(|&y,&w| (w.1).cmp(&y.1));

    let answer;
    if vodd[0].0 == veven[0].0 {
        if vodd.len() == 1 {
            if veven.len() == 1 {
                answer = n/2;
            } else {
                answer = n - vodd[0].1 - veven[1].1;
            }
        } else if veven.len() == 1 {
            answer = n - vodd[1].1 - veven[0].1;
        } else if vodd[1].1 > veven[1].1 {
            answer = n - vodd[1].1 - veven[0].1;
        } else {
            answer = n - vodd[0].1 - veven[1].1;
        }
    } else {
        answer = n - vodd[0].1 - veven[0].1;
    }

    println!("{}",answer);
}

