fn main() {
    let N = read!(usize);
    let V = read![[i32]];

    let mut kv = vec![];

    let mut s = 0;

    for p in 0..2 {
        let mut m = BTreeMap::new();

        for i in 0..N {
            if i % 2 != p {
                continue;
            }

            *m.entry(V[i]).or_insert(0) += 1;
        }

        let mut v = m.into_iter().map(|(k, v)| (v, k)).vec();

        v.push((0, 1_000_000));
        v.push((0, 1_000_001));
        v.sort();
        v.reverse();
        kv.push(v);
    }

    let mut i = 0;
    let mut j = 0;
    while kv[0][i].1 == kv[1][j].1 {
        if kv[0][i + 1].0 < kv[1][j].0 {
            i += 1;
        } else {
            j += 1;
        }
    }

    s += N - (kv[0][i].0 + kv[1][j].0);

    println!("{}", s)
}

fn solve<R: BufRead, W: Write>(_reader: R, _writer: &mut W) {
  let mut _scanner = Scanner::new(_reader);

  #[allow(unused_macros)]
  macro_rules! scan {
    ($T:ty) => {
      _scanner.next::<$T>().unwrap()
    };
    ($($T:ty),+) => {
      ($(scan!($T)),+)
    };
    ($($T:ty),+; $n:expr $(; $m:expr)*) => {{
      let mut vec = Vec::with_capacity($n);
      for _ in 0..$n {
        vec.push(scan!($($T),+ $(; $m)*));
      }
      vec
    }};
  }

  #[allow(unused_macros)]
  macro_rules! scan_iter {
    ($T:ty; $n:expr) => {
      _scanner.take::<$T>($n).map(|x| x.unwrap())
    };
  }

  #[allow(unused_macros)]
  macro_rules! print {
    ($fmt:expr) => {
      write!(_writer, $fmt).unwrap()
    };
    ($fmt:expr, $($arg:tt)*) => {
      write!(_writer, $fmt, $($arg)*).unwrap()
    };
  }

  #[allow(unused_macros)]
  macro_rules! println {
    ($fmt:expr) => {
      writeln!(_writer, $fmt).unwrap()
    };
    ($fmt:expr, $($arg:tt)*) => {
      writeln!(_writer, $fmt, $($arg)*).unwrap()
    };
  }

  #[allow(unused_macros)]
  macro_rules! eprint {
    ($fmt:expr) => {
      #[cfg(debug_assertions)]
      write!(::std::io::stderr(), $fmt).unwrap()
    };
    ($fmt:expr, $($arg:tt)*) => {
      #[cfg(debug_assertions)]
      write!(::std::io::stderr(), $fmt, $($arg)*).unwrap()
    };
  }

  #[allow(unused_macros)]
  macro_rules! eprintln {
    ($fmt:expr) => {
      #[cfg(debug_assertions)]
      writeln!(::std::io::stderr(), $fmt).unwrap()
    };
    ($fmt:expr, $($arg:tt)*) => {
      #[cfg(debug_assertions)]
      writeln!(::std::io::stderr(), $fmt, $($arg)*).unwrap()
    };
  }

  #[allow(unused_macros)]
  macro_rules! dump {
    ($($x:expr),+) => {
      eprint!("[{}:{}] ", file!(), line!());
      eprintln!(concat!($(stringify!($x), " = {:?}; "),+), $($x),+);
    };
  }

  use cmp::Reverse;
  use std::cmp;
  use std::time::{Duration, Instant};

  let now = Instant::now();

  let n = scan!(usize);
  let v = scan!(u64; n);

  let mut set = vec![0usize; (*v.iter().max().unwrap() + 1) as usize];
  for &v_i in &v {
    set[v_i as usize] += 1;
  }
  let mut vec = set.into_iter().enumerate().collect::<Vec<_>>();
  vec.sort_by_key(|&(_, x)| Reverse(x));
  let vec = vec.into_iter().map(&|(i, _)| i as u64).collect::<Vec<_>>();

  let mut ans = 114514usize;
  for goal in vec.chunks(2) {
    if now.elapsed() > Duration::from_millis(1800) {
      break;
    }
    dump!(goal);
    let temp = v
      .chunks(2)
      .map(|this| (this[0] != goal[0]) as usize + (this[1] != goal[1]) as usize)
      .sum();
    ans = cmp::min(ans, temp);
    let temp = v
      .chunks(2)
      .map(|this| (this[0] != goal[1]) as usize + (this[1] != goal[0]) as usize)
      .sum();
    ans = cmp::min(ans, temp);
  }
  println!("{}", ans);
}

