pub fn main() {
    let i = stdin();
    let mut o = Vec::new();
    run(i.lock(), &mut o);
    stdout().write_all(&o).unwrap();
}

fn run<R: BufRead, W: Write>(i: R, o: &mut W) {
    let mut i = CpReader::new(i);
    let n = i.read::<usize>();
    let v = i.read_vec::<usize>(n);

    writeln!(o, "{}", solve(&v)).unwrap();
}
fn solve(v: &[usize]) -> usize {
    let mut c0 = HashMap::new();
    let mut c1 = HashMap::new();

    for i in 0..v.len() {
        let c = if i % 2 == 0 { &mut c0 } else { &mut c1 };
        *c.entry(v[i]).or_insert(0) += 1;
    }

    let m0 = get_modify(c0);
    let m1 = get_modify(c1);

    if m0.key != m1.key {
        m0.count + m1.count
    } else {
        min(m0.count + m1.count_next, m0.count_next + m1.count)
    }
}
fn get_modify(m: HashMap<usize, usize>) -> Modify {
    let (&key1, &key_count1) = m.iter().max_by_key(|&x| x.1).unwrap();
    let sum: usize = m.values().sum();

    let key_count2 = if let Some((&_key2, &key_count2)) =
        m.iter().filter(|&x| *x.0 != key1).max_by_key(|&x| x.1)
    {
        key_count2
    } else {
        0
    };
    Modify {
        key: key1,
        count: sum - key_count1,
        count_next: sum - key_count2,
    }
}
#[derive(Debug)]
struct Modify {
    key: usize,
    count: usize,
    count_next: usize,
}

