    let mut map1 = BTreeMap::new();
    let mut map2 = BTreeMap::new();
    for i in 0..n{
        if i%2==0{
            *map1.entry(v[i]).or_insert(0) += 1;
        }else{
            *map2.entry(v[i]).or_insert(0) += 1;
        }
    }
    // k,v逆にしてVecに格納
