    for (i, &v) in vs.iter().enumerate() {
        if (i % 2 == 1) {
            od[v] += 1;
        } else {
            ev[v] += 1;
        }
    }

    let mut od1=(0,0);
    let mut od2=(0,0);
    let mut ev1=(0,0);
    let mut ev2=(0,0);

    for i in 0..100001 {
        if (od1.0 < od[i]) {
            od2 = od1;
            od1 = (od[i], i);
        } else if (od2.0 < od[i]) {
            od2 = (od[i], i);
        }

        if (ev1.0 < ev[i]) {
            ev2 = ev1;
            ev1 = (ev[i], i);
        } else if (ev2.0 < ev[i]) {
            ev2 = (ev[i], i);
        }
    }

    if (od1.1 != ev1.1) {
        n - od1.0 - ev1.0
    } else {
        n - max(od1.0 + ev2.0, od2.0 + ev1.0)
    }
}

