        cnts1[vs[i]] += 1;
        cnts2[vs[i+1]] += 1;
        i += 2;
    }

    let m1 = max_idx(&cnts1);
    let m2 = max_idx(&cnts2);

    if m1 != m2 {
        let ans = n as i64 - cnts1.iter().fold(&0, max) - cnts2.iter().fold(&0, max);
        println!("{}", ans);
    } else {
        cnts1.sort();
        cnts2.sort();
        let a = max(cnts1[(cnts1.len()-2) as usize], cnts2[(cnts2.len()-2) as usize]);
        let ans = n as i64 - cnts1.iter().fold(&0, max).clone() as i64 - a as i64;
