    }
}

fn max_idx(v: &Vec<i64>) -> usize{
    let mut ret = 0;
    let mut mx = 0;
    for i in 0..v.len() {
        if v[i] > mx {
            ret = i;
            mx = v[i];
        }
    }
    ret
}

