    ($fmt:expr, $($arg:tt)*) => {
      #[cfg(debug_assertions)]
      write!(::std::io::stderr(), $fmt, $($arg)*).unwrap()
    };
  }

  #[allow(unused_macros)]
  macro_rules! eprintln {
    ($fmt:expr) => {
      #[cfg(debug_assertions)]
      writeln!(::std::io::stderr(), $fmt).unwrap()
    };
    ($fmt:expr, $($arg:tt)*) => {
      #[cfg(debug_assertions)]
      writeln!(::std::io::stderr(), $fmt, $($arg)*).unwrap()
    };
  }

  #[allow(unused_macros)]
  macro_rules! dump {
    ($($x:expr),+) => {
      eprint!("[{}:{}] ", file!(), line!());
      eprintln!(concat!($(stringify!($x), " = {:?}; "),+), $($x),+);
    };
  }

  use cmp::Reverse;
  use std::collections::HashMap;

  let n = scan!(usize);
  let v = scan!(u64; n);

  let mut map = HashMap::new();
  for chunk in v.chunks(2) {
    if chunk[0] != chunk[1] {
      *map.entry((chunk[0], chunk[1])).or_insert(0) += 1;
    }
  }

  let pair = map.into_iter().max_by_key(|&(_, x)| x).map(|(x, _)| x).unwrap_or_else(|| {
    let mut set = vec![0usize; (*v.iter().max().unwrap() + 1) as usize];
    for &v_i in &v {
      set[v_i as usize] += 1;
    }
    let mut vec = set.into_iter().enumerate().collect::<Vec<_>>();
    vec.sort_by_key(|&(_, x)| Reverse(x));
    let max = vec[0].0 as u64;
    (max, vec.get(1).map(|&(x, _)| x as u64).unwrap_or(0u64))
  });

  dump!(pair);

  let mut ans = 0;
  for chunk in v.chunks(2) {
    if chunk[0] != pair.0 {
      ans += 1;
    }
    if chunk[1] != pair.1 {
      ans += 1;
    }
  }
  println!("{}", ans);
}

const CUSTOM_STACK_SIZE_MEBIBYTES: Option<usize> = None;

fn main() {
  if let Some(stack_size_mebibytes) = CUSTOM_STACK_SIZE_MEBIBYTES {
    let builder = thread::Builder::new()
      .name("exec_solver".to_string())
      .stack_size(stack_size_mebibytes * 1024 * 1024);
    builder.spawn(exec_solver).unwrap().join().unwrap();
  } else {
    exec_solver();
  }
}

fn exec_solver() {
  let stdin = stdin();
  let stdout = stdout();
  #[cfg(debug_assertions)]
  let mut writer = stdout.lock();
  #[cfg(not(debug_assertions))]
  let mut writer = ::std::io::BufWriter::new(stdout.lock());
  solve(stdin.lock(), &mut writer);
  writer.flush().unwrap();
}

use io::Scanner;
use std::io::{stdin, stdout, BufRead, Write};
use std::thread;

pub mod misc {
  pub use self::byte_char::*;
  pub use self::byte_string::*;

  mod byte_char {
    use std::fmt::{self, Debug, Display, Formatter};

    #[derive(Clone, Copy, PartialOrd, Ord, PartialEq, Eq, Hash)]
    pub struct ByteChar(pub u8);

    impl Debug for ByteChar {
      fn fmt(&self, f: &mut Formatter) -> fmt::Result {
        write!(f, "b\'{}\'", self.0 as char)
      }
    }

    impl Display for ByteChar {
      fn fmt(&self, f: &mut Formatter) -> fmt::Result {
        write!(f, "{}", self.0 as char)
      }
    }
  }

  mod byte_string {
    use misc::ByteChar;
    use std::fmt::{self, Debug, Display, Formatter};

    #[derive(Clone, PartialOrd, Ord, PartialEq, Eq, Hash)]
    pub struct ByteString(pub Vec<ByteChar>);

    impl Debug for ByteString {
      fn fmt(&self, f: &mut Formatter) -> fmt::Result {
        write!(f, "b\"")?;
        for &c in &self.0 {
          write!(f, "{}", c.0 as char)?;
        }
        write!(f, "b\"")
      }
    }

    impl Display for ByteString {
      fn fmt(&self, f: &mut Formatter) -> fmt::Result {
        for &c in &self.0 {
          write!(f, "{}", c)?;
        }
        Ok(())
      }
    }
  }
}

pub mod cmp {
  pub use self::reverse::*;

  mod reverse {
    use std::cmp::Ordering;

    #[derive(Clone, Copy, PartialEq, Eq, Default, Debug, Hash)]
    pub struct Reverse<T>(pub T);

    impl<T: PartialOrd> PartialOrd for Reverse<T> {
      fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        other.0.partial_cmp(&self.0)
      }
    }

    impl<T: Ord> Ord for Reverse<T> {
      fn cmp(&self, other: &Self) -> Ordering {
        other.0.cmp(&self.0)
      }
    }
  }
}

pub mod io {
  pub use self::from_bytes::FromBytes;
  pub use self::scanner::Scanner;

  mod from_bytes {
    use misc::{ByteChar, ByteString};
    use std::str::{self, FromStr};

    #[derive(Debug)]
    pub struct FromBytesError;

    pub trait FromBytes: Sized {
      type Err;

      fn from_bytes(bytes: &[u8]) -> Result<Self, Self::Err>;
    }

    impl FromBytes for ByteChar {
      type Err = FromBytesError;

      fn from_bytes(bytes: &[u8]) -> Result<Self, Self::Err> {
        if bytes.len() == 1 {
          Ok(ByteChar(*unsafe { bytes.get_unchecked(0) }))
        } else {
          Err(FromBytesError)
        }
      }
    }

    impl FromBytes for ByteString {
      type Err = FromBytesError;

      fn from_bytes(bytes: &[u8]) -> Result<Self, Self::Err> {
        Ok(ByteString(bytes.iter().cloned().map(ByteChar).collect()))
      }
    }

    impl<T: FromStr> FromBytes for T {
      type Err = T::Err;

      fn from_bytes(bytes: &[u8]) -> Result<Self, Self::Err> {
        let s = if cfg!(debug_assertions) {
          str::from_utf8(bytes).unwrap()
        } else {
          unsafe { str::from_utf8_unchecked(bytes) }
        };
        T::from_str(s)
      }
    }
  }

  mod scanner {
    use io::FromBytes;
    use std::io::BufRead;
    use std::marker::PhantomData;

    pub struct Scanner<R> {
      reader: R,
      buffer: Vec<u8>,
      position: usize,
    }

    impl<R: BufRead> Scanner<R> {
      pub fn new(reader: R) -> Self {
        Scanner {
          reader: reader,
          buffer: vec![],
          position: 0,
        }
      }

      pub fn next<T: FromBytes>(&mut self) -> Result<T, T::Err> {
        FromBytes::from_bytes(self.next_bytes().unwrap_or(&[]))
      }

      pub fn take<T: FromBytes>(&mut self, n: usize) -> Take<R, T> {
        Take {
          scanner: self,
          n: n,
          _marker: PhantomData,
        }
      }

      pub fn next_bytes(&mut self) -> Option<&[u8]> {
        if self.buffer.is_empty() {
          self.read_line();
        }
        loop {
          match self.buffer.get(self.position) {
            Some(&b' ') => self.position += 1,
            Some(&b'\n') => self.read_line(),
            Some(_) => break,
            None => return None,
          }
        }
        let start = self.position;
        loop {
          match self.buffer.get(self.position) {
            Some(&b' ') | Some(&b'\n') | None => break,
            Some(_) => self.position += 1,
          }
        }
        Some(&self.buffer[start..self.position])
      }

      fn read_line(&mut self) {
        self.position = 0;
        self.buffer.clear();
        self.reader.read_until(b'\n', &mut self.buffer).unwrap();
      }
    }

    pub struct Take<'a, R: 'a, T> {
      scanner: &'a mut Scanner<R>,
      n: usize,
      _marker: PhantomData<fn() -> T>,
    }

    impl<'a, R: BufRead, T: FromBytes> Iterator for Take<'a, R, T> {
      type Item = Result<T, T::Err>;

      fn next(&mut self) -> Option<Self::Item> {
        if self.n > 0 {
          self.n -= 1;
          Some(self.scanner.next())
        } else {
          None
        }
      }

      fn size_hint(&self) -> (usize, Option<usize>) {
        (self.n, Some(self.n))
      }
    }

    impl<'a, R: BufRead, T: FromBytes> ExactSizeIterator for Take<'a, R, T> {}
  }
}

use std::collections::HashMap;
use itertools::Itertools;

#[macro_use]
macro_rules! error {
    ($($arg:tt)+) => (
        println!($($arg)+);
    )
}

fn main() {
    let mut input_buffer = String::new();
    let stdin = std::io::stdin();
    if let Err(err) = stdin.read_line(&mut input_buffer) {
        error!("Cannot read a line from stdin: {}", err);
        return;
    }
    let input_buffer = input_buffer.trim();

    let sequence_length: usize = match input_buffer.parse() {
        Ok(n) => n,
        Err(err) => {
            error!("\"{}\" is not a positive integer: {}", input_buffer, err);
            return;
        },
    };

    if sequence_length == 0 {
        error!("The length has to be a positive (non-zero) even integer. ");
        return;
    }
    if sequence_length % 2 != 0 {
        error!("The length of sequence has to be even. ");
        return;
    }

    let mut input_buffer = String::new();
    if let Err(err) = stdin.read_line(&mut input_buffer) {
        error!("Cannot read a line from stdin: {}", err);
        return;
    }
    let input_buffer = input_buffer.trim();

    let sequence = input_buffer
        .split(' ')
        .map(|s| s.parse::<i32>())
        .collect::<Result<Vec<_>, _>>();
    let sequence = match sequence {
        Ok(s) => s, 
        Err(err) => {
            error!("\"{}\" are not integers: {}", input_buffer, err);
            return;
        }, 
    };

    if sequence.len() != sequence_length {
        error!("The length of sequence is different from reserved one: {} reserved, {} used. ", sequence_length, sequence.len());
        return;
    }

    let mut even_items: HashMap<i32, i32> = HashMap::new();
    let mut odd_items: HashMap<i32, i32> = HashMap::new();
    for pair in sequence.chunks(2) {
        *even_items.entry(pair[0]).or_insert(0) += 1;
        *odd_items.entry(pair[1]).or_insert(0) += 1;
    }
    let even_items = even_items;
    let odd_items = odd_items;

    let even_items_sorted: Vec<(i32, i32)> = even_items.into_iter().sorted_by(|a, b| a.1.cmp(&b.1)).rev().collect();
    let odd_items_sorted: Vec<(i32, i32)> = odd_items.into_iter().sorted_by(|a, b| a.1.cmp(&b.1)).rev().collect();

    let mut even_max = even_items_sorted[0];
    let mut odd_max = odd_items_sorted[0];
    if even_max.0 == odd_max.0 {
        if even_max.1 >= odd_max.1 {
            odd_max = *odd_items_sorted.get(1).unwrap_or(&(even_max.0 + 1, 0i32));
        }
        else {
            even_max = *even_items_sorted.get(1).unwrap_or(&(odd_max.0 + 1, 0i32));
        }
    }

    let even_cnt =  even_items_sorted.iter().fold(0, |acc, x| acc + (if *x != even_max { x.1 } else { 0 }));
    let odd_cnt =  odd_items_sorted.iter().fold(0, |acc, x| acc + (if *x != odd_max { x.1 } else { 0 }));
    println!("{}", even_cnt + odd_cnt);
}

macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        input_inner!{iter, $($r)*}
    };
    ($($r:tt)*) => {
        let s = {
            use std::io::Read;
            let mut s = String::new();
            std::io::stdin().read_to_string(&mut s).unwrap();
            s
        };
        let mut iter = s.split_whitespace();
        input_inner!{iter, $($r)*}
    };
}

macro_rules! input_inner {
    ($iter:expr) => {};
    ($iter:expr, ) => {};

    ($iter:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($iter, $t);
        input_inner!{$iter $($r)*}
    };
}

macro_rules! read_value {
    ($iter:expr, ( $($t:tt),* )) => {
        ( $(read_value!($iter, $t)),* )
    };

    ($iter:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($iter, $t)).collect::<Vec<_>>()
    };

    ($iter:expr, chars) => {
        read_value!($iter, String).chars().collect::<Vec<char>>()
    };

    ($iter:expr, usize1) => {
        read_value!($iter, usize) - 1
    };

    ($iter:expr, $t:ty) => {
        $iter.next().unwrap().parse::<$t>().expect("Parse error")
    };
}

fn main() {
    input! {
        n: i32,
        v: [i32; n]
    }

    use std::collections::BTreeMap;

    let mut even_count : BTreeMap<i32, i32>= BTreeMap::new();
    let mut odd_count : BTreeMap<i32, i32> = BTreeMap::new();

    for (i, x) in v.iter().enumerate() {
        if i % 2 == 0 {
            *even_count.entry(*x).or_insert(0) += 1;
        } else {
            *odd_count.entry(*x).or_insert(0) += 1;
        }
    }

    let mut es = even_count.iter().map(|(k, v)| (*v, *k)).collect::<Vec<_>>();
    let mut os = odd_count.iter().map(|(k, v)| (*v, *k)).collect::<Vec<_>>();

    es.sort();
    es.reverse();
    os.sort();
    os.reverse();

    es.push((0, -1));
    os.push((0, -1));

    let ans = if es[0].1 != os[0].1 {
        n - es[0].0 - os[0].0    
    } else {
        n - std::cmp::max(es[0].0 + os[1].0, os[0].0 + es[1].0)
    };

    println!("{}", ans);
}

use std::io::{self, BufRead};
use std::collections::HashMap;
use std::cmp::min;

fn main() {
  let stdin = io::stdin();
  let mut lines = stdin.lock().lines();
  let _: usize = lines.next().unwrap().unwrap().parse().unwrap();
  let vs: Vec<usize> = lines.next().unwrap().unwrap().split(' ').map(|x| x.parse().unwrap()).collect();
  let mut xs: HashMap<usize, usize> = HashMap::new();
  let mut ys: HashMap<usize, usize> = HashMap::new();
  for i in 0..vs.len() {
    let k = vs[i];
    if i % 2 == 0 {
      xs.insert(k, xs.get(&k).unwrap_or(&0) + 1);
    } else {
      ys.insert(k, ys.get(&k).unwrap_or(&0) + 1);
    }
  }
  let (kx, vx) = xs.iter().max_by(|x, y| x.1.cmp(y.1)).unwrap();
  let (ky, vy) = ys.iter().max_by(|x, y| x.1.cmp(y.1)).unwrap();
  let nx = (vs.len() + 1) / 2 - vx;
  let ny = vs.len() / 2 - vy;
  let ans = if kx != ky {
    nx + ny
  } else {
    let zero = 0;
    let (_, vx2) = xs.iter().filter(|k| *k.0 != *kx).max_by(|x, y| x.1.cmp(y.1)).unwrap_or((&zero, &zero));
    let (_, vy2) = ys.iter().filter(|k| *k.0 != *ky).max_by(|x, y| x.1.cmp(y.1)).unwrap_or((&zero, &zero));
    let nx2 = (vs.len() + 1) / 2 - vx2;
    let ny2 = vs.len() / 2 - vy2;
    min(nx + ny2, nx2 + ny)
  };
  println!("{}", ans);
}
